/* 平成13年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h13.committeeSessions.push(...[{"id":"h13-20011012-4","meetingId":"h13-c-settlement","date":"2001年10月12日","dateIso":"2001-10-12","committee":"決算特別委員会","time":"午前１０時０５分～午後６時０８分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を97件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"初めに、１点目にやりたいことは、契約および権限委譲について触れていきたいと考えています。本年４月より事業部制を導入いたしました。管理職の方々も活発に行動されていることと思いますが、実感としてどのように変わってきたのか、また、今後どのランクの職員にまで権限委譲を図り、職員の意識改革を図っていこうとされているのか、今後の計画または考え方、それを教えていただきたいと思います。","respondent":"中尾根企画部長","answer":"委員のまずお尋ねの事業部制の実施の実感ですけれども、事業部制は昨今自治体の経営能力が問われている中にありまして、柔軟かつ機動的な対応、そのことによって能力を図ろうということで導入したものでございまして、組織の自立と責任を高めていくということで導入いたしました。","id":"exchange-001"},{"speaker":"石田委員","kind":"質問・要望","question":"通話料は別ですけれども、今携帯電話なんかは、自分たちのチームの経費となるわけですから、そういう意識づけができてきて、全部ただのものを探してくるというようなものになってきた。これはどういう形かというと、意識が変わってきたというのは、その３人、５人の中で、自己評価をさせるわけですね。だから、区長の意思も、多分ずっと一職員にまで浸透させなくてはならない。","respondent":"中尾根企画部長","answer":"権限の委譲と責任、ないしは職員のそういう信頼の関係といいますか、組織の運営体制の問題だと思いますけれども、委員ご指摘のとおり、行政といえども、やはり民間の視点、ないしは区民の感覚、こういうものを持って仕事に当たらなければならない。","id":"exchange-002"},{"speaker":"石田委員","kind":"質問・要望","question":"物を買っている、または発注しているんだということですね。今度の場合は、税金で皆さん発注なり、物を買っていくわけですから、その意識づけということは、必ず浸透させていただきたい。このやっぱり契約というのを、公平性を確保するとか、透明性を拡大していくとか、そういう意味が非常に大切になってくると思うんですが、そこら辺のところの考え方をちょっとお聞かせいただきたい。","respondent":"高橋区長","answer":"しかしながら、これが実施に入りますと、部長に移された権限を課長に移す、課長の権限を係長に移す、係長が今度各職員の自己管理に任せると、こういう手法が順次浸透していくものと考えています。それはそんなに長い期間かからずに、私はできると思っています。","id":"exchange-003"},{"speaker":"石田委員","kind":"質問・要望","question":"この中で、契約の中で、幾つかちょっとお聞きをしたいのは、まず予定価格の根拠ですね、これの決め方はどうなっているのかなというあれがあります。予定価格が3,２００万円だった。この理由は、どうであったかということを考えているのか、それを教えていただきたい。物品購入ももちろんあると思いますが、工事もあると思いますが、それぞれの比率を教えていただければと思います。","respondent":"本間総務部長","answer":"非常に予定価格に比べまして安く落ちた理由として考えられますことは、これは制限つき一般競争入札で行いました。","id":"exchange-004"},{"speaker":"石田委員","kind":"質問・要望","question":"物品購入については、今の見積もり合わせという話で、今出てきた物価の動向というのは、先ほどもお話をしましたが、自分のお金で物を買うとなれば、もっと調べるのではないのかなと私は思っておりまして、これについても例えば業者に買わされないで、区が主体的にもし購入をするということであれば、随意契約の枠を広げるとか、見積もり合わせの比率を考えていくということが私は必要だと思いますが。","respondent":"本間総務部長","answer":"こういう適用につきまして、検討をしてまいりたいと、このように考えているところです。","id":"exchange-005"},{"speaker":"石田委員","kind":"質問・要望","question":"今のお答え、ほんとうにそれをやっていただきたいなと考えています。ここでもう一点、最終的に確認をしたいんですが、必ずできるところというのはあるはずなんですね。今、1,０００万円というお話もありましたけれども、できるところから手段を工夫して、手をつけていただきたい。これに対するご見解をひとつお願いいたします。","respondent":"高橋区長","answer":"そのときには、随意契約にすれば安くできるんじゃないかということになりますけど、そこまで業者をたたいちゃいますと、今度少し景気がよくなったときに、品川区にだれも業者が来なくなってしまいますので、やはり、業者が来やすい、また、業者も損をしない、品川区も損をしない。","id":"exchange-006"},{"speaker":"石田委員","kind":"質問・要望","question":"教育については、公教育という形のものは、教育委員会として、どういうふうな形で交流をしてもいいんではないかというような観点からいきたいと思いますが、最初にまず教えていただきたいのは、現在の区立小学校から私立中学校に行く子どもの割合、また、私立に行く子どもたちも、中学校でありますから、義務教育であると思うんですが、この子どもたちも公教育の中に入ると思いますが。","respondent":"指田教育次長","answer":"区立小学校から私立中学校への進学率のお尋ねですけども、平成１２年度を見ますと、卒業生2,０９８人のうち、私立中学校へ進学した方が４３２名、率にしますと、２0.６％という状況です。","id":"exchange-007"},{"speaker":"石田委員","kind":"質問・要望","question":"今のお話の中で、約２割の子どもが区立小学校から私立中学校へ行くということでありまして、我々の子どものころはそんなにいなかったんじゃないのかなと思いますが、多種多様の中でそういう選択肢も生まれてきているということであります。公立中学校を選ばないで、私立中学校へ行くわけでありますから、その理由とかいうものを教育委員会のほうでは把握をしているのかどうか、教えていただきたい。","respondent":"指田教育次長","answer":"一般的なお答えになるかとも思いますけれども、やはり、私立中学に行くというふうなところにつきましては、公立学校で見られないような校風だとか、あるいはカリキュラムを含めた教育内容、さらには中学・高校・大学といったようなシステム的なことなど。","id":"exchange-008"},{"speaker":"石田委員","kind":"質問・要望","question":"私がここで言いたいのは、約２割のお子さんがそういう形の中で区立小学校にもいる、そこで区立小学校の授業を受けて勉強しているわけですよね。それで、中学校にも行く。ここら辺、私学の中学校ですよね、今の話になってくると、そこら辺にも学ぶことはあると思うんですが、ここら辺を踏まえて、交流をしているとか、していないとか、そこら辺の学ぶことはあるのか、そこら辺のことをちょっとお聞きをしたい。","respondent":"指田教育次長","answer":"前後するかもわかりませんけれども、私どももご承知のとおり教育改革プラン２１を進めてきてあります。","id":"exchange-009"},{"speaker":"石田委員","kind":"質問・要望","question":"そういう選択肢の財産を増やしていくというか、教師についてもそういうことを増やしていくということが進路指導ということで言っているわけじゃなくて、それはそういう財産を増やすことをさせていく、これが公教育であって、私はそういうことの公教育のために、もっともっと交流を増やしていくということが、その先生にとっての意識づけにもなると思うんで、それは教育委員会としては。","respondent":"若月教育長","answer":"今委員がこれもご指摘になりました、例えば、私立の学校で不登校に陥って、本区の公立の学校に来る、そういった場面では、私立の先生も公立の先生も全く無関係で、その子どもをやりとりしているという現状はありません。","id":"exchange-010"},{"speaker":"石田委員","kind":"確認","question":"私学ですと、生活文化局私学部行政課と、こういうところがやっているそうなんですが、ここら辺が何かこういうことを、例えば品川区の教育委員会がこういうことをやるよというときに、まさか注文はつけて来ないと思うんですが、そういうところが、品川区がこういう独自のものをやるというときに、結構そこの二つのところとか、そういうところが何かいろいろ注文をつけてくるのかどうか。","respondent":"若月教育長","answer":"私立もしっかりしないと、また、それこそ公立に負けちゃうぞという主張でありまして、私たちに何かを言うというよりも、私学自身も頑張ろうというような意気込みの込められた文章のほうが多いというのが現状です。","id":"exchange-011"},{"speaker":"石田委員","kind":"質問","question":"そういう子に対する、逆に、学校でずっといるわけですから、それは区立小学校にいるわけですから。教育費でも私やらせてもらった。そうなると、その子どもたちが生意気になってきて、学校の宿題はやらないとか、試験も適当にやっておけばいいやと、学校の授業なんか関係ないやというような風潮が私はその部分のところについては、その子どもたちにはあると思うんですが、そこら辺はどうお考えになっているか。","respondent":"指田教育次長","answer":"教育改革を進めて、まだ間もないという時期です。今お話がございました。","id":"exchange-012"},{"speaker":"石田委員","kind":"質問・要望","question":"ですから、そういう形の中で、公教育というとらえ方をするんであれば、品川の教育委員会として、そこら辺を含んで習熟度なのか、今度週五日制に変わるわけですけれども、そこら辺のところに手を入れていかないと、その子たちの３年間なり、そういうものはどうするんだ。常に学校で１番でいいのか。常に１００点、１番でいいのか。そこら辺のところもよくお考えになっていただきたい。","respondent":"若月教育長","answer":"当然、今やっているその実践を通して、これからさまざまな子どもたちのニーズに応えられるような教育活動を展開してまいりたいと、こんなふうに考えているところです。","id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問","question":"石田委員に引き続き、自民党を代表して総括質疑をします。私のほうから大きく４点質問をします。初めに、仮称保育園ＰＴＡのことについてお伺いします。そこでお伺いしたいのは、区長が昔いろいろたくさん批判された、ある意味で、最もこのことについては辛らつにおっしゃられたと思うんですが、ここに至って、区長のまず感想をお聞かせください。お願いいたします。","respondent":"小沼福祉事業部長","answer":"２点目の今後の進め方の問題とも関係してくるわけですけれども、今私のほうも各園で実施状況について、それぞれヒアリング、あるいは状況はどうであったというようなことも聞いてあります。","id":"exchange-014"},{"speaker":"伊藤委員","kind":"質問","question":"といいますのは、当然品川区の公立の保育園ですから、保護者との関係を十二分に構築をしていく必要がある、とはいうものの、今部長の答弁の中にありましたようにいろんな思いがある。具体的には、これは公営住宅法の改正が必要だということはわかってはおりますけれども、お伺いするのは、まず収入超過の具体例をプライバシーに配慮しながら教えてくださいということが一つ。お願いいたします。","respondent":"山室住宅指導担当部長","answer":"区としても、こうした取り組みを注視しまして、都と連携するとともに、区としてのあり方について検討し、環境を整えたものから改革をしていきたいというふうに考えております。","id":"exchange-015"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、課税ベースで言えば、確かに２件なんでしょうけれども、おそらく資産等を含めた実質所得とか、ほかのさまざまな収入をあわせていきますと、この数字はもっと増えていく可能性が十分あると私たちは思っております。ですから、大変厳しい競争率がある。お願いいたします。","respondent":"山室住宅指導担当部長","answer":"できることと、それから今すぐできることと、それから法制度等を改正していかなければいけない、その中での対応をしていかなければいけないということと２点あるわけですが、できることにつきましては、今申し上げたとおりの取り組みをしておりまして。","id":"exchange-016"},{"speaker":"伊藤委員","kind":"質問・要望","question":"公営住宅を建設するコストと、それからこういうふうな問題を改善していくコストを考えていきますと、どう考えても新しく建設するよりは、現状の問題を解決していったほうがはるかに社会的な公平さも担保できますし、費用対効果も十二分に保つことができると私たちは考えているわけですので、頭では理解しますけれども、法改正が必要だということ、それから必要な形、頭では理解していますけれども、でも。","respondent":"野本環境清掃事業部長","answer":"したがいまして、この共同組合が処理する事務の中には、今お話ししたように、時限的なものと恒久的というふうに言っていいのかどうか、今の段階では６年という時限からは離れて存続する可能性が高いものと、こういうふうに二つあって、それらをあわせて。","id":"exchange-017"},{"speaker":"伊藤委員","kind":"質問","question":"今の部長の答弁をお伺いしながら、区長が言い続けてきた内容と若干温度差を感じます。区長、答弁ありましたら、お願いいたします。","respondent":"高橋区長","answer":"だけど、それを即各区が実施するには、初めは困難だろう。だけど、一定の期間が過ぎたら、それを一遍各区に戻す、このような取り決めがなければうちは賛成できませんということははっきり申し上げました。","id":"exchange-018"},{"speaker":"伊藤委員","kind":"質問","question":"私ども、特に自民党はそうですけど、これは解散すべきだと言い続けてきておりますし、自区内、たまたま品川区はし尿もありますし、それから清掃工場を持っているわけですから、これは品川区の独立した自治体としてやるべき仕事であるということをずっと言い続けてきておりますので、多少部長の答弁を聞いて不安になったところがあるんですが、区長の答弁を聞いて安心したです。お願いいたします。","respondent":"市岡企画財政課長","answer":"発行額の総額ですが、平成１２年、１３年、ここまでで約５０５億円、それから今回紹介をいたしましたが、あと９７８億円程度予定をしているということで、総額あわせますと1,４８３億円余という大きな金額になります。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"質問","question":"７億1,０００万円余の共同処理期間中の負担金です。平成１２年度で品川区は１５億4,６００円余の負担金を今しているわけですから、これに加えて７億円、財調算定されるということですからあれなんでしょうけど、それからいろいろ考えていきますと、共同処理後の対応を私たちは考えていくわけであります。お願いいたします。","respondent":"市岡企画財政課長","answer":"なお、これは共同処理後、例えば大井工場等の関連の起債償還額が多額になった場合も、これは一つの心配なんですが、これもそういう心配があろうということで、平成１２年の都区財調の協議の中では、こういう清掃の経費が５２％を上回るような事態になった場合には。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問","question":"ですが、この工場のさまざまな現状をお伺いすると、東京都内の下水道の進捗はしているということ、それからビルピット汚泥等の民間処理委託等で確実に処理数は減少しているという説明を受けましたし、実際私たちが工場を見させていただいた中での工場のいわゆる稼働率というんですか、６割前後だったです。ですから、これを果たして一部事務組合で抱えていくことが正しいことなんだろうか。お願いいたします。","respondent":"野本環境清掃事業部長","answer":"持っていれば持っているほど、１キロリットル当たりのコスト単価というのはどんどん反比例的に上がってきますから、これは考え方で、逆に言えば、民間のほうでああいうものを活用することによって、業務内容を変更したり拡大するというような道があり得るならば。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問・要望","question":"この話も、近未来といいましょうか、将来のことでもありますので、今部長がおっしゃったような答弁も含めて十二分に検討していってくださいということをここでは要望します。それから次に、特別区人事厚生事務組合について質問をします。その背景には、安定した身分保障制度をすることによって、いわゆる全体の奉仕者としての仕事をしていただきたいというふうなことが求められていると考えています。","respondent":"高橋区長","answer":"その発言をしたとき、脱退もできないんだ。じゃあ、納付金を納めないよとまで言って、やっとこの問題を解決したことがあります。こういう問題で、現在共通基準というのは、品川区の人事にとって、人事制度にとって、果たして必要かと考えますと、私は必要ないと思っています。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、例えば３２万人の品川区、それから世田谷区は７０万人ですか、余りにも大都市なところがなぜ共通基準でやっているのかという疑問がずっとあるわけですので、これはうがった見方かもしれませんが、ある意味東京都が２３区をコントロールするために置いているのではないかということ。ですから、これからのことでありますけれども、今脱退ということをお話しされました。","respondent":"高橋区長","answer":"だから、２３区で私と同じような考えを持っている区長はかなりいると思います。だけど、表面に立って、このように言うばかな区長は少ないんじゃないかなという気がしてならないわけです。","id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問","question":"この問題の原点は、何のための地方自治かということから始まっていると思います。一部事務組合のための共通基準とか地方自治ではなくて、各区に住んでいる区民のための地方自治なわけですから、非常に高橋区長の思いは伝わってきました。ですから、できれば、これをそれぞれの区、区長が、特に区長が各区の区民のために取り組んでいただきますようにお願いしておきます。改めて区長の決意をお伺いいたします。","respondent":"高橋区長","answer":"しばしば申し上げておりますが、区の施策を進めていく基本は財政と人です。人事です。人間で言いますと、両足をしっかり地につけて、行政をしていかなくちゃならないと思います。したがいまして、その基本は忘れずにひとつこれからもやってまいりたいと考えています。","id":"exchange-024"},{"speaker":"伊藤委員","kind":"質問・要望","question":"いろいろ発言がありましたけれども、区長の大きな思いは伝わってきましたので、ぜひ大胆に進めていっていただきますように、お願いいたします。どうぞ、この我が自民党品川区議団の意を十二分におくみ取りいただきまして、平成１４年度予算に生かしていただきますように、大きな要望をお願いいたしまして総括質疑を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"山路委員","kind":"質問","question":"私は区議会公明党を代表して総括質問を行います。質問の内容は、ＩＴ講習会について、文化芸術の振興について、水と緑の市町村交流事業について、高齢者の居住の安定確保に関する法律に関連してお伺いいたします。はじめに、ＩＴ講習会についてであります。そこで、１点目の質問は、ＩＴ講習会の進捗状況について。品川区において、当初計画されたとおりに推進しているかどうか、お伺いいたします。","respondent":"中尾根企画部長","answer":"しかし、秋になりまして、また再び2,３１０人の予定のところ、１００％応募していますので、現状にいたしましては、夏の見込みの分はありますけれども、ほぼ計画どおり推移している、このように受けとめてあります。","id":"exchange-026"},{"speaker":"山路委員","kind":"質問・要望","question":"このＩＴ講習会は、当初１万1,０００人、目標達成ということで、事業のスタートを切られたわけなんですが、最後のもう一回、冬季が残っているわけなんですけど、何とかして１万1,０００人は達成していってもらいたいと思うんですが、その中身の展開といたしまして、夏季にちょっと少なかったということなんですが、今まで受講した人の意見とか要望とか。","respondent":"中尾根企画部長","answer":"最後の冬の分が残ってありますけれども、冬の予定は2,４００人をやはり予定しています。この見込みですけれども、過去３回やった中での2,０００人台の予定ということでしたら、これはそのレベルであれば、応募需要は十分あるかな、このように受けとめてあります。","id":"exchange-027"},{"speaker":"山路委員","kind":"質問","question":"何とか１万1,０００人をクリアする見込みということなんですが、万が一定員を割ったときに、２回目の受講をしたいという人がいらっしゃった場合、そういうときに私は２回目でもいいんじゃないかという考えを持っているんですが、その辺はどういうふうにお考えでしょうか。","respondent":"中尾根企画部長","answer":"したがいまして、現在では２回目もあいていたら受けたいという方については、受けられる仕組みになっておりまして、品川区におきましても、既にそういう体制で取り組んでいるところです。","id":"exchange-028"},{"speaker":"山路委員","kind":"質問・要望","question":"何としても１万1,０００人の大成功していただきたいと思います。パソコンを作動しているお母さんたちが、操作に困ってしまい、ちょっと手伝ってもらいたいとき、学校のコンピュータ室に行って、また講習を受けるなり、あるいはアドバイスをしてもらうなりができるような相談員、仮称パソコンお助けマン制度を設置したらどうかと思うものでありますが、どのようにお考えでしょうか、お伺いいたします。","respondent":"指田教育次長","answer":"したがいまして、来年度、初級コースということを１２時間コースに例えるとすれば、やはり、一段上のグレードアップした中級コース的なものをこれから考えていかなければいけないだろうと、このように思ってあります。","id":"exchange-029"},{"speaker":"山路委員","kind":"提案","question":"どうぞよろしくお願いいたします。３点目は、身障者でＩＴ講習会を受講し、パソコン購入の希望者にパソコン代を補助する制度の導入についてお伺いいたします。受講後、パソコン購入を希望している人がいるともお伺いしましたが、私はパソコン代をこういう方に補助してもよいのじゃないかと提案するものですが、ご見解をお伺いいたします。","respondent":"中尾根企画部長","answer":"こうした背景から、国におきましても、積極的に何らかの対策をしていきたいというようなことで、支援策の動きもあります。したがいまして、これら国・都などの動向も十分見極めながら、具体的な検討を今後進めてまいりたいと、このように考えているところです。","id":"exchange-030"},{"speaker":"山路委員","kind":"質問","question":"文化芸術についてお伺いいたします。その中の一つとして、新進若手芸術家の育成支援を挙げております。そこで質問の第１点目は、ここで言われている地域からの芸術活動の振興を図る、あるいは文化活動への支援策について、どんな公的支援策を想定されているのか、お伺いしたいと思います。","respondent":"中尾根企画部長","answer":"具体的には、一番目の多様な文化の支援といたしましては、青少年の文化活動への支援策、これが総合実施計画上に乗ってありますし、２番目の場の整備の部分におきましては、幅広い文化活動ができるように、これから文化センターを整備していきたいという計画にあります。","id":"exchange-031"},{"speaker":"山路委員","kind":"提案","question":"質問の第２点目に当たりまして、「仮称全員集まれ、若手芸術家品川まつり」の開催の提案をさせていただきたいと思います。そして、最後にそれぞれ団体や個人の優秀者を表彰するなど、若手芸術家への場の提供、激励など、公的支援の一環としてはどうかと考えるものですが、ご所見をお聞かせいただきたいと思います。","respondent":"中尾根企画部長","answer":"委員はこうした事業を区が行っているというのを十分承知の上でさらに、こういう新しい提案というふうにされているとは思いますけれども、既存のそういう事業との融和等も含めまして、何か新しい趣旨を生かす事業があり得るかどうか十分検討していきたい。","id":"exchange-032"},{"speaker":"山路委員","kind":"提案","question":"私は、品川が古きよき伝統や歴史的遺産の保存の宝庫であると確信しているものでありますので、もっと多くの人に品川の文化の伝統や歴史を公開、拝観してもらうために、インターネット上にホームページを開設し、公開可能な作品を掲載し、発信することは、文化芸術振興にとって、大きな役割を果たすものと考えますが、どのようにお考えでしょうか、ご意見を賜りたいと思います。","respondent":"指田教育次長","answer":"私どものほうも、１１月を目途にいたしまして、今教育委員会としてのホームページを開設する予定でおります。","id":"exchange-033"},{"speaker":"山路委員","kind":"質問","question":"水と緑の市町村との交流事業についてお伺いいたします。平成１３年度、事務事業評価結果のまとめや、款別審査の質問を踏まえた上で、我が党は、交流事業の継続発展を願う立場から、改めてお尋ねしたい点は、区の財政負担をより少なくして、交流事業を継続発展させていくためのどんな自助努力を双方に期待しているのかということであります。ご所見をお伺いいたします。","respondent":"小栗区民生活事業部長","answer":"自然体験を中心とした魅力ある事業を実施して、利用者の増を図り、収入増と経費の削減を図っているところです。早川町につきましては、親子で田植え、稲刈り体験や渓流釣り、ホタルを鑑賞する会など、たくさんの交流事業を実施しております。","id":"exchange-034"},{"speaker":"山路委員","kind":"提案","question":"これまでの交流をさらに発展させるため、以下数点提案をさせていただきたいので、後ほどご見解を賜りたいと思います。提案の２点目は、区内の小・中学校の児童・生徒を対象に、夏休み期間を利用したサマースクールを実施し、キャンプや釣り、野生体験など、都会では味わえない貴重な体験をしてもらうようにしてはどうか。あきがありました。それぞれご所見を求めたいと思います。","respondent":"小栗区民生活事業部長、新美保健高齢事業部長、指田教育次長","answer":"したがいまして、ご提案の短期サマースクールにつきましては、受入先の早川町、あるいは早川の北小学校等の意向もありますので。私からは、３点目と４点目のご提案についてお答えいたします。早川町での実施というふうなこと、事務事業評価でもございましたように、コストの問題あるいは活動の内容の問題。","id":"exchange-035"},{"speaker":"山路委員","kind":"提案","question":"品川区で、島倉千代子さんが見えるんで、私たちもぜひ行かせていただきたいというご意見を現場でお聞きしてまいりましたので、その点も加えて要望しておきますので、どうぞよろしくお願い申し上げます。最後に、区長にお伺いいたします。今後、この事業を拡大し、充実させようとすると、現在の職員体制では限度があるのではないかと思います。今後コマーシャルベースになっていくことも予想されます。","respondent":"高橋区長","answer":"いずれにいたしましても、町と区との交流でなければ、ほんとうの交流になっていかないんじゃないだろうかというふうに思っております。方法論につきましては、十分検討させていただきたいと思っています。","id":"exchange-036"},{"speaker":"山路委員","kind":"質問","question":"今月施行された高齢者の居住の安定確保に関する法律に関連してお伺いいたします。東京都の場合は、財団法人東京都防災・建築まちづくりセンターが該当しますが、これに加入しているのは、２３区中、板橋区と大田区のみで、品川区は加入しておりません。そこで、なぜ板橋区と大田区だけで、そのほかの区は加入していないのか、また、品川区が加入しない理由についてお伺いいたします。","respondent":"新美保健高齢事業部長","answer":"その３点は、第１に家賃滞納時の賠償に対する金銭保証であり、入院時、死亡時に対応する身元引受的な仕組みになっていないこと、第２に高齢者の生活支援や見守りがなく、孤独死や失火といった家主の不安を解消できていないこと。","id":"exchange-037"},{"speaker":"山路委員","kind":"質問","question":"今、部長の答弁と若干ダブりますけど、９月２１日の本会議で我が党の辻委員が質問して、これに対する区側の答弁が、今部長が言われたようなこと、高齢者の住まいの確保について大方のニーズに応え、区においては、以前から借り上げを含む区立高齢者住宅の整備運営と高齢者の住宅あっせん制度を柱として支援し。","respondent":"新美保健高齢事業部長","answer":"ということで、私どもこの事業については、宅建協会品川支部と協力連携をとりながら事業を進めておりますので、今後、宅建協会との意見交換の場がありますので、そういったところを活用して、制度の周知、それから地域の家主さんの制度活用の意向等を十分把握いたしまして。","id":"exchange-038"},{"speaker":"山路委員","kind":"意見","question":"部長の言われていること、理論ではわかるんですよ。大屋さんが高齢者に貸さないという不安を払拭しないと、どうしても家主さんが安心して部屋を貸すことができない。そのための救済制度として、今回国の法律が施行されたと思いますけど、ここのところについて、たくさん現場では部屋が借りれないという方がいらっしゃいますので、もう一度ご答弁をお願いしたい。","respondent":"新美保健高齢事業部長","answer":"そういう意味では、新しい国制度ができたわけですので、その活用については十分検討し、実現できるものは実現をしていく、従来の我々の区の施策についても、整合性を見直しつつ、活用について検討してまいりたいというふうに考えております。","id":"exchange-039"},{"speaker":"山路委員","kind":"質問・要望","question":"この問題につきましては、保健高齢事業部長のご答弁を信じまして、保健高齢事業部長におあずけいたしますので、現場で高齢者が安心して民間住宅に住み、品川区に長く住み続けるようにしていただきたいことを要望して、私の総括質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"桜井委員","kind":"質問・要望","question":"最初に、行政評価システムの問題、そして、続けて住民への情報提供と住民参加の問題、３点目には１６３号線の問題について、時間がある限り質問させていただきたいと思います。特に今回示された２１２の事務事業評価について明らかになった点は、効率化、公平化の名のもとに、事業の縮小、廃止がされようとしており、区民に対しては、受益を受ける者は応分の負担を求めていく姿勢が色濃く出ております。","respondent":"中尾根企画部長","answer":"したがいまして、そういう取り組みの結果といたしましては、一つには事務指標をそれぞれの事業に据えることによりまして、実施方向が明確になってきたということが挙げられますし、さらには、大胆に事務事業に対する所管課長、部長。","id":"exchange-041"},{"speaker":"桜井委員","kind":"提案","question":"行政評価の目的について、私は昨年の９月定例会で区長に質問申し上げました。改めてお尋ねします。それから今申し上げたように、私は第３回定例会で目的の問題、それから二つ目には、施策に係わるあらゆる情報を住民にわかりやすく提供していく住民参加の問題、３点目には、すべての事業について評価すべきという提案を申し上げたわけですけども、そのことについて改めてお尋ねします。","respondent":"中尾根企画部長","answer":"そのことについては、いささかも変更はございません。ただ、今回の事務事業評価の結果のまとめを公表するに当たりまして、私どもが非常に意を注いだのは、こういうＡ、Ｂ、Ｃ、Ｄという評価であるとか、そういうものを出すに当たって誤解されないということが非常に重要だ。","id":"exchange-042"},{"speaker":"桜井委員","kind":"質問","question":"後で答弁漏れについてはお答えください。失業率が５％を超えました。そして、係わっている住民の皆さんがどういう希望を持っているのか、もうこれは要らないよというのか、そういう点では、廃止縮小、あるいは拡大に当たっても、直接住民に係わるサービスについては、私は自己評価の段階から、やはり入れるべきだというふうに考えますけど、いかがでしょうか。","respondent":"中尾根企画部長","answer":"事務事業評価の中は、私どもが言いましたように、いろんなプロセスも明らかにして、こういうふうに考えて、どうとらえているんだ、これでどうですかと提起するものですから、その段階の中でごちゃごちゃするというわけにはいきませんので。","id":"exchange-043"},{"speaker":"桜井委員","kind":"質問","question":"価値観が違うというお話はちょっといただけません。さまざまな、今民主主義の世の中ですから、いろんな価値観があり、いろんな多様な意見がある。そのことをやっぱりきちっと行政は平等に扱っていく、そして受けとめていく、そういう度量があって私はいいと思うんですね。部長はそういう度量がある方だというふうに思っていたわけですけども。そして、その現状と対策を改めて伺いたいというふうに思います。","respondent":"小沼福祉事業部長","answer":"今、東京都と２３区での大きな区分といたしましては就労関係、あるいは就業関係につきましては、これはこの間、款別のときに申し上げましたけど、産業労働経済局と、それから福祉局のほうが中心となりまして、就業就労対策についての一つの検討に入っているという状況です。","id":"exchange-044"},{"speaker":"桜井委員","kind":"質問・要望","question":"そういう中で、８割の方が職を求めているという事態で、今品川で７０名というお話なんですけども、やはり、その傾向は私は同じではないかと思うんですね。私は区長にその考え方の大変やっぱり長として失礼ですけども、いかがなものかというふうに思うんです。今後の生活保護の行政の改善、これについてもあわせてどういう考え方があるのかをお尋ねしたいと思います。","respondent":"高橋区長、小沼福祉事業部長","answer":"それで、この品川区にいられなければ、やはりほかの区に行くしか方法はないだろうと、こういうようなことを申し上げたわけでして、また、２３区では、それぞれの区が一つの役割を担おうということで。後段の生活保護、いわゆる生活保護制度の適用の今後の考え方ですけれども、これはこの前の民生費のときも出てきた質問とも関連しますけれども、私ども、いわゆるホームレス、路上生活をされている方だから適用があるとかないとか。","id":"exchange-045"},{"speaker":"桜井委員","kind":"質問","question":"だって、１７万人を超えるリストラでしょう。これまで、都の調査でもホームレス直前の職業は技能工が４割ですよ。ですから、私はやはり、この職を失った理由が不況の影響、これが大きいということは、政府自身も認めているわけなんですよ。だから、私は改めてこの生活保護の考え方の中で、二つ改善策が出されております、国のほうのケースワーカーの説明会で、その二つの改善策を改めてお尋ねします。","respondent":"小沼福祉事業部長","answer":"これ、実は幾つかページが分かれてありますけど、先ほどの生活保護の適用の基本的な考え方、タイトルにつきましては、ホームレスに対する基本的な生活保護の適用についてというタイトルバックのものですけれども、先ほど申し上げましたような基本的な考え方は。","id":"exchange-046"},{"speaker":"桜井委員","kind":"質問","question":"ですから、ホームレスが区長が前段で述べられたように、困る者と、あるいはホームレスは、言葉としては言っていないですけども、いてほしくないというのを暗に区民ではあってほしくないみたいな、そういうニュアンスが強く出るわけですよ。しかし、なぜそういう背景になって、そのことを改善していく、そこに政治の責任があるということをきっちり持つことが私は大事だと思います。改めて見解をお願いします。","respondent":"高橋区長","answer":"だけど、そういうホームレスがいること自体が問題であって、それを収容して、その人たちの自立を促していこうということが、そこから始まったわけでして、それぞれの東京都と２３区が共同してそれをやっていこう。","id":"exchange-047"},{"speaker":"桜井委員","kind":"意見","question":"実際にホームレス問題は、大変今の政治の貧困さをどう見るかと同時に、そこにやっぱり住んでいる人たちに対しての生活保障をどうするかという大変複雑な問題もはらんでいます。私はそういう点では、行政の姿勢が鋭く問われる、そういう点だと思います。それで、今お話が出ました生活保護の５年間の実績をまずお尋ねします。","respondent":"小沼福祉事業部長","answer":"ちなみに、保護率ですが、平成９年度が9.８パーミル、１１年度が9.１パーミル、１０年度が8.２パーミル、９年度が7.５パーミル、８年度が7.０パーミルと、こういうような５年間の数値は、今申し上げたようなところです。","id":"exchange-048"},{"speaker":"桜井委員","kind":"意見","question":"実際、区民１００人に１人が生活保護を受けているという、大変深刻な状況です。そういう中で、区が一体どういうふうにそういう方々にやっぱり心を寄せていくのかという、先ほど来行政評価システムの話をしましたけども、実は、ここで保護率の問題について、事務事業評価の中では、保護率を下げていくというお話ですね。これはどういうところから来ているのか、ご説明ください。","respondent":"小沼福祉事業部長","answer":"いわゆる、品川区のフェースといいますか、場面で考えますと、当然自治体としてできることとできないこと、これはあります。区あるいは都の役割分担がありますけども。","id":"exchange-049"},{"speaker":"桜井委員","kind":"質問","question":"就労のやっぱり機会を拡大する。ですから、そのことによって、具体的な区が施策として区独自の施策としてこういうセーフネットをやるというのがない限り、私はやはり非常に不安が拡大するというふうに思います。それが８０枚になって、７０枚になって、今は何枚ですか、７０枚でしょうか、あるいは５６枚でしょうか。ここのところにメスを入れるというのはどういうことなんでしょうか。","respondent":"小沼福祉事業部長","answer":"今後の状況等を考えますと、生活保護制度、少なくとも新しい生活福祉の視点ということになりますと、やはり、自立の、厚生ということじゃなくて、自立の支援であるとか、援助であるとか、助長であるとかと、そういう方向に移していくということの流れで。","id":"exchange-050"},{"speaker":"桜井委員","kind":"質問","question":"ですから、私は、入浴券の問題というのは、ただ単に入浴券というんじゃなくて、やはり人間らしい生活を少しでもしていきたいという点からいって、どうやって自立支援を、自立支援というなら、私は入浴券については、やはり、きちっとしてもとの１週間の２回に戻して、そして健康回復して、それぞれの就労に例えば行くということのほうが、よっぽど自立支援じゃないですか。","respondent":"高橋区長、小沼福祉事業部長、新美保健高齢事業部長","answer":"高齢者は金持ちだと私言いません。言われていると、たしか言ったと思いました。その上に、財政力と、あるいは時代的な背景というのを考えて、それぞれ市部あるいは区部、東京都２３区ですけど、それぞれの区で上乗せしている。平成１２年度の品川区内５万8,０００人の６５歳の方の所得の分布ですが、第１段階が2.９４％、第２段階、世帯全員が区民税非課税世帯ですね。","id":"exchange-051"},{"speaker":"桜井委員","kind":"質問","question":"部長はすべて法内でいくという驚くべき発言をしているわけですけども、ご承知のように生活保護は国の制度ですから、地方、都心部、あるいは大都市、いろんなやっぱりそれぞれの実態があるわけですよね。ですから、地方分権ということで地方自治体としてよく区長が言うように、品川区は品川区だという、品川区にふさわしい保護制度をやるべきだというふうに思うわけです。改めて厳しくしておきたいと思います。","respondent":"中谷まちづくり事業部長","answer":"大崎駅東口の第３地区のまちづくりの状況ですが、こちらはご存じのとおりニューシティーの隣の地域でございまして、大体事業規模が2.６ヘクタール、今現在、住宅２棟、そして事務所棟２棟の都市計画決定に向けて準備を進めているところです。","id":"exchange-052"},{"speaker":"桜井委員","kind":"質問","question":"総事業費とかいろいろと聞いたんですけど、それも教えてください。","respondent":"中谷まちづくり事業部長","answer":"総事業費ですが、ちょっと今現在計画策定中でございまして、この事業費につきましては、今後動いていくということが考えられますが、まず、総事業費は概ね６００億円前後を予定しておりまして、補助金の額ですが、これもご存じのとおり固まっておりませんが。","id":"exchange-053"},{"speaker":"桜井委員","kind":"質問","question":"今１００億円という数字が出まして、私ども、この問題は、かねがね指摘しておりますけども、実際１７年間で４２０億円を超える補助金なんですよね。さっき、入浴券の問題を言いましたけども、法外援護というのは品川で年間9,０００万円ですよ。そこで入れるのはやっぱり１００億円ですよ。私は、なぜこんなに民間の大規模開発に湯水のようにお金をつぎ込むのかと、改めてお聞きしたいと思います。","respondent":"中谷まちづくり事業部長","answer":"先ほどもお話ししたとおり、この大崎駅第３地区につきましては、ここは駅前に極めて近いところでございまして、品川区の大井町とともに顔とも言える部分です。この顔の部分を発展させていかなければ、地域の活力は生まれませんし、まちづくりも発展していかないです。","id":"exchange-054"},{"speaker":"桜井委員","kind":"質問・要望","question":"私は、さっき生活保護の問題を言いましたけども、本来区がやるべきことは、やっぱり住民の生活と暮らしですよ。次に、住民参加、情報提供についてお尋ねします。そのことによって、区民がどういうふうに評価するのかという点は基本だと思うんですね。それからもう一つは、どのようにその方々に情報提供をされているのか、お知らせください。","respondent":"新美保健高齢事業部長","answer":"区内の居宅介護支援事業者数ですが、事業者指定をしている区内に住所を有する事業者数につきましては、現在４９です。うち、区の在宅介護支援センターが１７、それ以外が３２ということになります。","id":"exchange-055"},{"speaker":"桜井委員","kind":"意見","question":"いや、違う。ごめんね。在宅者の連絡情報提供はどうなのかと聞いたんです。","respondent":"新美保健高齢事業部長","answer":"したがいまして、居宅介護支援事業者のうち、在宅介護支援センターについては、当然定期的な連絡、あるいは区の方針等を通知し、あるいは指導しています。","id":"exchange-056"},{"speaker":"桜井委員","kind":"質問","question":"必要に応じてというのがちょっと気になるんですけどね。例えば、去年４月から実施されて、かなり１年の間でも、例えばショートステイの運用の仕方とか、それから今日直近では、東京都の今度は介護制度の利用者への軽減の問題がありますよね。その都度、かなり改善され、あるいは変更されてきた、その都度というのは、変更されてきたときに３２の事業者に連絡をしているんでしょうか。","respondent":"新美保健高齢事業部長","answer":"ただ、それ以外の方でも、お問い合わせ等ありましたら、十分個別にご説明、対応しておりますので、そういったところでぜひ情報収集をよろしくお願いしたいと呼びかけているところです。","id":"exchange-057"},{"speaker":"桜井委員","kind":"質問","question":"情報収集の努力ではなくて、私は情報提供の責務として区があると思うんです。款別の中でも、宮崎委員のほうで課長との質問の中で、聞いたとか、聞かないとかということがありますけども、私は第一義的に情報収集ではなくて、情報提供があると思うんです。在宅介護支援センター以外の皆さんは、先ほどちょっと部長が言いかけたんですけども、何名いらっしゃいますでしょうか。","respondent":"新美保健高齢事業部長","answer":"ご質問は在宅介護支援センター以外で、ケアプランを作成している方が何人いるかと、そういうご質問でしょうか。８月審査分の介護報酬請求から見ますと、８１事業者、３０９件の介護報酬請求が支援センター以外から来ております。","id":"exchange-058"},{"speaker":"桜井委員","kind":"質問・要望","question":"ということは、３０９人の方々が先ほど言ったショートステイの問題ではありませんけども、情報収集が怠ったために、受けられにくかったということになりかねない。私は、これは情報提供の責任としてぜひ改善を求めたいと思うんですよ。ですから、変更があったときに、そうした在宅介護支援センターの事業者への情報提供をぜひこの場でお約束をいただきたいというふうに思いますけど、いかがでしょうか。","respondent":"新美保健高齢事業部長","answer":"ただ、品川区は品川区なりの運用をしております。大田区とはまた違った運用、これにはご協力いただく方には十分ご説明をしたいと思いますし、その辺についてはそういう関係の中で情報提供をきちんとしていくです。","id":"exchange-059"},{"speaker":"桜井委員","kind":"質問・要望","question":"品川区で民間の業者がいるんですから、品川で情報提供いただきたいと思うんですよね。いつ区に変更になったかが、聞かなくちゃわからない。それからもう一つの点で、これは毎回ここ１０年余の間で５回、６回ほど指摘しておりますけども、学童連協の問題ですけど、区長、去年、沢田委員が区長とルールをつくってやるというお話しですけども、その後改善されたというふうに区長はお考えになっているでしょうか。","respondent":"中尾根企画部長","answer":"これを検討いたしましたけど、やっぱり、この方法が一番公平でいいという結論ですので、この方法を続けさせていただきたい、このように考えてあります。","id":"exchange-060"},{"speaker":"桜井委員","kind":"質問","question":"昨日私、「その後どうですか、１年間は」と申し上げましたらば、「もう既に今年８月２４日から４回にわたって課長に会談を要請してきたんですけども、まだ会えない」と。だから、文書で出したということですが、昨年６回やっているんですよね。そんなに課長は毎日毎日忙しいですか。そのルールはどうも学童の課長との間では、ルールが確立していないようですけど、ルールを確立する意思があるんでしょうか。","respondent":"小沼福祉事業部長","answer":"具体的に連協ということで、それを所管する課、児童課が窓口になるかなと思うんですが、そのお話が出ましたので、私のほうからお答え申し上げますけれども、課長から私を含めて、この場、あるいは本会議等の場で再三再四区長が申し上げている仕切りですね。","id":"exchange-061"},{"speaker":"桜井委員","kind":"質問・要望","question":"じゃあ、課長がルール違反しているんでしょうか。私は、ここの陳情の中でも、定員がオーバーだから、いろんな心配があるので聞いていただきたい。そして、来週の募集の状況も聞きたいと今回台風の関係で課のほうは、学童のほうはお休み、その当日ですね、連絡が来たと。それについて、聞く耳を持たないということなんでしょうか。私はこの問題は区長に聞きたいと思います。","respondent":"高橋区長","answer":"はっきり申し上げまして、やはり、そういう要請を受ける場合、それぞれ紳士的な、女性ですと淑女的な立場でひとつ会合をしてもらいたい、これが私のたってのお願いです。お願いですよ。それじゃなければ、また会うことができなくなりますので、それだけは申し添えておきます。","id":"exchange-062"},{"speaker":"桜井委員","kind":"質問","question":"昨年３月に話し合いを持ったようですけども、そのときの話し合いというのはどうだったんでしょうか。紳士的だったんでしょうか、お尋ねします。","respondent":"小沼福祉事業部長","answer":"少なくとも、ただ、私が承知している限り、仄聞する限りでは、紳士的になさっているんじゃないかなと思います。両当事者で会う場面があったということであればですね、そういうふうに考えてあります。","id":"exchange-063"},{"speaker":"桜井委員","kind":"質問","question":"じゃあ、区長の責任というより、部長の責任でぜひ改善をお願いしたい。ですから、私はそういう点で今部長がきちっと対応するということでありますから、それを了として見守っていきたいと思います。続きまして、時間が限られておりますから、１６３号線について聞きます。実際に１６３号線について、８月３０日に説明会がありました。そして、概要についても、権利者の関係もお知らせください。","respondent":"中谷まちづくり事業部長","answer":"そして今測量を行っておりますので、この測量を行い次第、事業認可に必要な図書をまとめ、来年早々にも事業認可申請を出し、春には事業認可を取得した後、用地補償等の説明会をして。","id":"exchange-064"},{"speaker":"桜井委員","kind":"質問","question":"一般質問の答弁で、区の認識としてこの問題、一本橋商店街の理解が得られなければ、本事業の進展はあり得ないと。商店など、道路計画に協力をいただく方々に十分な話し合いが必要だと。ですから、ある面では区が具体的に例えば種地を確保して、あるいはそこに仮の住宅あるいは店舗ということも含めてやっていくということについての考え方をお聞きします。","respondent":"中谷まちづくり事業部長","answer":"こういうものについても、区のほうとしてもできる限りの支援をしていきたいというふうに考えておりますし、また、公的住宅、こういうものがありますれば、こういうものについて入居する方についても当然あっせんしていく等の対応も考えていきたいというふうに思っておりますので。","id":"exchange-065"},{"speaker":"桜井委員","kind":"質問・要望","question":"そういう点で、商店振興についての角度からまずちょっとご答弁いただきたいし、同時に区長がマイクを用意されているようですから、区長の決意があれば、お聞きしたいというふうに思います。","respondent":"小栗区民生活事業部長、中谷まちづくり事業部長","answer":"したがいまして、さまざまなケースが出てくるかと思いますが、産業振興の面から相談に乗ってほしいと、こういうお申し出を受けておりますので、具体的な対応策が出てきました段階で支援などを検討してまいりたい。住宅に入居をご希望する方につきましては、区民住宅等、幸いマテリアルの住宅等がタイミングよくできるといいますか、完成になりますので、こういうものを利用する等既存の住宅ストックを最大限利用する中で。","id":"exchange-066"},{"speaker":"桜井委員","kind":"意見","question":"一本橋を含めたまちづくりについては、私どももいろいろと研究して、住民の皆さんと住んでいてよかった、商売していてよかったと言えるような、そういう点ではやっていきたいといふうに思いますし、区のほうもご努力を一層お願いしたいと思います。先ほど来、地方自治体のあり方の問題も申し上げました。ほんとうに暮らし、福祉、厳しいところにあります。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"川西委員","kind":"質問・要望","question":"初めに、ＩＳＯ１４００１認証取得による今後の取り組みについてお伺いいたします。「いよいよ新たなスタートです」。２番目は、小・中学校における環境教育について内容を伺います。３番目は、エネルギー源としての太陽光発電システムの活用を区民に呼びかけ、いわゆる省エネのことですが、補助金等の手続を案内、そしてあっせんできるシステムづくりについて、どのようにお考えであるか伺います。","respondent":"野本環境清掃事業部長","answer":"太陽光発電の有効活用に関し、候補市あるいは今年の１１月から各部において、ホームページ等も利用できるようになりますので、そういうようなものを通じて積極的に区民へのＰＲについて実施をしていきたいと、かように考えてあります。","id":"exchange-068"},{"speaker":"川西委員","kind":"質問・要望","question":"カレンダーに変えたいですので、これというのは、世帯に全部配るんですか。──ああ、そうですか。ですから、あれをもう少しどこかの部屋があいていましたら、総合相談窓口というようなものを手始めに考えていただけないかどうか。よろしくご期待申し上げます。私は今６５歳ですから、これからいわゆる高齢期を迎えるといいますか、もうそうなんですけれども、人たちにやはり責任があると思う。","respondent":"新美保健高齢事業部長","answer":"この辺の活動のあり方につきましても、プラン２１のこれからの柱の一つというふうに思っておりますので、そういう方向で検討を進めたいと存じます。","id":"exchange-069"},{"speaker":"川西委員","kind":"質問・要望","question":"「６５歳や６８歳で何言っているんですか」なんて言われることもあります。ですから、その年になって、痛みがわかる人にそういう相談を据えていただきたい。プラン２１にこれらのことをぜひ盛り込んでいただきたいと要望いたします。そういう意味で、死んだ計画をいつまでも残しておくのか、ほんとうに緑道としての計画をやる気があるのか伺います。しかし、その後、設置の要望があるのかどうか伺います。","respondent":"中谷まちづくり事業部長","answer":"このように考えておりまして、今具体的な検討を行っておりますので、近々、徐々にまちから花壇が増えていく日が来るんではないかということで考えております。","id":"exchange-070"},{"speaker":"川西委員","kind":"質問・要望","question":"改修について、来年すぐできるのかどうかは別として、お願いしたいと思います。やはり、周りがよくなったにしては、トイレがちょっとと思います。ですから、むだなスペースということになりますから、隣接に買い取っていただくなりという大胆な処置をとって、一つずつそういうものは整理していくという、公共的な区であっても、そのことが必要だというふうにお願いをしておきます。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"土井委員","kind":"質問","question":"民主党区民連合を代表させていただきまして、総括質問をします。その意味では、やはり、都区の関係での今後の課題というようなものはどういうものがあるのかということについて、どのようにお考えになっているか、あるいはまた、それらの課題を解決していくという形の中での活動体といいますか、そういうものについてどのようにお考えになっているのか、まずもってお伺いをしたいと思います。","respondent":"中尾根企画部長","answer":"自治権確立の問題ですけれども、今委員ご説明ありましたように、都区制度改革につきましては、戦後の昭和２７年の自治法の改正、改正というか、改悪から始まりまして、幾多の運動がありました。最近では昭和５０年、念願の区長の公選制というものを勝ち取ってきたわけです。","id":"exchange-072"},{"speaker":"土井委員","kind":"質問・要望","question":"そしてまた、そのときには、特に清掃一部事務組合については、先ほどのお話の中でも、いわゆる一部組合としての仕事が残っちゃうということになりますと、残るものがあるとすれば、それは何なのか、きちっと決めて、そこはそれとして残すけれども、それ以外は絶対に譲らないという態度をしっかりしていかなきゃいけないと考えていますので、その辺の考え方についてお伺いします。","respondent":"高橋区長","answer":"したがいまして、２３区と東京都で財調の問題についての取り組みを今後進めていかなくちゃならないわけでございまして、財源の配分がぴしゃっと決まりますと、この２３区と東京都の関連がなくなれば、２３区の中でその配分方法をどうするかということが残るだけです。","id":"exchange-073"},{"speaker":"土井委員","kind":"質問","question":"こんなのができたのは、やはり、職員の派遣もする、みんなも努力もする、融和を図っていこうという作業が前々から行われていて、それですぐにこんな形ができたんだと思いますから、これも区長をはじめとする理事者の皆さん、あるいは実際に携わっている皆さんがいろんな意味でご努力をされたことだと思って敬意を表するわけですけれども、そういうことに進めていくためには。","respondent":"高橋区長","answer":"こういう問題を検討し、結論を出すということになっております。先ほど申し上げましたように、まだ２回しかやっておりませんけど、これから詰めて、そういう問題を平成１７年度までに鋭意具体的な問題を出していくと、これが２３区の取り組みの一応予定です。","id":"exchange-074"},{"speaker":"土井委員","kind":"質問・要望","question":"この移管の問題等も含めて、いろいろ２０年も３０年もかかって、ようやっとやってきた。これが、どうもいろんな意味の理解が十分に進まない中で、これを何としても入れようということなもんですから、どうもこれを持っているとお守りみたいな感じに宣伝をされている嫌いがなきにしもあらずというふうに思いますけれども、これらとの関連も含めて若干お聞かせをいただきたいと思います。","respondent":"中尾根企画部長","answer":"それと同時に、情報に対するセキュリティーをきちんとしていかなくちゃいけない、この防備の問題。それと、操作をするのは職員ですから、職員がきちんとそういう能力を持たなきゃいけない、こういうようなことを同時にあわせて今対応しています。","id":"exchange-075"},{"speaker":"土井委員","kind":"質問・要望","question":"今住民基本台帳システムのコンセンサスの問題等々はまだまだ全国的な議論が必要ですので、あえて申し上げませんが、いずれにしても庁内イントラネット等も含めまして、これからやっぱりせっかく組んでいくわけですから、将来を見据えた格好で、住民サービスにつなげるのが最終目的ですので、ぜひよろしく進めていただきたいというふうに思います。同じ申請書が３種類あったり、４種類あったりするんですね。","respondent":"中尾根企画部長","answer":"したがいまして、区民生活に必要な情報につきましては、できるだけホームページの中で情報を提供していきたいというふうに今考えておりまして、それぞれ事業部が競いまして、今内容を検討しています。","id":"exchange-076"},{"speaker":"土井委員","kind":"質問","question":"こういうのは何とかなりますよね。そして、場合によってはそういうご相談等をいただく中から、今はそこはまだできないけれども、とりあえずじゃあここでやってよということでお願いをして、優秀なところを確保しておくということが必要になってくるんじゃないかと思っているものですから、その辺についてどのような対処対応が始まるのか、していかれるのか、この辺をお伺いをしておきたいと思います。","respondent":"中尾根企画部長、指田教育次長、小栗区民生活事業部長","answer":"じゃあ、その後どうしていくのか、こういうことを区が十分検討していく、こういう役割だと考えています。今、ご指摘ございましたように、基本的にはあれは小・中学生向けの形、ソフトになっていて、ライセンス料を取っていますので、当然のことながら。西大井地区の再開発に絡みますＩＴ産業の誘致ですが、平成１５年度に竣工予定ですこの開発ビルの中の保留床を使いまして。","id":"exchange-077"},{"speaker":"土井委員","kind":"提案","question":"教育の関係のところで、著作権等々の問題等が起きないようにぜひ確実にやっていただきたいと、このように思います。パソコン講習会等で、やはり導入の位置、ある部分についてはやはり区がやるのはなかなかいいことだなと私も思っているんですね。それで、これがどういう経緯をもってこれが提起をされてきたのかと、ここに提案されてきたのかというその経過について、若干お聞かせをいただきたいと思うんです。","respondent":"小栗区民生活事業部長","answer":"区では、７月２日の議会で趣旨採択ということになりまして、この内容を受けまして、区で検討した結果、地域の防犯活動に区も主体的に取り組むべきだと、こういう時期に来ているということで、条例を提案させていただいたものです。","id":"exchange-078"},{"speaker":"土井委員","kind":"質問・要望","question":"これがそうはいかなくなった。なぜだと。だから、ここのところを私たちはやっぱりしっかりと踏まえながらやっていかないと、単なる訴えっこみたいな形になっては困りますので、ぜひそこら辺の運用等をきちんとやるように心がけていただきたいのが一つ。これは公的に完全につくったものですけれども、この辺と同じようにならないように、よろしくお願いをしたいと考えていますので、お答えを聞いて終わります。","respondent":"小栗区民生活事業部長","answer":"お話のとおり、協議会では設置目的が犯罪の防止であること、協議内容が青少年委員と重複しないよう十分注意して運営してまいります。","id":"exchange-079"},{"speaker":"田中委員","kind":"質問・要望","question":"区民クラブを代表いたしまして、総括質疑をさせていただきたいと存じます。私も最後ですので、重複を避けつつ、重複する部分は若干角度を変えてお伺いをしたいと思います。第１点目は、行政評価につきまして、お伺いをいたします。そういった公の立場で評価をますます受ける環境の中においての事務事業評価の基本的な考え方についてからまずお伺いをしたいと思います。","respondent":"中尾根企画部長","answer":"そこで、区といたしましては、区政総合業績評価システムというように幅広い観点から取り組んでいくということで、一つには企業会計手法の導入ということ、これはバランスシートの問題ですし、２番目には行政評価、今委員のご案内のとおりです。","id":"exchange-080"},{"speaker":"田中委員","kind":"質問・要望","question":"事務事業評価につきまして、ぜひこの評価の活用をより図っていただきたいと考えています。一つは、事務事業の権限委譲ということも午前中の審議にもございましたが、質的な向上といえるような観点も含めまして、予算編成のあり方とか考え方、方法などの変化があるのか、お伺いしたいと思います。","respondent":"市岡企画財政課長","answer":"この事務事業評価の成果を予算にどういうふうに生かしていくかということなんですが、先ほどのご答弁の中で、企画部長のほうから権限委譲の一つとして、１４年度予算については、各事業部の事業部編成枠方式、こういう新しい方式をとるというご説明を申し上げました。","id":"exchange-081"},{"speaker":"田中委員","kind":"質問・要望","question":"組織としての中では、そういう活用がなされようかと思いますが、またそこにいらっしゃる職員の方々の意識というんでしょうか、職員の方々同士のいろいろな刺激にもなったりするものだろうと思いますけれども、その職員の方にとっての意識改革にとって、この事業部評価というものがどのように活用されるのか、その点をお伺いしたいと思います。","respondent":"中尾根企画部長","answer":"職員にとって、どういう影響かですけれども、もともとこの事務事業評価というものにつきましては、仕事一つ一つについて区民に対する説明責任、これをどうしていくかという手法の一つとして始めたものです。","id":"exchange-082"},{"speaker":"田中委員","kind":"質問・要望","question":"組織、また職員の方々を含めたさまざまな意味での質的向上がこの活用によって図られると思いますので、ぜひ活用いただきたいと思います。次に出てくる政策評価につきまして、政策評価の意味合いというのは、おおよそわかってはいるんですが、まずその内容につきまして、おおよそのことと、あと、今後の導入についての予定についてお伺いをしたいと思います。","respondent":"中尾根企画部長","answer":"今後の進め方ですけれども、これをやるには、第三者による委員会の設定方式がよろしいだろうというふうに私どもは考えてございまして、この委員会を設置し、その委員会の中で具体的にはどういう評価の仕方をしたらいいのかというのをご議論いただいて、具体的に進めていきたい。","id":"exchange-083"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほどの事務事業評価は、いわゆる自己評価であるために、我々区議会がその仕組みの中には入ってはおりませんが、この政策評価に関しましては、いわゆる経営的な評価を行うという観点からも、ぜひ議会の係わりというものもその仕組みの中に組み込んだほうがより質の高いものが、評価がなされるのではないかなというふうな思いを一部しておりますが。","respondent":"中尾根企画部長","answer":"政策評価のほうは、先ほど言いましたのは目的ですから、これは平たく言った言い方ですと、区長に対する諮問機関的な意味合いがあります。したがいまして、ここのけじめはきちんとつけていかなくちゃいけない、このように考えているところです。","id":"exchange-084"},{"speaker":"田中委員","kind":"質問・要望","question":"続きまして、２番目は職員の方々の育成についてお伺いをしたいと思います。一方、職員の人数が減る一方で、区民の方々からの行政需要、地方分権が進むことによって、区に求める需要というものが逆に増えてきていると思います。そのような環境変化がありますけれども、まずは品川区におきましての職員の育成についての現状の認識とか基本的な考え方をまずお伺いしたいと思います。","respondent":"本間総務部長","answer":"先ほど来、いろいろお話が出てくる中で、また一方では非常に特別区制度の改革等によって、自治が進展をしているということを踏まえて、これから品川区の個性、品川区の特色を生かした、創意あふれる行政展開を図るには、この職務を遂行する職員一人一人の資質の向上を図り。","id":"exchange-085"},{"speaker":"田中委員","kind":"質問","question":"いわゆる人事配属の管理というんでしょうか、そういったものも職員の育成上行われているかと思いますが、もう少し具体的にこれまでの取り組みと、また今後いわゆる基礎的自治体ということの意識も踏まえながらも、新しい品川区を目指していく上での新しい研修に対する取り組みということをまずお伺いしたいと思います。","respondent":"本間総務部長","answer":"それで、新しい取り組みですが、事業部制が４月からスタートいたしまして、我々研修を所管するセクションといたしましても、この事業部制に対応いたしまして、新しい研修をスタートさせてあります。","id":"exchange-086"},{"speaker":"田中委員","kind":"質問・要望","question":"そのキャリアアップしていく際の本人の希望がどれだけ聞いてもらえるのかといったようなもの、また、先ほど出た正当に業績を評価してもらうような制度というものも当然そこに必要になってくるかと思いますが、先ほどはスキルアップという観点でお伺いいたしましたけれども、働く意欲を向上させるための方策として、款別審査にも出ていましたけれども、例えば表彰制度ですとか、これは款別審査で伺った際。","respondent":"本間総務部長","answer":"人事委員会等につきましては、午前中からいろいろとお話が出てありますが、この中で確かに委員ご指摘のとおり、実際に汗をかいて実績を上げた職員が、それなりに報われるという意味では、なかなか昇任ですとか、給与制度で統一基準という２３区のそういう基準がありますが。","id":"exchange-087"},{"speaker":"田中委員","kind":"質問・要望","question":"そのそういう職員の方の能力を十分引き出して、区民のニーズに応えていただくように高橋区長をはじめ、理事者の皆様のご努力を強く要望いたしますと同時に、今年度から新しく研修担当課が発足いたしましたが、課長以下、課員の皆様のご努力を、ご尽力を強く期待をいたしておりますので、よろしくお願いいたします。続きまして、３番目はペイオフの問題についてお伺いをしたいと思います。","respondent":"相川収入役","answer":"一方、総務省におきましては、地方公共団体におきますペイオフ解禁への対応策の検討を進めてまいりまして、これにつきましても、金融機関の経営状況の把握と、公金預金の保護策の２本の柱からなる報告書が発表されてあります。","id":"exchange-088"},{"speaker":"田中委員","kind":"質問","question":"この基金の中にも果実運用型ですとか、取り崩し型とか、それぞれいろいろなタイプの基金がありますけれども、こういったペイオフに向けて、こういった基金の管理といいますか、対応についての考え方、そしてまた、年末をいよいよ迎えるに当たって、またさらに中小企業の方々を中心とした融資制度、制度融資が区の事業としてもなされておりますけれども。","respondent":"相川収入役","answer":"そういうことですので、現在区内にある３０の金融機関に預託をして、その何倍かの融資の枠を広げてありますので、ただ単にこの基金だけを保護する目的ではなくて、その政策目的のほうに軸足を置きながら、なおかつ私どもとしてはペイオフにもしあった場合について言うと。","id":"exchange-089"},{"speaker":"田中委員","kind":"質問","question":"さらにペイオフ対策の最も必要な部分としては、金融機関の安全性の見極めというものがものすごく大切になってまいりますが、先ほど、過去何年間かの資料等もお集めになって、調査されているということでございましたが、また、それぞれディスクローズされる資料等も分析をされていらっしゃると思いますけれども、この見極めに対する改めてお考えをお伺いしたいと思います。","respondent":"相川収入役","answer":"金融機関の経営状況の概況を把握する際には、一般的には健全性とか収益性とか、流動性の三つの側面が必要だと、こういうふうに言われてございまして、健全性の分析では、自己資本比率でありますとか、不良債権の比率、それから収益性の分析についてはいろんな利益率とか。","id":"exchange-090"},{"speaker":"田中委員","kind":"質問","question":"今、小泉内閣が一生懸命不良債権処理に向けて全力を挙げてらっしゃいまして、３年後をめどにすべてを処理するんだという意気込みで取り組んでいらっしゃいます。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"築舘委員","kind":"質問・要望","question":"まとめに当たりまして、本決算特別委員会での我が会派の款別審査における各委員の発言ならびに総括質疑における発言の意をくんでいただき、また、区長へ提出しました我が会派の政策要望書の各項目の内容を平成１４年度の予算編成に生かしていただきますことを付言いたしまして、平成１２年度の各会計の歳入歳出決算を認定いたし、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"堺委員","kind":"提案","question":"款別審査の際に、我が党委員から提案いたしました中央環状品川線都市計画素案に係る区民要望への対応、仮称品川中央公園に環境に優しい太陽光灯の導入、旗の台駅周辺に駐輪場や公衆トイレの設置、水と緑の市町村交流事業の拡充、補助２６号線等の交通安全対策、補助１６３号線整備事業に係わる商店街等への対応策。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-093"},{"speaker":"沢田委員","kind":"質問・要望","question":"用地特別会計には賛成します。千代田生命は全体面積の８０％を所有、ここに補助金５０億円近くも投入する理由はどこにあるのでしょうか。日本一の品川区の再開発計画に対し、根本的な見直しを求めるものであります。なお、密集住宅市街地整備事業は、住民の合意を得ながら、安全快適なまちをつくる点で前進していることを評価するとともに、これにみならった品川のまちづくりの転換を求めるものであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"本田委員","kind":"質問・要望","question":"新規事業の介護保険制度は高齢者福祉施策の新しい展開であり、保険料や利用料の納付に伴う被保険者、利用者の意見や苦情が制度に的確に反映できること、サービス供給の整備や、高齢者の加重負担軽減など、税と個人負担のあり方など、制度上の問題を含め、見直すべきところは見直して、より充実した制度として推進され、高齢者福祉の向上を図ることを要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"本間委員","kind":"質問・要望","question":"同時に、区民にわかりやすい財政状況および事務事業評価に努めていただきたいと思います。最後に、これまで決算特別委員会の審査を通じて、我が会派の各委員から発言した意見および指摘させていただきました事柄につきまして、今後の区政執行に当たり、十分に生かしていただきますことを強く要望いたしまして、平成１２年度品川区各会計歳入歳出決算を認定することに賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"田中委員","kind":"質問・要望","question":"新世紀のあるべき姿を描いた第三次長期基本計画の策定、行政サービスの維持向上を目指した行政評価システムの導入、環境問題にも積極的に取り組んだＩＳＯ１４００１認証取得、ＩＴ化推進をサポートするＩＴ基礎技能講習事業、全国的にも注目されている教育改革プラン２１の推進、住み替え可能な中堅ファミリー層向け住宅の供給事業等々、新時代に求められている品川区独自の施策であると高く評価いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/493823?Template=document&Id=1192#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":119133,"voices":221}},{"id":"h13-20011101-8","meetingId":"h13-cm11","date":"2001年11月1日","dateIso":"2001-11-01","committee":"建設委員会","time":"午前１０時０７分～午後３時２７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"上山委員","kind":"質問","question":"二、三まとめてお聞きしたいんですけれども、最初にその３工事まで契約されて、工期も今年度中には完成するというふうになっているかと思うんですけれども、調整池そのものはもう少し早くでき上がるかと思うんですけれども、実際に稼働できるのはいつ頃になるのかわかれば、池そのものでも稼働できるのか、あるいはその３工事の引っ張る管ができないと実際は稼働できないのか、その辺をお尋ねしたいのが一つ。","respondent":"北村下水道河川課長","answer":"稼働予定時期ですが、今のところその３工事も年度内竣工ということで予定していますので、今後、道路下の工事でいろいろな障害物等の可能性がありますが、一応今年度中には何とか完成させて稼働できるようにしたいと。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"仕組みというのがもう一つよくわからないんですけれども、下水道には本来汚水が流れていて、雨が降るとのみ込めないものは外に出てきちゃう。それを今の第二立会川幹線だとか幾つかの幹線でポンプ所に持っていって、勝島運河に放流しようということですね。勝島運河はそれをやっちゃうと、相当汚濁が出ちゃうんじゃないかなと思うんですが、その辺はどうなんですか。","respondent":"北村下水道河川課長","answer":"そういうような合流改善の対策と合わせまして、閉鎖性水域である勝島運河ではなくて、多少流れのある京浜運河に放流先を変更していくことで自然の浄化作用も働いてまいりますので、汚濁そのものは大部分改善されてくるというような判断で進めているところだと聞いてあります。","id":"exchange-002"},{"speaker":"築舘委員","kind":"意見","question":"これはデータイムの１０時から１６時台ということですが、朝とか夜とか通勤のときが一番ある意味では乗り降りが多くて、利用者は望んでいるんじゃないかなと思うんですが、その点、何で１０時から１６時台ということで限られているのかと。","respondent":"伊佐都市計画課長","answer":"埼京線はご存じのように代々木駅のところが開かずの踏み切りということで、その辺の関係で朝晩に本数を増やすことは厳しいということで、ただ全体として増やす方向では検討している。地元対応にいろいろ問題がある。","id":"exchange-003"},{"speaker":"横山副委員長","kind":"意見","question":"というのは、品川のほうに行くのに、西大井駅に止まっているのにチンチン鳴って、多分時間を計ると２分以上ずっと待つ。それは安全性があっていいんだけれども、逆に知っている人は、閉まると２分開かないよということでくぐる人が出てくるんじゃないかなと思うんだけれども、あの辺のところはほかの踏み切りと比べてすごく長いということをよく聞くんだけれども、何とかなるのか。","respondent":"伊佐都市計画課長","answer":"ご指摘の原踏み切りは特に駅の直近というか、すぐ南側にあるので、駅近くの踏み切りの宿命でございまして、止まっている時間もどうしても遮断機を鳴らしてしまう。ただ、その辺の時間が短くできないかという話は、今後ＪＲとも検討したいと思います。","id":"exchange-004"},{"speaker":"上山委員","kind":"質問・要望","question":"見込みというのは見込みだと思うんですけれども、何か基準というとおかしいんですが、例えばそういう人が出そうだとか、何かそういう情報があってそういうふうにしているのか、あるいは１年ぐらいあれば今までの経験則的にこれぐらいが出られるんじゃないかとか、何か裏付けみたいなものか根拠というのでしょうか、どういうようなことがあるのか、もしわかれば教えていただきたいと思いまして。","respondent":"田村住宅課長","answer":"後は、都営住宅は２７万戸あって、常にあき家が出てくるんですね。それをある程度見込んで、大体管理戸数が幾らなので発生戸数が大体このぐらいだということで見込んでいます。上山委員お尋ねの、例えば登録して次の募集が始まっちゃうわけですね。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"責任を持ってあっせんするということは、とにかくあき家募集に当たれば、多少遅れても必ず当たるというふうに説明していいのかどうなのかというのが一つ。それから、これとはちょっと違うんですけれども、自殺があったりいろいろな事故住宅が、今までは公募に載せなかったんだけれども、今度は載せるんだというような話を聞いたんですけれども、その辺の情報がもしわかったら教えていただけますか。","respondent":"田村住宅課長","answer":"１点目のあき家を登録して１年と切っても、先ほど言ったような読みもありますので、責任を持って登録をした方を住宅のあっせんをしているということで、ご理解いただきたいと思います。","id":"exchange-006"},{"speaker":"沢田委員","kind":"意見","question":"今の件なんですけれども、フォーマットだとか、あるいは提出するのはフロッピーみたいなものでもいいのかとか、何かそういうのがあれば、それから大体どれぐらいの分量、大論文を書くこともないと思うんだけれども、例えばＡ４版を１枚とか何とかというのがあるといいんですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"沢田委員","kind":"質問","question":"そうすると、紙に手書きでもいいし、ワープロでもいいし、場合によったらフロッピーみたいなもので、何でもいいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/791630?Template=document&Id=3704#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":12778,"voices":43}},{"id":"h13-20011105-5","meetingId":"h13-cm11","date":"2001年11月5日","dateIso":"2001-11-05","committee":"総務委員会","time":"午後１時０４分～午後４時４６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を69件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"林（宏）委員","kind":"意見","question":"申請書電子配信のところで、総務委員会じゃないかもわからないんだけれども、用紙がこういうふうに取り出せるようになっているんだけれども、あれは直接用紙を出して紙を一々使うのであれば、むしろ書き込めるようにして、メールのような形でというのは先々考えていらっしゃるのかな。この委員会で聞いていいかどうかわからないんだけれども。たまたま田中課長もいらっしゃるから。","respondent":"田中情報システム課長","answer":"それで、この点で区民の方の個人が特定できるような形の部分は、国のほうで汎用の電子申請届け出システムというのを今実証実験しておりますので、１年後には全国の市町村にそれが提示されるということになっておりますので、その辺のところを踏まえて。","id":"exchange-001"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"それも特色だと言われればそれまでなんだけれども、どういうふうにお考えになっているのかを聞かせていただきたいのと、リンクも、例えばリンク先だけど、環境清掃部の場合、例えばごみというか、大きいごみだ何だと、民間業者とかそういうような、いわゆるこれは役所関係の財団だとか外郭団体になっているんだけれども、そういう民間の必要な企業を載せるといろいろあるのかもわからないけれども。","respondent":"山田広報広聴課長","answer":"今回、統一性を図るという部分を、一面それぞれの事業部の中でもんでいただいて、ご自分たちとしてどうしていくかを検討していただくという部分もございましたので、かなりその辺、業者の提案の中ではカウンターできますというのはやっていたんですけれども。","id":"exchange-002"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"まだ立ち上がったばかりなので、いろいろこれからプラスしていく、あるいはマイナスしていくということが多いと思うんです。幾ら頑張ってつくっても、宝の持ちぐされということになりかねないので、そういうのも一つご検討をこれからしていただければと思います。要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中島委員","kind":"質問","question":"何かの検索のページで、５０音別ででてきたんですけれども、あれがそのまま残るんですか。そうすると、これはどこの区でひいていいかわからないものって出てくるんですね。中には例えば厚生労働省とか、ああいうところの検索のところには、文字を入れるとぱっと出てくるものがあるんですけど、そういうのもつきますか。","respondent":"山田広報広聴課長","answer":"一文字だけでは検索できない場合は追加の文字を入れていただいて、検索をしていく。現在、介護とかという言葉だけを入れますと、すごい膨大な、議会の答弁のページも、いわゆる区議会の広場にもリンクしておりますので、かなりボリュームとしては出てまいります。","id":"exchange-004"},{"speaker":"田中委員","kind":"確認","question":"データの更新のことについてちょっとお伺いいたしますが、以前の決算、予算委員会でもちょっと質問させていただいたことがあるんですが、最新情報の内容が、既につくられているページのデータには、あの当時にはなかなか更新されないということがありましたが、今回この今後の管理のところにも空き情報などは随時更新をされているということでなっておりますが、ちょっと確認の意味も含めまして。","respondent":"山田広報広聴課長","answer":"そういったものがないものについては、各事業部の中で日々更新ということに、例えば保養所の空き情報を１１月末ぐらいから所管とすれば入れていきたいということで、今準備をしているんですけれども、そのような形で独自のページのところで空き情報を設けるということで。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問","question":"今までは、一つつくられたものがそこでの変更はなく、区民の方々としては最新情報を見るしか、最新情報を見れば１０月以降変わったということはわかるんですが、もともとの児童課のページだけを見てしまうと、そのままの状態になるという、その最新性、更新されないということが今までのページにはありましたが、今後はそういうことも更新されていくのかどうかということでちょっとお聞きします。","respondent":"山田広報広聴課長","answer":"ですから、ある意味では二つの作業をしなければいけないという部分については、ちょっと残念ながら従来どおり、予算の関係ではなくて、あくまでも考え方としてまだそこまでいっておりませんので、ご理解いただきたいと思います。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"リンクのことでちょっとお伺いしたいんですが、メーンの区のページからはそれぞれの事業部に行くんですが、これは全体が写っていないので下のほうに出るのかもしれませんが、逆に各事業部からメーンの品川区のホームページに戻れるものと、載っていないものとあるんですが、その辺の関係と、あと、逆に横のリンクというんですか、区民生活事業部から例えば福祉事業部に、横のリンクが行けるのかどうか。","respondent":"山田広報広聴課長","answer":"基本的にはそれぞれのホームページとうちのトップページとは必ず横の関係で行ったり来たりできるようにしていきたいということと、今ご指摘のとおり、そこからまた事業部、ほかのところにトップページに戻らずに行けるかどうかについても、張り方の問題ですので。","id":"exchange-007"},{"speaker":"三上委員","kind":"質問・要望","question":"そこらあたりをちょっと教えていただきたい。","respondent":"山田広報広聴課長","answer":"そのばらつきの中で査定をする中で、一応１部５０万円程度ということで、これは基本的には職員の手づくりをベースとしながらも、デザインでありますとか、いわゆる大量つくり込みでありますとかを考えますと、やはり業者の支援なくしてはできないだろうというところで。","id":"exchange-008"},{"speaker":"土井副委員長","kind":"質問・要望","question":"業者と打ち合わせをして、さてという話になりますと、費用の問題もさて置いて、同時性を追求すれば追求するほど、その場で直すというパターンがつくれるようにしていっていただきたいと思うんですね。今たまたま職員の中にすばらしい技能なのか、技術なのか、お持ちの方がいらっしゃって、それができるところもある、６事業部もあれば、また十分なところ、不十分なところ、いっぱいあるんだと思うんですね。","respondent":"山田広報広聴課長","answer":"ただ、今後の部分について、いわゆる業者との費用の問題等については打ち合わせをさせていただきながら、やはり一定のレベルというものは私どもも保持してまいりたいというふうに考えてありますし、研修についても。","id":"exchange-009"},{"speaker":"土井副委員長","kind":"意見","question":"そのとおりだと思うんですけれども、さまざまな研修があるんですけれども、この種のものには必ずしも全部が全部できる必要もないし、逆に全部が適任者であるとも思えない部分もある。これはしたがって、情報の話でもあり、人事の話でもありということになりますので、よろしくお願いをしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問","question":"この比較の方法というのは、ずっと変わらないんですか。","respondent":"古川人事課長","answer":"それぞれの自治体の規模等があろうかと思いますが、国も各自治体も人事委員会も同じ内容です。それから、その前提となる各種別あるいは責任度合いの調査、これも基本的には同じ考え方で実施して、こういうようになっております。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"変わらないというのは、地域でなく全国レベルということと、時間的に１０年置きに比較の仕方を変えようとか、そういうことはやっていないんですか。","respondent":"古川人事課長","answer":"人事委員会は５３年にご案内のとおり特別区が設置したと思うんですが、そのときからこのやり方は変わってございませんで、全国的に一定の仕事の方法である、こういうふうに理解しております。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問","question":"これだけ不況が来てしまって、民間の雇用情勢が厳しいということは皆さんご承知のことと思いますけれども、どう見ても逆のカスタムがあるようにという実感があるんですね。この比較の方法自体がこのままでいいのかという発想があるのかないのか、それから、今言ったようないろんなものを比較しなきゃいけないんじゃないかということについて、いろいろどういう考え方を持つべきでしょうか。","respondent":"古川人事課長","answer":"比較の方法につきましては、例えば平成１１年に人事院が１００人以上の規模ではなくて、より小規模で３０人以上をもとにということで、否定的であったということは聞いてありますが、なかなかそういう中では、それぞれもちろん企業の規模が小さいということもあるとは思いますが。","id":"exchange-013"},{"speaker":"塚本委員","kind":"質問","question":"助役に伺いたいんですけれども、どうも実感として民間に準拠していないというふうに思わざるを得ないんですけれども、年収として比較するべき、民間も年収ということで、これはある一定のところだけとってずっと比較して、こういう差ができるというふうな考えなのか、詳しくはわからないけれども、あと、ボーナスはどんどん減っていますし、何しろ高齢者の雇用の安定性が非常に悪くなっていますね。","respondent":"濱野助役","answer":"その認識については同じ認識を持っています。ただ、実務として今年、来年の給与を決定していくということの中では、やはりこの形が、もちろん最善ではありませんけれども、現時点でのとり得べき方式ではないかという、そういう認識です。","id":"exchange-014"},{"speaker":"塚本委員","kind":"質問","question":"民間の雇用の関係もかなりそういう状況に、５.３％なんて聞きますけれども、いろんなマジックを使っていると思う。今全然違いますからね。七、八年前からもう変えなきゃいけないという課題が目に見えていたのに、まだ昨日、今日と変えられないこと自体が問題なんで、これをどうやって、どういう手順で、どうしたら変えられるのかということをもう考える時期です。どうしたらいいんですか。","respondent":"濱野助役","answer":"これは基本的なところだと思うんです。そういう認識は持っております。","id":"exchange-015"},{"speaker":"塚本委員","kind":"質問","question":"後段以下が、どうしたら変えられるかということなんですが。これは政治の責任だと言われればそのとおりなんだけれども、現実日本でやっている政治を行うというのは半ば官僚ですかね。それで、そういう意識を働かせなきゃいけなかった。それは政治ばかりじゃなくて、皆さん方当事者の責任でもあると思うんです。その辺は。そこのところを聞きたいんです。","respondent":"濱野助役","answer":"公務員のほんとうの意味での一番大きな根幹の制度というのは、一自治体の力ではどうにもなりませんけれども、認識としては先ほど申し上げたような認識を持っていますし、現状の時点での打開策として、今申し上げたようなことがとれるのかなというふうに考えてあります。","id":"exchange-016"},{"speaker":"塚本委員","kind":"質問","question":"やはり雇用関係がもっともっとフレキシブルで、タイトじゃないですから、要らないものはすぐやめる、そして給与の上げ下げで、上へ行けば行くほど首を切られるような、そういうことをしないと、これだけ時代が進んで、社会が変わっていることに対応できないという、雇用の場合はミスマッチが行き過ぎちゃってここまで来た。品川の場合は、それでも懸命の枠内で努力しているのは認めます。その辺はどうですか。","respondent":"濱野助役","answer":"その民間企業、その企業にとっては、経済のあり様だとか、企業が取り扱っていた業界の業態のあり様というのは全く変わっていたにもかかわらず、そこのところへの認識が足りないか、あるいはそれへの対応策を怠っていたために、非常に老舗の大きな企業が倒れてしまう。","id":"exchange-017"},{"speaker":"塚本委員","kind":"質問","question":"そういう状況をやはり共通の認識として持つべきだし、今助役のお話を伺えば、僕たちもそういう世代ですから、ほんとうに厳しい年齢で、もう大丈夫だと思った人がどこか首という対象に、路頭に迷わせているということが出てきているわけですから、ここのところをもう一度、ほんとうにこれから真剣に認識しないと、国のほうから出てきたからこれでいい、仕組みが変わらないんだからしようがないよなだけでは。","respondent":"古川人事課長","answer":"私のほうから、助役のほうからも既にご説明がありましたので、基本的なこの勧告の制度の、また繰り返しになりますけれども、あくまでも人事委員会という第三者、専門的な人事行政機関が、先ほど申し上げました情勢の原則の中で。","id":"exchange-018"},{"speaker":"塚本委員","kind":"意見","question":"最後にしますけれども、これは勧告で、案が出て、お前たちが最終的にどう読むだろうという話も我が責任として承りましたけれども、いずれのときか、それじゃだめだという日が来るのかなと、その準備を我々もしなきゃいけないなというふうに個人的には思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"林（宏）委員","kind":"確認","question":"総括的に、今塚本委員から出ましたけれども、ちょっと具体的に確認したいんだけれども、この対象の事業所の中に、品川区の事業所というのは何社ぐらい入っているのか、何人ぐらい入っているのか。それから、今の話にあった中で、いわゆる労働時間についてはどういうふうに、全く関係なく、労働時間というのは全く無視なんだということなのか、その辺ちょっと教えてくれますか。","respondent":"古川人事課長","answer":"私どもも不勉強ですが、今回、人事委員会から出されました勧告のほうも、それから、それを詳細にまとめた資料がありますけれども、先ほど申し上げた７２０社、これは特別区２３区の中で一定の要件を備えた事業所を抽出してございまして、実際にそれぞれ調査していく中で。","id":"exchange-020"},{"speaker":"林（宏）委員","kind":"質問","question":"民間だと例えば１,８００時間という一つの世界的な基準というのはつくられているけれども、例えばその４０万円の水準まで行くには、１２時間、１３時間働かないと、いわゆる残業があるとか、そういうものを加えていかないと、その金額にならないというところも民間でいくと結構あるわけですよね。そうすると、東京都はどういうところと比較してやるわけですか。","respondent":"古川人事課長","answer":"東京都も先ほど申し上げましたように、基本的には１２０の事業所で同じです。ただ、エリアが２３区だけではなくて、都下全体に入る。若干数が多いわけです。","id":"exchange-021"},{"speaker":"林（宏）委員","kind":"質問","question":"わかりました。そうすると、東京都がやるなら、東京都の区部部分だけで持ってきたって同じような、乱暴な言い方をすると、２３区の人事委員会というのは、ここのところばたばたいろいろ話に出ている。いろいろ問題はありますよ。上げ下げも含めて。それで、この人事委員会の第三者的な立場というものに対して、それぞれの区としては、さっき勧告と言われたけれど、どういう関係にあるんですか。","respondent":"古川人事課長","answer":"勧告どおり実施する、しないは、基本的には各区、２３区の区長がそれぞれの考え方の中で、２３区の統一した交渉の場で、そのことについては交渉の過程で明らかにしていく。それをどう各区が最終的にまた議会の中に生かしていくか。","id":"exchange-022"},{"speaker":"林（宏）委員","kind":"質問","question":"人事委員会はそういうふうにやれと言って設置されたものだから、別に縮小するとか、レベルを下げるとか、上げるとか、広げるとか言ったって、がんじがらめになっているわけで、そうすると、その人事委員会の仕組みを２３区でどう扱っていくかというのは、区長会であったり議長会であったり、要するに人事委員会の、それこそまた外側のところでやっていくということになっていくわけで、そういうことについて。","respondent":"古川人事課長","answer":"この二つがあいまって、それぞれチェックする。チェックというのもどちらかといいますと、任命権者の実施する任用関係、給料表も含まれておりますが、それに対するチェックもありますし、このような勧告もある、こういうことです。","id":"exchange-023"},{"speaker":"林（宏）委員","kind":"意見","question":"今まさしく言われたとおり、もう法に基づいて、現段階ではあるべき仕組み、組織なわけで、それを一担当課長が要らないとか言うのは無理なんだろう、無理というよりも筋違いの話だろうと思う。ただ、我々とすれば、これからの自治体の給与の決め方とか、人事についての適切な税金の配分とか考えていくと、やっぱり各区で真剣に取り組んでいかなきゃいけない事柄の大きい一つだろうと思うんですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"三上委員","kind":"質問","question":"制度そのものが確かに民間では４月に昇給したということで、その時点の調査を、これは参考にするということであって、それに基づいて公務員の給与改定を、その辺を調整してもその時点にしたとしても、実際に勧告した時点が、それならそれでいいということであれば、それはそれでいいというふうに、私はそういうふうなシステムを変えるということになると。","respondent":"古川人事課長","answer":"そういうことで言いますと、必ずしも４月にさかのぼるということは基本ではないというふうに思ってありますが、本来の給与改定を４月の部分が民間の実態調査等々、あるいはまたできれていないという部分を見ていく中で、予算等を検討していく。","id":"exchange-025"},{"speaker":"三上委員","kind":"質問","question":"そうすると、実施ということについては、先ほど来解説の、各区が独自性をもってそれは決めるということは可能なんですか、それとも２３区の人事委員会としてはそういうような形で今やっているわけですから、２３区のきちんとした統一性の考え方でいくのか。","respondent":"古川人事課長","answer":"しかも、人事委員会が共同設置であるという中においては、２３区は同一の勤務条件を持つべきだろうという立場は人事委員会勧告の立場で出てあります。","id":"exchange-026"},{"speaker":"三上委員","kind":"意見","question":"妥結したときにその時点でじゃあというものが通常の考え方になってくるのが普通だと思うんですよね。〔「今年１０月昇給としてね」と呼ぶ者あり〕だから、そういうふうなことだっていいわけでしょう。","respondent":"古川人事課長","answer":"人事院が８月８日に１３年４月１日にさかのぼる、それはもう既に閣議決定をされて実施するという勧告もありますし、そういう中では、住民の感覚からのずれというのは確かにあろうかと思いますが、従来から４月１日に改定すべき、その規定もそこに置いて、１３年４月１日は実施日。","id":"exchange-027"},{"speaker":"土井副委員長","kind":"質問","question":"そうなると、やっぱり今ほんとうに給料表のつくり方、組み立て方、何級何号法というあのやり方、昇格の仕方、それから早さ、遅さ、こういうものがいわゆる評価制度ということになりますかね、人事考課制度になりますか、その辺を含めたものがトータルがどうなっているかということが非常に大きな動きだろうと思うんで、そういうものがやっぱり真摯に議論がされて、かつ住民の、議会も含めて。","respondent":"古川人事課長","answer":"ということで、これについて、研究・検討するようなことが必要という表現がありますけれども、民間に比べますと、かなり遅い段階かもしれませんが、今のあり方について、人事課、総務課以下こういう考え方を持ってありますし、私どももそのように考えてあります。","id":"exchange-028"},{"speaker":"土井副委員長","kind":"意見","question":"これ以上言っても、書いてあると言えば書いてあるんです。問題は、検討を踏み越えた部分がどうなるかという部分だろうと思います。社会は野球で言えば、２軍にいるのも１軍にいるのもいて、１軍でも給与の高いのから低いのまでいて、しばらくしてＦＡ宣言をまともにできるのからできないものまでいろいろある。期待で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問","question":"一つは、生活のところがどうなのかというのと、あとは、私もかつて民間にいたときに特に経験したのが、バブルが盛んなときには、なかなかこれはもう来手がなくて苦労したんですけれども、ある意味では給与、労働条件というのは、これから人材を確保していく上では、非常にポイントになる、これはいつもそうなんですけれども、そういう点で、今まではずっと職員はとらないのでずっと来て。","respondent":"古川人事課長","answer":"人材の確保という観点で、何人どう採用するかという問題ではなくて、あくまでも各自治体のそれぞれ持っている任用、あるいは給与、この体系をどう適切なものにしていくか、これが大事であるというふうに考えております。","id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問","question":"これは先ほど人事委員会の制度そのものの意義というのは触れられておりますけれども、こういう今までの仕組みがある、そういう仕組みの中で、職員団体との話し合い等も進んできているわけですから、それに対しての２３区でちょっと今足並みがそろってきていないという状況の中で、品川区のスタンスというんですか、その辺のところを、考え方をお伺いしたいと思います。","respondent":"古川人事課長","answer":"２３区の統一的な事項と、それから各区の置かれている環境、その違いが徐々に明らかになってきているというふうに考えてありますが、少なくとも昨年の給与改定に当たりましての品川区のスタンスは、人事委員会の勧告を尊重していく中で、一定の妥結経過を踏まえながら。","id":"exchange-031"},{"speaker":"宮崎委員","kind":"質問","question":"最後の点について、ちょっと一言言っておきたいと思うんですけれども、これまでのやっぱり決め方のルールというか、やり方があるわけですから、これはこれで踏まえていったほうがいいんじゃないかなというふうに思います。この点だけ言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"林（宏）委員","kind":"確認","question":"確認だけしたいんだけれども、この間、高層区民住宅の分と、これは別なんですか。ちょっとそれの区別を説明してください。この間高層部分の大きい三十何階建ての区民住宅部分とは別で、これは低層の部分じゃなくて、それも全部ひっくるめてというようなことなんですか。","respondent":"西島経理課長","answer":"前々回でしたと思いますけれども、高層棟のガス設備、これもやはり相手が東京ガスでございまして、あれは住宅の部分ということで、今回のは低層棟の住宅、それから高齢者の施設、それから地域センターも入りますけれども、それを含めて全体の。","id":"exchange-033"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、ガスが危ないから電気オンリーというようなことを今まで言われていましたよね。これはそれとは関係ないんですか。熱源、いわゆるヒーター部分、クーラーとかそういう部分だけで、例えばお湯を沸かすのには、やっぱり従来どおり電気でやるんですよということなんですか。それとも高齢者住宅に関しても、いわゆるガスの炎が出るという仕組みになるんですか、その辺ちょっと教えてください。","respondent":"岡田施設課長","answer":"私のほうからご説明いたします。前回超高層棟の部分もそうだったんですけれども、基本的に湯沸かし、それから台所のこんろ、いろいろ検討した結果、ガスにしています。","id":"exchange-034"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、安全性というのを最大限配慮して、電気を熱源としてこんろ類はやめたという考え方はなくして、安全であるという根拠は何なんですか。特に高齢者棟の場合に。","respondent":"岡田施設課長","answer":"安全性につきましては、後ろのところにもありますけれども、やはりガスを検出しまして、即大もとのところを緊急遮断弁でとめるようなシステム、こういうのをだんだんできてまいりまして、これは十分に採用しています。","id":"exchange-035"},{"speaker":"林（宏）委員","kind":"質問","question":"ただ、こと火事ということに関しては炎のほうが僕はやっぱり怖さはあるんじゃないのかなと思うんだけれども、それについては十分な資料というか、安全性を確保できる資料があるんですか。","respondent":"岡田施設課長","answer":"あるいはマンションなどが既に建っておりますけれども、オール電化のところもあれば、やはりガスを今までどおり使っていて、十分安全性を確認している部分がありますので、そういう意味で、先ほど聞きましたけれども、区民住宅レベルという形で両方をバランスをかけたときに。","id":"exchange-036"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"火だけではなくて、爆発、うっかり火が消えちゃってというようなところもある。上とか下とか横とか影響が大きいと思いますので、十分に安全については、利用する人だからね、これはつくった後は。区役所で幾ら安全だ安全だと言っても、使う人がそれを認識しておいてもらわなきゃいけないので、その辺もきちんと伝えていただきたいということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"塚本委員","kind":"質問","question":"随意契約になっていますけれども、ガスの配管工事ですね、これは同等の技術力、あるいは会社の信用度からいって、ほかにもこの仕事に対する会社はあるんだろうと思うんですけれども、その辺はどうなんですか。","respondent":"岡田施設課長","answer":"小さな工事で、改修工事で何かを改修するのに付随するぐらいのガス工事ですと、品川区でも何社か指定された工事会社がありまして小レベルならできますが、これはできないです。","id":"exchange-038"},{"speaker":"塚本委員","kind":"質問","question":"小さな修理、家庭のガス管をつくり出すようなのは、町の工事屋が実際に働きますよね。このレベルの仕事は、それを下請に出すと、ほかの施工業者が出しているとは考えられない、みんな自前、東京ガスが工事をするんですか、その辺はどうなんですか。","respondent":"岡田施設課長","answer":"それは、私どもが例えば施設課が技術力を持っていたとしても、実際に手を出さない部分、あるいは施設管理の細かいところは実際に手を出す部分も緊急的にはやりますけれども、それと同じように、ガス会社が自分のところで抱えている部分と。","id":"exchange-039"},{"speaker":"塚本委員","kind":"意見","question":"それ以外のところとは直接契約ができない商習慣になっている、そういうことですね。わかりました。それと、この大もとと契約するときに、その先がどういう種類になるかということは、契約書で知ることができるのかどうか、本体でやるのか、その辺は。この下請会社に出すということは知り得る立場にあるのか、あるいはそういうこともネグレクトして契約する習慣になっているのか、そこのところをちょっと。","respondent":"西島経理課長","answer":"〔「契約時に」と呼ぶ者あり〕 契約時ではなくて、契約後に、実際に契約をして、その後に実際に稼働するときという時期になろうかと思います。","id":"exchange-040"},{"speaker":"中島委員","kind":"意見","question":"さっきもちょっとわからなかった点があるんですが、基本料金の件で、電気だとどういうふうな感じ、ガスの場合は使わないときはかからない、そこのことが初めてご説明があったと思うんですが、そこら辺がちょっとわからなかったんですが。","respondent":"岡田施設課長","answer":"ただ、それが非常に設定が低いんですね。それで、電気ですと、最大使うと思われる契約、例えば通常一般の家庭ですと４０アンペアぐらいの契約、この契約をしちゃいますと、電気は使わなくても、これは毎月払っていかなくちゃならない。","id":"exchange-041"},{"speaker":"中島委員","kind":"質問","question":"それは相当な金額の違いがあるんでしょうか。品川はそういう料金の問題で決めるのであれば、安全性のほうを最優先したほうがいいのではないかなと思うんですが、かなりの差額が出るのでしょうか。","respondent":"岡田施設課長","answer":"実は基本料金の話は付属で出た話だと思っていただければありがたいんですが、もともとガスにするか、電気にするかというのは、当然安全性の部分から入って、あと、利用勝手みたいなところ、そういうものを検討していって、その中で、やはり特に高齢者の関係の場合ですと。","id":"exchange-042"},{"speaker":"宮崎委員","kind":"確認","question":"１点ちょっと確認したいんですけれども、今の電気かガスかというのは、高齢者の部屋ごとに選べるとか、そういうことは可能なんですか。","respondent":"岡田施設課長","answer":"これはそこまでの自由性は、戸建ての住宅ですと、十分例えば一つの団地の中でＡというお宅は電気にする、Ｂはガス、これはあるんですけれども、複合施設で一つの建物ですので、ここまでの自由性は実はなくて、家庭用のガスこんろはガスならガス、こういう形です。","id":"exchange-043"},{"speaker":"宮崎委員","kind":"意見","question":"確かに先ほど課長が説明されたように、やっぱり火が見えたほうがいいというお年寄りもいるんですよね。その一方で、安全性というものがあるので、できたら選べれば、そのほうがいいなと思ったんですけれども。難しかったらしようがない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"北野委員","kind":"質問・要望","question":"もう既に９月２５日に契約をしていて、９月２６日から工事ということなんですけれども、それで、報告というのが今現在になったということの理由が、内容を検討していたということなのかどうか、ちょっと確認させていただきたい。","respondent":"西島経理課長","answer":"なぜ今日の報告になったかですが、契約をした日は９月２５日ということは、入札をした日ということでございまして、入札を受けた後に確認しまして、それから、決済をとって、それから、書類をつくるということで、ちょうど２５、２６日が総務委員会が入っていたと思いますが。","id":"exchange-045"},{"speaker":"北野委員","kind":"確認","question":"それで、すごい細かいところをお伺いするんですが、現在ガスのどういう機種のものをつけられているのかなというものを確認と、電気の場合だったら、一つのものとかというのが、今タイマーによってはガスが音が出て、自然的に何分たったらガスが自然的に消えて、タイマーの音がピッピッと鳴るとか、いろんな装置がついているんですけれども、今すぐに。","respondent":"岡田施設課長","answer":"ただ、こんろみたいな持ち運びが自由なものというものには、入居者のものでできると、こういう部分がありますから、例えば私はそういうハイレベルのものとなれば、それができるかなと思いますが、ただ、そういう最新型のものであるならば。","id":"exchange-046"},{"speaker":"林（宏）委員","kind":"質問","question":"不思議なことなんでお聞きしたいんですけれども、貯水池を設置する工事なんでしょう。それで、埋戻し式という土木工事が入って、土工って書いてあるね。５ページの３の工事概要というところで。何と言ったらいいのかな、わざわざこういうように書くものなんですか。要するに掘って、池をつくって、もとの公園の工事はまたお金がかかるんだろうけれども、平らに戻すというのは当たり前じゃないんですか。","respondent":"西島経理課長","answer":"当然、私ども事務方にすると当たり前のことですけれども、ちゃんと工事の工程の中にはきちっとその辺記載をしておきませんと、次の、今お話が出ましたように、次に今度は公園を整備するという工事が始まりますので、要するに現状復帰といいますか。","id":"exchange-047"},{"speaker":"林（宏）委員","kind":"質問","question":"ちょっと埋戻しにこだわって聞くと、その１というのはどこまで、掘ったまでなんですか。ちょっとその１の資料を持ってこなかったのでわからないのだけれども、その１というのはどこまでやって、その２というのは、埋め戻して、それでまたその３というのが今度は誘導管というのかな、流水管というのか、それがあるんだけれども、この池に関しては、１と２はどういうふうに区切られているのか、教えてください。","respondent":"西島経理課長","answer":"その１工事ですけれども、調整池を築造するための掘削工事ということで、工事概要で言いますと、まず掘削をいたしまして、これは土の量が約６,５００立法平米、それから、土留め工と言いまして、板を張って、土が崩れないような、それから地盤改良工事。","id":"exchange-048"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、その仕事の内容については１というのと２と一緒に、工事会社というのかな、施工業者としては全然違う業種なんですか。ちょっと何で１と２が分かれないといけないのですか。","respondent":"西島経理課長","answer":"それで、下水道局側の準備の関係と、それから地元の方の説明等を考慮いたしまして品川区が受託したものですけれども、できるだけ今年度中にこれは解決をしたいということで、できたところから順に発注をしていく、その関係でその１、その２工事を分割して発注したです。","id":"exchange-049"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、つながってくるんだけれども、その３の工事ができ上がって完成ということになると、その３工事というのも同時に並行してやったほうが早く完成になるんじゃないのかなという、まとめて決めちゃうという疑問が起きて、その３を何で品川がやらないのかなという、それから、ここを、一般質問か何かでもどなたかが言っておりますけれども、通行どめにまたなっちゃうのかどうか。","respondent":"西島経理課長","answer":"その３工事に伴う道路の件ですが、細かい話は私も聞いてございませんけれども、工事説明会を１１月１９日の説明会を予定しておるというふうに聞いておりますので、そこで細かい話をされるだろうというふうに聞いております。","id":"exchange-050"},{"speaker":"宮崎委員","kind":"質問","question":"老朽化が著しいということでのヴィムのほうから解約したいということなんですけれども、中途解約となると、普通違約金とかそういう問題が出てくるんですけれども、そういうもののほうはどういうふうになっているのかお伺いしたいというふうに思います。","respondent":"西島経理課長","answer":"土地建物貸借の契約書をつくりましたときに、契約の終了という項目がございまして、一つは過怠金等に貸し付けることが不足しですけれども、二つ目は貸し付けるときに、２次補修費を投入する計画はないというのが区側の考えですので。","id":"exchange-051"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、貸付料年間３００万円となっているんですけれども、それは中途で終わればその分までということになるんですか。それと、あともう一つ、ここでは土地の処分先未定というようになっていますけれども、ここに、旧一碧荘廃止処分となっていますよね。これは解体ということなんですか。","respondent":"西島経理課長","answer":"土地の処分先のことですけれども、この辺は、建物付きで処分したほうが有利なのか、建物を処分して、売ったほうが有利になるかについては、どちらが可能性があるかということも含めて、これから検討してまいりたいというふうに考えてあります。","id":"exchange-052"},{"speaker":"宮崎委員","kind":"確認","question":"建物付きで処分したほうが有利かどうかという、今のお話ですと、もう老朽化が著しいというふうに、要するにこれは使用に耐えられないという、そういう話じゃないでしょうか。そうすると、当然取り壊しということにならざるを得ないんじゃないのかなというふうに思うんですけどね。そこら辺のことは、今のお話ですと、まだ使用に耐えられるのかどうなのか、ちょっと確認したいというふうに思います。","respondent":"西島経理課長","answer":"一般的に考えれば建物を解体処分ということになろうかと思いますが、その辺は少し柔軟に有利な方法を選択してまいりたいというふうに考えております。","id":"exchange-053"},{"speaker":"宮崎委員","kind":"意見","question":"そういう立場であれば、先ほどのヴィムとの関係も中途で解約したらそこまでだと、３００万円掛ける何カ月ということになるんだという、そういう説明だったと思うんですけれども、そういう意味では、そっちのほうも同じ考えでいくんじゃないのかなというふうに思うんですけれども、先ほど複数になるよというような話だったんですけれども、今の、区に有利にというふうなことであれば。","respondent":"西島経理課長","answer":"ヴィムとの話ですけれども、実は１３年度いっぱいお貸しをするということも考えました。ただ、１０月末で営業を開始して、それをずるずる延ばしてしまうことで、区民の見る目がどうかということが一つあります。","id":"exchange-054"},{"speaker":"宮崎委員","kind":"質問・要望","question":"わかりました。実際にそっちのほうの事業というのが結局どうだったのかというのがわかれば、ちょっとこっちでは担当でないということになっちゃうかもしれないんですけれども。そういうかなり応援してやってきたんですけれども、その事業としてどうだったのかというところはどうなんですか。","respondent":"西島経理課長","answer":"一碧いきいきプランのお話だと思いますが、年４回、高齢事業課のほうで一碧荘を利用しましてバスで行きまして、いろんな陶芸教室だとか、歴史散歩だとかというふうなものを実施しています。","id":"exchange-055"},{"speaker":"塚本委員","kind":"意見","question":"こういうときに、大変売れない、はっきり言ってなかなか価格がかけられるかどうかということが疑問に。近傍でどのくらいの値がついているのかということと、それから解体費はどのくらい見込まれるのか。","respondent":"西島経理課長","answer":"どのぐらいで売れるかというのは、なかなか難しい。〔「近傍で何かあるかと聞いている」と呼ぶ者あり〕近傍で聞いたところ、最近であの近辺では取り引き例はあまりないというふうに聞いておりますので、ちょっとこれからいろいろ努力をしていきたいなというふうに。","id":"exchange-056"},{"speaker":"林（宏）委員","kind":"質問","question":"それこそ事業評価じゃないけれども、私が買うわけじゃないんだけれども、要するに売るしかないという判断をもうされているんだろうと思うんだけれども、先ほども出たほかの事業に生かして使うとかいろいろあったけれども、その辺の検討の結果はもう出ているということなんですか、売却、土地の処分先とか未定になっているんだけれども、いわゆる政策評価というような点で、ここの土地を処分するという。","respondent":"西島経理課長","answer":"旧一碧荘については廃止処分という決定をしています。","id":"exchange-057"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、先ほども言われていた伊東市に幾らかでもお金を、幾らかでもないな、大分大きいお金だよね、納めていくとかいうことになって、それから取得の金額だとかもろもろ考えていくと、幾らなら売るとか、幾らなら処分するんだというようなところまで相談はされているんですか。ただ単に処分と決めただけなんですか、それではいかにも僕は無責任過ぎると思うんだな。","respondent":"西島経理課長","answer":"そういうことも総合的に勘案をしまして、およそこのぐらいの金額というのは、私どもで内部で調査をしてまいりまして、その数字を含めて検討をした結果、廃止決定という結論を出したものです。","id":"exchange-058"},{"speaker":"林（宏）委員","kind":"質問","question":"もっと前からあの土地をどうするかということは、もう一碧荘を閉めてヴィムに貸した時点から、菅家委員が一般質問で松崎のことや何かを含めてお聞きしていますけれども、そういうことなんですよ。今、こういうふうにヴィムがもうお手上げだから、ここをお返ししますと言ってきた時点でどうしようか、使い道がないからやめようかというのは、僕は行き当たりばったりだと思うけれども、いかがですか。","respondent":"中尾根企画部長","answer":"一碧荘も含めてこの施設の問題ですけれども、実はこの９ページですか、今回の資料の裏方にも一碧荘のデータが書いてありますが、区が持っている保養施設およびこういう厚生施設については、長い間結局いろいろ検討してきた経過があります。","id":"exchange-059"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、じゃあ、ほかにキャンプに使えるかどうかわかりませんけれども、キャンプ地として利用するだとか、それこそもうほんとうにとってつけた健康塾というのをやったんだから、野原にして健康塾をもう一回あそこでやれば、それこそ品川荘に泊まって、あそこで運動させてあげればいいんだし、そういうふうに、健康塾がもう非常に僕はとってつけた事業だと思っているから、だから、そういう意味で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"塚本委員","kind":"質問","question":"全般的に大変実りある視察だったと思います。メーンである唐津市は、合併協議会が任意から法定にかわるというちょうど節目のときに行きまして、これも企画部長ですか、大変意欲的に取り組まれているということ、それからあの地域の地域性というものを強く感じましたし、まさしく７万だ、１５万だということの行政レベルでの有効性というようなものを肌で感じました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"林（宏）委員","kind":"意見","question":"確かに民間のいろんな意見を聞くというのは大事なことだし、それなりに貴重な意見を述べられているんだろうと思いますけれども、やっぱり行政の核心的業務だとか、理解だとか、そういうような財政のみではない部分があると思うので、何となくあれだけ大きくなっちゃうと、どこから手をつけていいんだという、全体でつけられないと言って、財務的な部分で一つ手を入れたという。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"田中委員","kind":"質問・要望","question":"１点は、総合窓口化をするに当たっての現状、品川区と大きく違う点は庁舎のスペースのあり方といいますか、窓口があれだけ広いものがあったからこそ、ああいう仕組みも導入できたのかなという部分も感じまして、これは将来の話になりますが、仕組みをもちろん検討していく中で、逆に効率性を求めたハードのあり方も将来的には検討しなきゃいけないのかなというのを感じました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"三上委員","kind":"質問・要望","question":"あとは、福岡市については、確かに首長がかわったということが最大の原因でもあり、一つの方向性が出てきているということを感じて、やり方としては、品川区の行革とは全くやり方が違うという中にあって、どちらがどうなのかということで、品川区の行革というのは、どちらかというと、逆に議会がかなりの勢力を持って、区民のいろんな意見を聞いて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"中島委員","kind":"質問","question":"唐津市は、非常に何か私も先ほど塚本委員がおっしゃられたように、町の中の唐津くんちですか、あそこで練習をしている青少年の姿に非常に感銘して、何か品川区に取り入れられるものはないのかなという、そんな思いで帰ってきたわけなんですね。それから、福岡市なんですが、初めにこの自治体のＤＮＡ革命というんですか、これは私は非常に興味を持って聞いてまいりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"宮崎委員","kind":"質問","question":"あれを参考にできればなというふうに思いました。こういう状況なものですから、私も担当課長に財政状況のほうはどうなんでしょうかと聞いたら、そっちのほうはあまり問題ないんだという、そういう答弁だったので、ちょっとその財政問題というのは、私からすると非常に大分大きな借金があるじゃないかというふうに思ったんですけれども、このずれという、そんなのもちょっと感じたんですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"北野委員","kind":"意見","question":"それから総体的に建物で言いますと、市民に対しての情報公開の部分とか、そういう市民が直接対話するところが入り口に近かったということでは、庁舎のつくり方もあるんでしょうけれども、やはりこの品川区でも情報公開の部分で、区民が行きやすい場所の設置というものも検討していくべきではないかなということを、唐津市と佐賀市と福岡市を見てきて感じたところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"土井副委員長","kind":"質問","question":"順番にいきます。福岡市ですから、政令指定都市ですから、もう県と同じような権能、能力のレベルを、官僚組織的にもそういうものがかっちりあるわけで、そこのところをどう崩していくのか、変革をしていくのか、その意識づけをどうつくるのか、こういうところに相当な力点を置くことが必要だというふうに、職員の皆さんも委員会の皆さんも感じて、その方向で進んだ。先ほどあった何カ所でもやっている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"林（宏）委員","kind":"質問","question":"１点だけいいですか。４５円で袋を買ってというような仕組みになっているんだけれども、ごみは有料、資源は無料という仕組みをつくり上げて、受益、応益のきちんとしたものを打ち出しているんで、ごみ、清掃そのものはこの委員会ではないけれども、そういう観点からも清掃、ごみやリサイクルというのをとらえていくのもいいのかなという気がしていました。ごみのカレンダーもありました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/901100?Template=document&Id=1562#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":65537,"voices":164}},{"id":"h13-20011106-6","meetingId":"h13-cm11","date":"2001年11月6日","dateIso":"2001-11-06","committee":"区民委員会","time":"午後１時０２分～午後２時３５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"原委員","kind":"質問・要望","question":"同趣旨の請願は、このところ数年にわたって、品川青色申告会、荏原青色申告会の両方から出されてきたものでございまして、内容的にも、今お読みいただいたとおりですが、青色申告会そのものは、その後の中小企業の規模のほうになっていて、この軽減措置を外されると、景気そのほかの、それでなくても今は大変厳しい中ですので、ぜひ一定継続をしてほしいという強い要望があるですので、今のお話ですと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"本田委員","kind":"質問・要望","question":"減額２分の１ですから、それは推測できますけれども、そういうことがよくわからないんです。これは目的税ですから、都市計画に係る整備事業に使うというふうになっているんだと思いますけれども、それはどういうふうに、いわゆる品川区民の税負担を軽減してくれという請願でありますけれども、そもそも税金がどういうふうに使われているのか。","respondent":"松崎税務課長、小栗区民生活事業部長","answer":"私どもの税目ではないので正確にお答えできないところもありますが、地方税の体系からいきますと、基本的には市町村税に位置づけられてあります。例えば補助２０５号線の整備事業、補助１８号線、補助３２０号線、目蒲線立体交差、品川中央公園用地、こういったものに含まれて、区の都市計画交付金として歳入になってあります。","id":"exchange-002"},{"speaker":"本田委員","kind":"質問","question":"こういう請願は、本来、区が直接でないから、実態もなかなかつかめない。都に意見を出してくれということでありますけれども、請願紹介人もいらっしゃるんですが、これは都にもこういう請願というのは出ているわけですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"原委員","kind":"意見","question":"ここが直接やっていることではなくて、区を通して、区のほうから都のほうにそういう形で意見書を出してくださいという形なんですけれども、多分ほかの団体も、都のほうの、今どこのというのはわかりませんけれども、話によると、そこからまた話がいっているというふうなことを聞いております。ここの団体、直接は多分東京都である青色申告会連盟のほうからいっているのではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"本田委員","kind":"意見","question":"理事者の報告だと、議会の決定が待たれるということで、公表できない。どうも全体的には、国の減税を渋っている態度があるというようなことでもあるのかどうなのか。だから、各区の議会から一番近いところからどんどんつきあげてくれという意味合いを持って、こういう請願が出てきているのか。その辺は何か情報は入っていますか。","respondent":"松崎税務課長","answer":"今までは、平成９年ぐらいから継続して、この請願が各区から出されてありますが、その後の取り扱いにつきましては、都議会の各会派で反対しているところは今まではなかった。今回もおそらくないだろうというふうには聞いてあります。","id":"exchange-005"},{"speaker":"堺委員","kind":"意見","question":"今、課長のほうからご説明をいただきましたので、私としては理解したつもりであります。取り扱いについて、採択という形で、できれば全会一致という方向で上げればいいのかなという気がいたします。そういう意味では、本田委員がおっしゃるように全会一致で採択していきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"金高委員","kind":"提案","question":"このご時世で、確かに各自治体とも非常に厳しい財政状況だと思うんですけれども、それ以上に、２００m2以下の小規模住宅というのは、東京都の中において厳しい状態で生活をしている方々ですから、これが２分の１がなくなると、もっと厳しい生活を余儀なくされるということですから、これは引き続きお願いしていきたいと考えていますので、意見書提出については、採択していただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問・要望","question":"今の時代の中で税の軽減というのは何としても必要になっていると思います。私どもの会派でもこの請願については採択していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"菊地委員","kind":"質問","question":"業者のところから大変喜ばれると思うんですけれども、先ほど課長がお聞きしてくださった、どちらかというと、焼き肉店とか、お店屋さんが大変な状況であるという報告で、紹介状のほうも、この数字になっていますけれども、区でせっかくこうして対策をつくってきたんですけれども、緊急性から考えますと、購入負担金利ですか、0.５％というのは、実際には今の営業の厳しさから考えると。","respondent":"市川産業振興課長","answer":"ただ、最近新聞報道で、年末対策というので、特に特別区の場合、私どもの金利より下回っているところも結構ありますが、融資のあっ斡をしている資金が事業資金であるということを考えますと、私は0.５％という金利が、これが金利としてはぎりぎりの線ではないかというような。","id":"exchange-009"},{"speaker":"菊地委員","kind":"質問・要望","question":"確かに一般的な形で見れば0.５％というのは非常に安いと思うんですけれども、据え置き期間が１年ということで、この１年間の間にお客さんが戻ってくれば、それは返せる体制というのは出てくるんでしょうけれども、課長の目から見て、今の状況というのは、１年ぐらいでお客さんが戻るような形というのはできるかどうか。そのあたりをお聞かせいただきたいと思います。","respondent":"市川産業振興課長","answer":"一方で、消費者の心理的な冷え込みを緩めていくような対策というのが、これは国レベルで当然行われるものだと思ってありますけれども、特に年末の厳しい状況の中で、私どもは身近な事業者が持ちこたえていけるように、第一弾としてこういう手を打ったわけでございまして。","id":"exchange-010"},{"speaker":"原委員","kind":"提案","question":"区民チャンネルで見ていましたら、区ではこういう仕事をやっています。狂牛病に対してはあまりいい、ちゃんとした形で見ていたかどうかという印象がないんですけれども、それも含めて、ここの中でいろいろな意味で、提案していかなければいけないのなと考えています。トータルで結構ですけれども、ここ数年の中で、年末特別融資の状況はどういうふうな形になっているか。数年のところで結構です。","respondent":"市川産業振興課長","answer":"年末対策、ここ４年ばかり実施してきてありますけれども、大ざっぱな数字を申し上げますと、昨年が融資実績が１５億円、その前の年が２０億円、さらに１年前が４０億円出てあります。このときが一番ピークです。","id":"exchange-011"},{"speaker":"原委員","kind":"意見","question":"そうすると、やはりこの辺の枠を広げ方というものは、その辺のところはどうお考えになっているのか。例えばそれも含めて４０億円になる可能性もあるのかどうかということ。","respondent":"市川産業振興課長","answer":"一つに、融資実績が伸びた場合には、先ほどお話しした、４０億円に伸びたときもそうでございましたけれども、予算上のやりくりを、補正予算ということも含めて、また議会にお願いすることも含めて、一定の枠を絞って、その枠以上には受け付けませんという。","id":"exchange-012"},{"speaker":"原委員","kind":"意見","question":"今のお話のとおり、ひとつお願いをしたいなと思います。特に今回の場合は、実績が昨年でもまた増えていますから、３６件が６０件になっていて、そういう意味では、それだけ対応をうまくやれますようにお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"堺委員","kind":"提案","question":"確かにこの件については、１０月５日のアンケートで、取りくんでほしいというご提案があったという形で対応していただいているのは大変ありがたいと思います。確認をしたいんですが、１１月１日から始めて正味３日間で相談件数が９７件でしたね。最終的にそのうち狂牛病関連の対象になったのは１１件ということでしょうか。それを数が把握されておればお聞きしたいと思います。","respondent":"市川産業振興課長","answer":"１３件のうち１１件は即日に紹介状を発行して、２件が持ち越しになって、この持ち越しになっているというのは、紹介状を発行するに必要な書類が当日整っていなかったとか、そういう理由で持ち越しになったです。全体の相談件数の９７件に対して１０％強というような割合です。","id":"exchange-014"},{"speaker":"堺委員","kind":"質問","question":"これから増えてくるのかどうかわかりませんが、新聞発表以降、１日平均２０件の相談があったという割合から言っても、３日間だから、これから増えてくるかどうかわかりませんが、その辺の電話で相談とか、感触で、これから見込みというのか、その辺のつかんでおられる感触はどうなんでしょうか。","respondent":"市川産業振興課長","answer":"もう一つ、金融機関からの融資のほかに業界の中の組合融資みたいなものもございまして、その利用というか、私は間接的に聞いたことなんですが、国や東京都の対応策も遅れぎみなんですが、組合自身の金融もちょっとあたふたとしているところがございまして。","id":"exchange-015"},{"speaker":"堺委員","kind":"質問","question":"資金ぐりが困難ということで、売上等については全然関係なく対処しますという、今回のそういうのと関連して、経営相談といいますか、そういうところまで踏み込んだ形でのご相談もあるんですか。来る側のほうからしてみれば、ちょうどいい機会だから、この際、自分のところの経営全般についても相談に乗ってもらおうという形でお見えになる方もいらっしゃるんですか。","respondent":"市川産業振興課長","answer":"今委員のご指摘になった点、通常の相談の受付の際にも私ども窓口の相談員にそういうことを心がけてお客様の声を聞くようにということで申しているところですが、特に今回の場合、先ほど数字でちょっとご案内したように、飲食店の関係の方が比較的多いものでして。","id":"exchange-016"},{"speaker":"石田副委員長","kind":"質問・要望","question":"１点だけ私のほうからお聞きしたいと思います。それであるなら、それが４０億円なのか、そこの目安をどこに持っていくかというのがあるんだけれども、もっと違った意味の使いやすさというのか、そういうものをお考えに、これは何年間も一緒なんだけれども、これを再度、考え直すというような方法をお考えになったことがあるのかどうか、そこら辺だけ聞きたいというのが１点。","respondent":"市川産業振興課長","answer":"もう一方で、信用保証の制度についてもちょっとずつながらメスが入りつつある。その中で区の制度融資をどういうふうに持っていくか。これについては注意深くそういった制度の変遷を見ながら検討をしていきたいというふうに考えております。","id":"exchange-017"},{"speaker":"石田副委員長","kind":"質問・要望","question":"要望だけしておきますけれども、今のところで、今、信用金庫でも、銀行でも、多分信用保証協会がつかないとお金を出さないというような体制が結構あるようでして、プロパー融資は本当にしなくなってきて困っているという業者が多い。例えば５００万円というのは大金なんだけれども、５００万円が使い勝手がいい会社と、５００万円ぐらいではというところもあるわけですよ。これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"本田委員","kind":"質問","question":"今のご説明だと、そういう飛ばし方をした場合に、八潮団地の上空にかかってくるんですか。","respondent":"金井環境課長","answer":"現在も年間で二十数便飛んでいるそうですが、八潮上空には基本的に飛ばしていないです。ただ、風具合によっては、多少寄ったりする可能性はあるかもしれないけれども、基本的には八潮団地の上空は飛ばないということを聞いております。","id":"exchange-019"},{"speaker":"菊地委員","kind":"意見","question":"今の課長の説明でわからなかったところで、２で、有視界飛行による運航を前提としたノースバード運航を希望する会社は皆無だったと。会社そのものが無理ですという話なわけですね。３番の(1)にある、公用機についてはノースバードを使うんだというんですけれども、民間の会社の考えている、公用機だったら使うという、その違いがよくわからないんです。","respondent":"金井環境課長","answer":"ご案内のとおり、民間が地方からお客さんを乗せて定期便で来たときに、前にもちょっとご説明したかと思いますが、視程が８kmでないと降りられない、非常に難しいと。","id":"exchange-020"},{"speaker":"原委員","kind":"質問","question":"今も上回っているから、すぐにまた上がってもいいのかどうなのかなというふうに受けるんですけれども、それに対して、その下に1)、2)、3)と書いてあるんだけれども、これは大気汚染のことではなくて、工事区域の内容にかかって、その部分をどう解釈していいのか。現状も環境基準を上回っていて、なおかつここで工事を始めて、こういう形にすると、またそれも上回りますよということなんですか。","respondent":"金井環境課長","answer":"ですから、上回っていますので、工事中はそれを低減することはできないという意味も含めて、これは自動車の走行が主ですので、これは総合的に、東京都は来年の５月からディーゼル車の規制も始まったり、ＮＯXは来年の５月から厳しくなりまして、規制が始まります。","id":"exchange-021"},{"speaker":"本田委員","kind":"質問・要望","question":"しかし、住んでいる者としましては、どっちから出ようと大気汚染は大気汚染のはずですから、書き方についてもその辺は十分努力している姿を見せるような書き方があってもいいんじゃないかと、私も思いながら聞いておりまして、現場から、そういう状況をここでは表現しているんだなと思いながら聞いていたんですが、何となく縦割り行政といいますか、こっちとそっちは違うという印象さえ受けるんですけれども。","respondent":"金井環境課長","answer":"そこだけ捉えると基準が上回っていますよというような話になりますので、前回もちょっとお話ししたと思いますが、政策的に、特に国に先駆けて乗用車の規制とか、都知事が真っ黒いあれを持っていろいろお示しをしたりして取り組んでいるわけですので。","id":"exchange-022"},{"speaker":"本田委員","kind":"質問・要望","question":"そういう場所柄での大井清掃工場のプラントに伴うこういう状態ですから、そこに八潮団地という大きな団地があるわけですから、その辺総合的に配慮した環境改善というものが求められているわけですから、それに見合った、それぞれ清掃工場とか、道路建設とか、ディーゼル車規制とか、いろいろ総合的に手は打っていくわけですけれども、どうも今の説明のように、単発。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"原委員","kind":"意見","question":"報告書の中身の中に文章だけでなくて、写真の掲載等はどうかということです。それぞれ皆さん写真を撮ったり、事務局でも撮ってましたよね。写真の配慮を、例えば事務局で総括的に今までやっていた中で、写真いいですよということか、あるいは個人で写真を入れてほしいということがあれば、入れられますよとかというのは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/693840?Template=document&Id=2310#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":24496,"voices":72}},{"id":"h13-20011106-7","meetingId":"h13-cm11","date":"2001年11月6日","dateIso":"2001-11-06","committee":"厚生委員会","time":"午後１時５分～午後２時３５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"船波委員","kind":"質問","question":"以前、第三次長期基本計画の素案を練っていく会議でも３名だったんですけれども、例えば男性と女性が平等に参画できるということを考えれば、例えば４名であるとか、偶数の数のほうがいいのではないかと思いますし、また地域という面でも、地域に密着して健康づくりができるというが目的にもなっているわけですから、品川区の地域というのも荏原と品川というだけではなくて。","respondent":"田中健康課長","answer":"例えば、今、委員がおっしゃったように地域性ということで、例えば大井・品川・荏原という地区の割合もありますが、それではある意味で地区割であって公募委員ではないような気もしますし、今回は医療関係団体が一つ大きなパターンを占めるところと、ほかにつきましては地域団体。","id":"exchange-001"},{"speaker":"須藤委員","kind":"質問","question":"２番目に「保健・医療・福祉」という言葉が入っているんだけれども、別紙１で企業というのはどこを指しているのかなということが１点。それから、医療関係で、前から我々は柔道整復師もどうだというようなお話をしたんだけれども、その辺のところはいかがなものでしょうか。","respondent":"田中健康課長","answer":"今回、企業という形で検討させていただきましたが、そこのところまで具体的な団体というところまでは至らなかったというのが現実です。","id":"exchange-002"},{"speaker":"須藤委員","kind":"質問","question":"ですから、これはどこまで決めてこういうふうにしちゃったよというお話を取っちゃったのかどうかわからないんだけれども、その辺のところの考え方というのを、もう既に各医師会、歯科医師会と進めちゃって、もうこれは変更できませんよという話になっちゃっているのか、あるいは今お話したようなことが、この委員会から話が出て、それではということができるのかどうかお聞かせください。","respondent":"田中健康課長","answer":"委員のご指摘はもっともな点、多々あると思います。実は、私どももそういう議論もいたしまして、一本化できないかという話もいたしましたが、従来の保健所運営協議会等がある程度網羅的にお願いしていたせいがございまして、そこに引きずられた面は確かにあります。","id":"exchange-003"},{"speaker":"須藤委員","kind":"質問・要望","question":"健康づくりというのは、前から言っているように非常に広い範囲で、いろんな人たちがいろんな考え方を持ってそれぞれ健康に関心があるというのが現在の世の中なので、いろんな声が相応に上がってこようかと思いますけれども、その辺のところも配慮しながら、今度の政策をつくっていただければと思います。内容的については、我々も会派としていろいろ要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問","question":"委員会の皆さんが策定した計画をつくった後、それを品川区がどういうふうに展開していくかということの、今のところの見通しを教えていただければありがたいんですが。","respondent":"田中健康課長","answer":"これが実際の事業運営にどういう形で展開されるかですが、ここがまさしく私どもが一番プラン２１に対して皆さんにご検討いただく中身と思ってあります。","id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問","question":"今の課長のご説明の中で、「体系化・重点化を図る」と、ここにも書いてありますけれども、先ほどの須藤委員の指摘にもあったように、それだったらどうして企業の意見し合う場がないのかということが、当然企業の方も区民でありますし、障害をお持ちの方も区民なわけですから、それこそいろんな分野の意見を取り入れていく仕組みを考えていくならば。","respondent":"田中健康課長","answer":"先ほどもご答弁申し上げましたが、今回企業のご意見を何らかの形で反映したいということもございまして検討はしてまいりました。そういう事務関係の方からも、民間の団体等という話もあったんですが、まとめ切れなかったというのが現実です。","id":"exchange-006"},{"speaker":"鶴副委員長","kind":"質問","question":"委員の構成を見ますと、それぞれのセクションごとに推薦をしてくださいということになるわけでしょうか、推薦区分というふうにありますけれども、委員の指名は公募以外はどうなるんですか。","respondent":"田中健康課長","answer":"この推薦区分のほうへ推薦をお願いいたします。ただ、例えば学識経験者の先生等は、ある程度設定をした上でお願いをするということで、ご本人の内諾もいただいておきながら、団体には推薦をお願いしています。","id":"exchange-007"},{"speaker":"鶴副委員長","kind":"質問","question":"そうすると、どういう方が委員になってこられるかわからないわけですね。ただ出席してきて、イエスマンでは仕方がない。そして、プラン２１を策定して公表するという段取りですけれども、そのたたき台というのは区の健康課でたたき台を考えて、そして提示して論議をしてもらうんですか、どういうことなんですか。","respondent":"田中健康課長","answer":"そういう考え方で、全くフリーハンドでお願いするというのは、なかなかエリアが広過ぎるような気がいたしますので、私どものほうからそういう点での資料というか、たたき台的なものはご提示申し上げながら議論を進めするように考えてあります。","id":"exchange-008"},{"speaker":"鶴副委員長","kind":"質問","question":"どちらを選択するかとなると、どうも課長の答弁によると、やむを得ないから行政主導型で基本的な考え方を提示して、それでお話をされて、それでまとめるというニュアンスが強いわけですね、どちらに重きを置いた品川健康づくりプラン２１ということになるわけでしょうか。","respondent":"田中健康課長","answer":"ただ、これは行政主導という言葉がどういうニュアンスの言葉の強さかとなると、非常に難しい要素があると思いますので、私どもはやはり行政の立場で品川健康づくりプラン２１というものをつくるということでは。","id":"exchange-009"},{"speaker":"鶴副委員長","kind":"質問","question":"喧々諤々な論議があったかというと、どうもそうではない。今回は全く議会サイドの委員というのはないわけですから、自由な発想に基づく実り多い論議を、議会の議員を気にすることのない論議が展開されるのかなというふうには期待はしております。そしてそれが「品川健康づくりプラン２１」という形でまとめられていくのかどうかという、そこのあたりが気になる点なんです。","respondent":"田中健康課長","answer":"行政主導というのは、確かにこういう方向でというところがあっていく場面も結構あるかと思います。ただ、今回私どもはそこまでのところはまだ持っておりませんし、整理をして皆さんにご参加をいただいて立ち上げていこうかなというふうに考えているところです。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"いきいき２１ですか、健康づくり区民会議の中には関係団体と地域住民団体の代表、それからボランティアというふうに書いてあるんですけれども、ボランティアというのが今回入っていないんじゃないかと思うんですけれども、そこのところがどうなっているのか教えてください。ボランティアの登録というのは、実際何人ぐらいになっているのかも合わせて教えていただきたいと思います。","respondent":"田中健康課長","answer":"健康指導者という形のボランティアですが、ボランティア自体が登録をですが、毎年の体系づけた登録になっていないものですから、ちょっと数的には抑えきれていないところがありまして、そちらからきちっとしたご意見をというよりは、今回プランづくりを進める中で。","id":"exchange-011"},{"speaker":"船波委員","kind":"質問","question":"インフルエンザの予防接種については、一口にインフルエンザといっても流行する型が幾つもあって、流行する型と予防接種の型と合ったり合わなかったりというようなことがあって、それによって効果もどうなのかなと思うんですが、これから流行すると思われる型に対して予防接種をするという型は合っているということがわかっているんでしょうか、予防接種の効果についてお伺いしたいんです。","respondent":"小林品川区保健所保健サービス課長","answer":"予防接種の効果についても、集団の防止効果は確かに接種率が８０％以上超えないと効果が薄いと言われておりますけれども、個人個人の予防については、今言いましたように型が合っておりますので十分効果は得られるだろうという、そのような考えに基づいております。","id":"exchange-012"},{"speaker":"船波委員","kind":"質問","question":"この説明によりますと、希望する個人がはがきによって申込むということになっていますが、高齢者の施設に入っているような方はどうなるんでしょうか。はやるときには、そういった施設のほうがはやってしまうのではないかと思いますが、そういった施設に入っている方はどういうふうに希望を取るとか、あるいは集団で接種するとか、その辺はどうなんでしょうか。","respondent":"田中健康課長","answer":"高齢者の施設に関しましては、今までも個別に施設で対応いただいております。今回も同じ立場でご利用いただけるものというふうに考えてあります。","id":"exchange-013"},{"speaker":"船波委員","kind":"質問","question":"個別にということは、施設ごとということですか、それとも施設に入っている個人個人ということなんでしょうか。","respondent":"新美保健高齢事業部長","answer":"区内の高齢者の場合ですが、入所施設についてはやはり集団で生活をしているという関係で、従来から各施設でそれぞれの施設入所者に対してはインフルエンザの予防接種等をするなど、それぞれの施設ごとに対応をやっているところですので、そういったことを踏まえつつ。","id":"exchange-014"},{"speaker":"船波委員","kind":"質問","question":"施設ごとに決めるということですけれども、今までは施設の場合、大体接種をしていただくということなんでしょうか。それから、区の負担が２,３００円ということですが、この財源はどうなるんでしょうか。","respondent":"田中健康課長","answer":"これが各自治体も悩み中の悩みでございまして、今回につきましては国のほうは何の財政的手当てもしてこなかったという状況です。これは各自治体とも大変な思いで持ってきまして、自己負担の考え方につきましても大変な議論をしてきたところです。","id":"exchange-015"},{"speaker":"船波委員","kind":"質問","question":"この法律が１０月３１日に成立したということですが、今後は毎年この法律に基づいて、同じように行われていくということでしょうか。","respondent":"田中健康課長","answer":"法律上、二類疾病という形が改正されない限りずっと続きます。ですから、来年以降も同じような形で、予防接種について対応する必要があろうかというふうに考えてあります。","id":"exchange-016"},{"speaker":"船波委員","kind":"質問","question":"区としては、もちろん効果があれば区民の方にたくさんやっていただいてもいいわけですけれども区の負担もあるわけで、なるべくやったほうがいいというようなスタンスなのかどうか伺いたいと思います。","respondent":"小林品川区保健所保健サービス課長","answer":"特に、高齢者の方々は基礎疾患を持っておられる方が多いと思いますので、十分そのあたりを配慮しながら接種していただくように、区としてはそれを支援するという形になるというふうに認識しております。","id":"exchange-017"},{"speaker":"嶋委員","kind":"質問","question":"今の時代にはがきというより、電話とかファックスとかというのはお考えにならなかったのか、まずお聞きをしたい。それから、協力医療機関名簿をくださるというなんですが、これは地図がつくのかどうかということ。私の地域なんかは、だんだん近くに医者がなくなっていくということがあるんですけれども、どのぐらいの協力医療機関に協力をいただけるのかお聞きをしたいと思います。","respondent":"田中健康課長","answer":"今回の対象の数ですが、これが非常に難しい形でございまして、今、区内で対象の方がトータルでは５万８,０００人ほどいらっしゃるんですが、その中の３０％ぐらい現在お受けいただけるかなというふうに見込んで、一応考えているところです。","id":"exchange-018"},{"speaker":"鶴副委員長","kind":"質問","question":"ところで、予防接種の効果ですね、普通専門の人たちに言わせると、やっぱり１回じゃだめなんだと、２回必要なんだというふうに言われているじゃないですか、そこあたりはどうなんですか。","respondent":"小林品川区保健所保健サービス課長","answer":"それは、やはりそのような研究の結果に基づくものでございまして、１回と２回とでは特に差がなかったという結果に基づいたものです。ただ、どうしても２回希望される場合は、任意で接種していただくという形になります。","id":"exchange-019"},{"speaker":"鶴副委員長","kind":"質問","question":"何が効くのか効かないのか、データ的に１回でいいと言われれば「そうか」と。それから、気になっていたのは、さっき言ったように今度は子どもが希望して予防接種をしておこうという場合、乳幼児医療費の範疇に含まれていることなのかどうなのかと、インフルエンザの予防接種は乳幼児医療費助成制度の対象外ではないのかというふうに思っているんですが、そこのあたりはどうなんでしょうか。","respondent":"田中健康課長","answer":"４,５００円というのも、法律で決まっているものではございませんで、三者協という形で決めたのが４,５００円という単価でございまして、例えば東京都以外にいきますと、また別途の考え方もありますし、というところで動いているところです。","id":"exchange-020"},{"speaker":"鶴副委員長","kind":"質問","question":"この法案に関係なく、要するに今回の法案は６５歳以上の接種を希望する人で、別に義務を課せないわけですよ。それはわかっていて、なおこの範疇の中に子どもが入るかなんていうことを聞いていないんですよ。だから、それは品川区で言うところの乳幼児医療費助成制度の中で含まれるのですか、含まれていないのですか、除外されているのですかということを聞いただけのことなんですよ。","respondent":"日下部障害者福祉課長","answer":"インフルエンザが乳幼児医療費助成制度の対象になるかどうかですけれども、基本的には自由診療ですので、助成の対象には入らないのではないかと理解をしております。改めて、その辺の事実関係については、再確認をさせていただきたいというふうに思います。","id":"exchange-021"},{"speaker":"鶴副委員長","kind":"確認","question":"私が聞いたのは、乳幼児医療費助成には所得制限がありますけれども、現行の乳幼児医療費助成制度の中でインフルエンザの予防接種をした場合には、その対象に含まれているのですか、含まれていないのですかということをただ聞いただけなんですよ。おそらく含まれていないというふうに思っているんですが、それを確認しないと次のことにいけないから、それで念のために聞いたんですよ。","respondent":"日下部障害者福祉課長","answer":"基本的には、乳幼児医療費助成制度の対象外と、副委員長のご指摘のとおりだというふうに受け止めております。","id":"exchange-022"},{"speaker":"鶴副委員長","kind":"提案","question":"これが成立する前に、私が考えていたことは、高齢者は集団的にインフルエンザが発生したという背景を踏まえて、今回の法律が提案されて、ようやく成立したということなんです。子どもたちにも、例えば４,５００円ではなくて、医療機関によってもっと高いところもある。高いでしょう、普通どのぐらいですか教えてほしいんですが、三者協で４,５００円、通常予防接種する場合、どのぐらいになっていますか。","respondent":"小林品川区保健所保健サービス課長","answer":"はっきりとしたことは申し上げられないんですけれども、情報として区民の方からいろいろ聞いているところによりますと、安いところで２,０００円、高いところで１万円というような幅があります。","id":"exchange-023"},{"speaker":"鶴副委員長","kind":"質問","question":"専門の先生に聞いておきたいんですけれども、予防接種のインフルエンザが医療機関によってどうしてそんなに差が出てくるんですか。これは一体どういうことなんだろうと。Ａというところに行ったら２,０００円、Ｂというところに行ったら１万円、効き目の中身が違うんですか。","respondent":"青山品川区保健センター所長","answer":"ただ、健康保険の中に含まれているものですと、健康保険点数という形で価格が決まってくるんですけれども、こういった自由診療、健康保険外のことになりますと、個々の医療機関において、例えばその先生がご自分の能力、資質等のことや設備そのほか。","id":"exchange-024"},{"speaker":"嶋委員","kind":"質問・要望","question":"ですから、打つなら今が一番いいという朝のニュースでした。そのときの状況もあると思いますが、これだと１１月２１日号の予定で、それを見てからとなるとやはり１２月に入ってしまうのかなと思いますので、なるべく早い時期に予防接種の実施ができるようにご配慮いただきたいと思いますので、よろしくお願いいたします。","respondent":"田中健康課長","answer":"私どもとのご説明と連動してやらせていただいておりますし、今、委員ご提案の広報につきましては、できる限り何らかの方法を考えてみたいというふうに考えております。","id":"exchange-025"},{"speaker":"須藤委員","kind":"意見","question":"１点だけ、先ほど高齢者の特別養護老人ホーム等の施設については、以前から個々に対応しているというお話だったんですけれども、この法律ができて、先ほど田中健康課長から行政としてはできるだけ接種の方向が望ましいので、そういう広報をしていきたいというお話ですけれども、むしろ先ほど言われているように、集団的に高齢者がいらっしゃるところではやると一番大変だなと思うので。","respondent":"新美保健高齢事業部長","answer":"基本的には、予防接種対応を各施設でやっているというふうにいろいろなところで聞いておりましたけれども、改めて区内の全施設確認をし予防接種は徹底するように、集団生活ということがありますので、その辺は今回していきたいというふうに思っております。","id":"exchange-026"},{"speaker":"須藤委員","kind":"質問","question":"今まで、施設ではどういう形になっていたか、いわゆる保険外の自由診療の形ですから、それで健康管理ということで各施設でおやりになっていたんじゃないかと思うんだけれども、考え方としては同じようにこういう対応ができますよということで、むしろ進めていかれたほうがいいんだろうと思うんですが、その辺のところはいかがでしょうか。","respondent":"新美保健高齢事業部長","answer":"それに対して在宅の方と同じ公費助成的なもの、自己負担は基本的には施設によるかと思いますが、ない形が多いのではないかというふうに受け止めておりますが、もう１回その辺の確認と、施設の対応としてやるべきことなのか。","id":"exchange-027"},{"speaker":"船波委員","kind":"質問","question":"入居登録者４０名程度を募集するというのは、４０名に設定したのは、１年間の間に登録していれば入れるのではないかという予測に基づいて、大体はこのぐらいということになっているのでしょうか。","respondent":"野田口高齢事業課長","answer":"そういった意味で登録も困窮度に応じてやっておりますので、そういった意味で幅を見て通常３０名から４０名ですけれども、４０名の登録ということで考えているものです。","id":"exchange-028"},{"speaker":"船波委員","kind":"質問","question":"予想される空き部屋の発生というのは２０室ぐらいだけれども、登録は４０名ということなんでしょうか。そうすると、はじめから４０名を登録するけれども、半分ぐらいというか、決められて１年間の間に入れなくて残ってしまう人というのは既に折り込み済みなんでしょうか。そういった場合、残ってしまった方は指定されている期間の後はどうなるんでしょうか。","respondent":"野田口高齢事業課長","answer":"ちなみに、平成１１年に４０名募集していますけれども、そういった方は現時点では何らかの形でほとんど、すべて区のほうで対応したということではございませんけれども、自力での解決も含めて、そういった意味では解決が進んでいるです。","id":"exchange-029"},{"speaker":"嶋委員","kind":"質問・要望","question":"毎年ひとり暮らしの方は、１２月しか申込みができないというのが多いと思うんですが、昨年もたくさん見えていたと思うんですが、昨年の見えた方の人数を教えていただきたいと思います。","respondent":"野田口高齢事業課長","answer":"昨年の申請状況ですけれども、２１０名です。内訳を申しますと、本当に緊急度の高い取り壊し・立退きといった件数が１３件といった状況です。途中で取り下げた人が１２名ということで、入居要件の該当者が１９８名です。これは幅広く取った場合、そういったことです。","id":"exchange-030"},{"speaker":"嶋委員","kind":"質問・要望","question":"これは登録制ということなんですが、１回登録をすると何年間保証というのか、１回申込めば何年間大丈夫だというお話を聞く方もあるとか情報的なものが違うので、教えていただきたいと思います。","respondent":"野田口高齢事業課長","answer":"例えば今の時点でまだ入居できない１３年度の登録者の場合には、入れないこともあるからこの時期に申込んでくださいというようなことで、ご案内を申し上げているところです。そういった意味では、１年間です。","id":"exchange-031"},{"speaker":"嶋委員","kind":"質問","question":"私のほうにも相談に来る方が、やはり高い家賃を払っていて、「もう、だめ」と言いながら１２月を楽しみにしていらっしゃる方がいらっしゃいます。自力でということもありますけれども、やはり自力でも大変厳しい方もいらっしゃるんですが、１２月に入れなかったらほかに何か区のほうであっせんというのがあるんでしょうか。","respondent":"野田口高齢事業課長","answer":"同時に、両方とも申請していただきまして、どちらかで解決していく。場合によっては、有料老人ホームとか私どもの持っている情報を、一人ひとりに合った解決につなげていくという方法で取り組んでいきたいと考えています。","id":"exchange-032"},{"speaker":"嶋委員","kind":"質問","question":"きちっとフォローをしていただいているということで、よろしいんでしょうか。","respondent":"野田口高齢事業課長","answer":"登録なさっても、「まだですか」というような問い合わせは定期的にありますので、そういった時点できちっとフォローしていきたいというふうに思ってあります。","id":"exchange-033"},{"speaker":"鶴副委員長","kind":"質問","question":"それは見なかったら見なかったで別でいい、あるいは予定はあくまでも予定であって、このウェルフェアテクノハウスを見たということだけを書けばいい。そういう施設はどういう施設であったというか、それで十分じゃないですか。見てきたことを書けばいいんじゃないかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"鶴副委員長","kind":"質問","question":"できれば、定例会が始まるまでにということでいいじゃないですか、あれはいつ招集でしたか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"須藤委員","kind":"意見","question":"書記に整理してもらって、またそれをこっちに戻してというのではなくて、出されたものを正副委員長にお任せしますから、長ければカットするなり、短ければ正副委員長がフォローして、きちんと合わせていただいたやつを持っていったほうが、また戻ったああだこうだというと時間がかかっちゃうでしょう。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"鶴副委員長","kind":"質問","question":"現実的には提出されたものをそのまま、例えばパソコンで打ってプリントアウトする人も出てくるでしょうし、あるいはワープロで打ってプリントしたものを提出する人もいるでしょうし、あるいは原稿用紙で４００字詰めで書く人も、全部そのままというやつでいいんじゃないですか。提出されたそのままを報告書にまとめたほうが生々しいじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"須藤委員","kind":"質問","question":"まとめるのは正副委員長、そして、またこっちに戻してというと大変じゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"鶴副委員長","kind":"質問","question":"あんまり長く書くことはないんじゃないかというふうに思います。資料もあることだし、主だったところを、一番印象に残ったところをお書きいただければいいんじゃないですか。はそれぞれ資料をいただきましたので、詳細は別添の資料ということで。まとめるときにはＡ４の用紙で、原稿用紙でも構いませんけれども、原稿用紙でもできればＡ４の原稿用紙みたいな形でお願いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/498533?Template=document&Id=3002#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":25913,"voices":104}},{"id":"h13-20011106-9","meetingId":"h13-cm11","date":"2001年11月6日","dateIso":"2001-11-06","committee":"文教委員会","time":"午後１時５分～午後３時５８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を55件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"川西委員","kind":"質問","question":"非常に幼稚な質問で、まことに申しわけない。ちょっと私、こういうのの見方にまだ慣れてないんです。今、例を挙げられて、荏原第一中学校と戸越台中学校で、３０人とか４０人の受入れに対してというようなことをおっしゃったんだけど、住民基本台帳による予定者数というのが、本来、学区域があったとすれば、これだけの子どもが来ると見てよろしいのかどうか。ちょっと見方を教えてください。","respondent":"久保田学務課長","answer":"荏原第一中学校につきましては、４１人ということで、１人上回っているわけですけれども、十分に施設の中で受け入れ可能ですので、抽選は行わず、そのまま受け入れるという考え方です。","id":"exchange-001"},{"speaker":"川西委員","kind":"意見","question":"わかりました。そうしますと、現在の学級数の学校の要覧を見て、この数字を当てはめて、来年度の新１年生はどのぐらいの学級になるかということを判断して、想定しないとわからないですね。そういうことですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"桜井委員","kind":"質問・要望","question":"あるいは、減で見たときに、大きく違うのが、大崎中学校の場合に、平成１３年度はマイナス３０人で、今度はマイナス６１人というふうに幾つか特徴があるわけですけど、その辺は、今、指摘したところの事例でもいいんですけども、学校ごとの分析というんでしょうか、教えていただきたいというのが一つ。制度が定着をしたという意味は、どういう意味なのか。とりあえず、２点、教えてください。","respondent":"久保田学務課長","answer":"もちろん、例えば、私どものプラン２１が目指しています特色ある学校づくりの中で、地域、それから保護者、学校が連携して学校づくりをやっていくのに当たって、どれだけそれが成果として出ているのかというのは。","id":"exchange-003"},{"speaker":"桜井委員","kind":"質問・要望","question":"この数字にはもっと奥深いものがあると思いますけど。だから、それは次回でもいいですから、教育委員会としてどう見るかという一定の考え方を、まとめていただきたいというのが一つ。しかし、いるけども、希望した２人ですからね。だから、そういう点からすれば、それなりの背景があるわけですから、だから、それに対してやっぱりどういうふうに指導的援助というのを、この１年間なりにされているのか。","respondent":"久保田学務課長","answer":"当然、平成１３年度、ご指摘も受けましたが、マイナスの大きいところにつきましては、それこそ１年がかりで、毎回、学校長を中心として、どういうふうにやったらこの学校の中で、より学校づくり、あるいは特色づくり図っていくかということで。","id":"exchange-004"},{"speaker":"桜井委員","kind":"質問・要望","question":"それっていうのは、どういう形で評価していくのか、どういう形でやっていくのかなんていうことは、全然、委員会の中で報告がないじゃないですか。教育委員会には、こういう報告はされているんですか。そこだけしていただきたいのと、それから改めて、ちょっと委員長にお願いしたいのは、外部評価制について、次回でもいいですから、きちっと説明をいただきたいということをお願いします。","respondent":"青木指導課長","answer":"ただ、内容につきましては、今、検討中であるということで、私どもも進めているところであります。","id":"exchange-005"},{"speaker":"桜井委員","kind":"質問・要望","question":"決まり次第というのでは、ちょっと困るんですよね。決まってから、来年度報告しますというのでは、やっぱり、これを見たお母さんから質問されたんですよ、きのう。この中には、教育委員会のほうのコメントはないんで、コメントが取られてないのかわからないんですけども、そういう点では、次回にでも、今の段階でもいいですから、ぜひ報告をいただきたいと思います。","respondent":"青木指導課長","answer":"この内容につきましては、私も、昨日、新聞社のほうに直接、抗議の電話をいたしました。こちらのほうから抗議をしたわけなんですけど、まだ検討中の内容です。ここに書かれているような具体的な内容については、まだ作業部会の中でも決定しているような内容ではございません。","id":"exchange-006"},{"speaker":"桜井委員","kind":"質問","question":"これで最後にします。じゃあ、指導課長は抗議したのかもしれませんけど、若月教育長は、「古い慣習がはびこり、なかなか変わろうとしない学校を変える試み。内部では気がつかない点を指摘してもらい、改革に結びつけたい」となっているんですよ。教育長は抗議しなかったんですか。","respondent":"若月教育長","answer":"だから、先ほどの課長の話じゃありませんけども、「したがって、今、それぞれの現場の先生方に作業部会をつくっていただいて、これからどういう評価のあり方がいいかを検討してもらっている最中ですよ」と、そう言ったんです。","id":"exchange-007"},{"speaker":"桜井委員","kind":"質問","question":"教育長のコメントも載っている。それで、抗議したんですか。","respondent":"若月教育長","answer":"そこら辺はあまり詮索しても仕方のないことですから、特にあれはしておりませんけども、そんないきさつがあるということでありまして、こういう形になったということは、ほんとうに他意のないことであるということで、ひとつご理解をいただきたいと思います。","id":"exchange-008"},{"speaker":"山路委員","kind":"質問","question":"最初のほうの数字なんですけど、今の住民基本台帳による予定数と、区域外から来る方とか、私立や国立に行く方とか、また、区域外に行く人とかいろいろ数が出ていますけど、受入れ学校として、一番多く受け入れる学校ってあるでしょ。要するに、生徒の数が一番多い学校、一番少ない学校は、平均的にはどのぐらいの生徒数を受け入れるのか。差し支えなかったら、学校名か、数か、できたら数で教えてください。","respondent":"久保田学務課長","answer":"来年度はまだわかりませんので、昨年の例でお話しします。一番多い学校は鈴ケ森中学校でございまして、〔「一番右を見てくれと言えばいい」と呼ぶ者あり〕１５９人です。","id":"exchange-009"},{"speaker":"山路委員","kind":"質問","question":"本年度の対象児を考えていましたので、昨年度じゃなかったんですけど、昨年度に沿って、ご説明していただいたんですが、大体、本年度も同じ傾向の入学者数だと考えていいんですか。","respondent":"久保田学務課長","answer":"登録数を見ていただけるとわかると思うんですけども、昨年より、今年は１７０人ほど少うあります。したがいまして、入学者数も、それに準じて、１５０人ぐらいは少なくなるんじゃないかとは思っております。","id":"exchange-010"},{"speaker":"山路委員","kind":"質問","question":"こういうマスコミとか、個々に情報漏れとか、いろいろな形であると思うんですけど、それによる動揺とか誤解で、数が大きく学校選択が変わってくる。それについては、教育長と指導課長が説明しましたので、今、アセスメント部会でやっている最中をすっぱ抜かれたというか、そういう形ですけど、それによる誤解とか、影響を心配するんですが、その辺については、どのようにお考えでしょうか。","respondent":"指田教育次長","answer":"いずれにしましても、今回の新聞報道は、今のところ、これには直接影響はないと考えています。","id":"exchange-011"},{"speaker":"山路委員","kind":"質問・要望","question":"せっかくそういう形で来ましたので、ちょっとしたことに動揺しちゃう、親が一番神経をとがらせている教育という問題に対しては、危機管理、情報管理ということを言われたましたけど、その辺は注意しながら、子どもたちの動揺がないように、すくすくと育っていくように、こういう問題が出てきますと、またいろいろな問題が出てくると思うんですけど、そういうことに右往左往しないように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"この住民基本台帳による予定数ですけども、たしか、小学校は増えているような話を聞いたんですけども、この先二、三年、推測的には、中学校の基本台帳の予定数というのはどうなっていくんですか。","respondent":"久保田学務課長","answer":"そこの辺は、毎年ちょこっと、平成１５、１６年でこのぐらいあって、その後は、やはり先ほどの中学校と同じように、やや回復してくるというような推測をしています。","id":"exchange-013"},{"speaker":"松澤委員","kind":"質問","question":"この数字は、特色ある学校づくりの中の評価に入れたいということで、ある程度、見ていかなくちゃいけないと思うんです。特に八潮地区ですけども、児童数そのものも、中学校を両方足してみて、３年生が２１５人から、２年生が１８０人、１年生が１４８人ですか、減ってますよね。この辺の分析はどうですか。八潮南中学校にゼロという可能性があると思うんですけど、その辺をどう見ているのか。","respondent":"久保田学務課長","answer":"現時点で、完全にさっ引きますと１５人ということなんで、ゼロにはならないんじゃないかとは思っています。これから、転出、転入等もありますので、そういう点も含めても、このぐらいでいくのかなというふうに思っております。","id":"exchange-014"},{"speaker":"松澤委員","kind":"質問","question":"昨年のを見ますと、基本台帳が６９人、そしてマイナス１で６８人中５１人なんですよ。今回、それが４６人でマイナス１５人ですから、課長、ほんとうにそんなことはないと言えるんですか。ゼロになったときに困るから、今のうちに、ゼロになったら、これはいいんだ、悪いんだという話をしてもらえますかね、どうなんだと。言えないですかね、言えなければいいんですけど。","respondent":"指田教育次長","answer":"プラン２１の教育改革によって、特色ある学校づくりと同時に、教職員の意識改革をしようという二とおりの意味があるわけですから、そういった意味において、教員たちが、なぜ自分たちの学校が選ばれなかったのかということは、教育委員会と一緒になって考えていくべき話だと。","id":"exchange-015"},{"speaker":"高星委員","kind":"質問・要望","question":"品川区の教育という意味合いでは、品川区以外のいろいろな先生から聞くと、評価されてきている。先生方が個人的に一生懸命頑張っているその成果が出ないうちに、次から次にまた変わっていく、新しい施策が入ってくるということになると、一生懸命頑張っている先生方をどうするんですかという意見があることも事実です。それと、在校生の３７名を足すとという計算はだめなの。そういうふうにならないんですか。","respondent":"久保田学務課長","answer":"本来なら６０人が入ってこられるんですけど、この中から私立に行かれる方や、引っ越しされて転出される方もいらっしゃいますので、最終的には３７人ということになったです。","id":"exchange-016"},{"speaker":"高星委員","kind":"質問","question":"じゃあ単純に、今年の住民基本台帳で、平塚中学校の９３人が、こうなってくると、予想として何人ぐらいなんですか。昨年のパーセンテージを掛けたらどうなっちゃうのかな。このパターンでいうと、下手したら２０人台になっちゃうんじゃないか。概算で２７人ぐらいになるんじゃないですか。","respondent":"久保田学務課長","answer":"先ほど、一番下のところにありますように、「国・私立入学者／指定校変更／転居者等があり、確定数ではありません」ということなんで、正直申し上げて、何人になるかというのは、現時点ではわからないわけです。","id":"exchange-017"},{"speaker":"高星委員","kind":"質問","question":"だから、そういう現実を見たときに、質問するんだけど、この数字を出して、じゃあどうするのと、具体的に金をかけるのかどうなのか。それが１クラス３０人、４０人ぐらいで、３学年でどうなっちゃうのかわからない。その辺のところをどう具体的に考えて、どうするつもりなのか、具体的に金をかけていくのかどうなのかということを、ちょっとお聞きしたい。まだ難しい話だとは思うんだけど。","respondent":"指田教育次長","answer":"それの政策、要求を受けて、我々とすると、ここのところを認めていこう、ここはこういうふうにしていこうという形で、これから予算要求をする予定でいます。","id":"exchange-018"},{"speaker":"高星委員","kind":"質問","question":"私も、プラン２１の選択制のことについては、本会議の代表質問を通じて、不退転の決意であるということは申し上げて、そこのところで、私はやめてしまえとか、そういう気持ちは全くないんです。そういう意味において、じゃあ、単純にお聞きしますけれども、危惧するところはそこなんだけど、平成１３年度、平塚中学校の場合、５３名がほかの学校に行かれて、３７名になったと。","respondent":"若月教育長","answer":"やがて来るべきそういう時期が必ずあるから、だから、今のできるうちから、とにかく一歩一歩、もう１回、努力を重ねていこうと、そういう意味で、今、学校は間違いなく、みんな積極的な気持ちで取り組んでいるという状況であります。","id":"exchange-019"},{"speaker":"川西委員","kind":"質問","question":"その他で出るのかどうかと思ったんですけど、この次の文教委員会とかおっしゃったから、４日の新聞記事に関連したことで、先ほど、報告がありましたが、私もあまりよく知らない立場で、４日にいろいろ、まちの方から質問をいただきまして、みじめな思いというか、恥ずかしい思いをしていたんです。","respondent":"青木指導課長","answer":"アセスメント部会ですが、区内の校長が４名、教頭が４名、それぞれ小学校、中学校２人ずつです。","id":"exchange-020"},{"speaker":"川西委員","kind":"質問","question":"もう一つ、私も自分の置かれている立場とか、いろいろほかにもありまして、評価ということに対しては、悪いとは思っていないんですよ。ですから、住民の方に、それなりの説明は、自分なりのことはした立場ですが、部会を持つということは、将来、こういう趣旨のものを考えていこうと思っていることは確かですね。","respondent":"青木指導課長","answer":"内部だけではなくて、内部と外部の評価から、学校が新たに改善の方策を打ち出していく、その資料にするための評価ということで、先ほど申し上げました作業部会として、学校アセスメント部会の中で、現在、区内の校長、教頭、小中学校合わせて８名の先生方に。","id":"exchange-021"},{"speaker":"桜井委員","kind":"質問・要望","question":"今の件で、プラン２１の検討委員会のそれぞれ途中の経過もいただいているし、どういう形でやるかということもいただいているわけでしょ。だから、そういういろいろな意見が皆さんの中にもあるし、すべてというといろいろあるかもしれませんけども、ある程度わかる範囲で、次回、ご報告いただきたいと思うんですけど、いかがでしょうか。それのお答えがなかったものですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-02","title":"続きまして、請願・陳情審査に移ります。 (1)の二〇〇二年度教育予算編成に関する陳情","agenda":"続きまして、請願・陳情審査に移ります。 (1)の二〇〇二年度教育予算編成に関する陳情","exchanges":[{"speaker":"山路委員","kind":"質問","question":"今、説明していただきましたが、１と２は検討されているようでありまして、３番の休憩室につきまして、お聞きしたいことは、私立中学校、小学校においてはどういうふうになっているのか、わかる範囲で教えてください。","respondent":"鷹倉庶務課長","answer":"いわゆる公務センターという形で、いろいろな部屋がオープン化される。我々の執務室と同じような感じですが、ああいうような形態をとっている場合については、隠れ場所的に休憩室を取られている形態のところもあるのかなと思われます。","id":"exchange-023"},{"speaker":"山路委員","kind":"意見","question":"大体参考になりましたけど、この気持ちは非常にわかるんです。それで、休憩室に先生がいるのは、そこを考えた場合に、どうとらえていいのかなということを、ちょっと迷うんです。全体としてとなると、子どもたちがどういうふうにとらえるのかなということが一つ、いいとか、悪いとかじゃありませんけど、ちょっとどうなのかなと悩んでいるところなんですけど、どういうふうに思われますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"川西委員","kind":"質問","question":"委員長、時間短縮のために、関連がありますから、いいですか。今の関連なんですけど、例えば、教員の服務規律とか、勤務規則とかで、例えば４０分なり、１時間休憩を取ると、その間の児童生徒の監督はだれがするとか、そういうのがどうなっているか伺えば、山路委員の質問と一緒に答えていただければと思います。","respondent":"青木指導課長","answer":"教員の休息、休憩の問題ですけども、このたび、４月からですけども、それぞれの学校で休憩、休息時間の割り振りということで、徹底しています。","id":"exchange-025"},{"speaker":"高星委員","kind":"意見","question":"要するに、休憩室があるから休憩していいとか、休憩室がないから、休憩して悪いとかじゃないのよ。ただ、僕は、全体の流れの中で、やっぱりゆとりのある教育というところにもやっぱり目を当てるべきだと、この中身はこういう趣旨にとらえているんです。大きな意味で、休憩室というよりも、休憩する場所という意味なんでしょ、僕はこういうふうに理解するんですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問","question":"先ほどちょっと、例えば主事室とか給食室に休憩室があるというお話がありましたけど、そこは使ってはいけないという規定か何かあるんですか。","respondent":"鷹倉庶務課長","answer":"これもご案内かと思いますけども、いわゆる主事室に行って、先生方がたばこをお吸いになったり、お茶をお飲みになっている現況があるのはご存じだと思います。使っちゃいけないとか、そういうことではございません。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"意見","question":"そういう点を考えた場合、学校の中で、新たに休憩室を設置するという必要性が出てくるのかどうか。それから、私みたいに民間にいた人間からしますと、仕事の時間中に休憩をするなんていうことは考えられないです。考えられないことだと思うんですね。そうすると、なぜここで休憩室を設置しろということが出てくるのか、私はちょっと疑問に思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"山路委員","kind":"質問","question":"質問していいかどうか、ちょっと迷っていたんですけど、お願いします。","respondent":"青木指導課長","answer":"それぞれの教員の適切な時間の中で、休憩、休息は対応しているんだということで、子どもの目には、そういうふに見えると考えています。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"暑さへの影響というのですか、養護の先生なんかのご意見もあるのかどうか、その辺を聞きたい。トイレは、順次改修ということなんで、期待しているんです。もう１点、クーラーについては、予算的な問題が研究されているのか、全校的にやるとどのぐらいかかるのか、部分的にやったら幾らぐらいかかるのか、その辺を研究されているのかどうか。よろしくお願いします。","respondent":"鷹倉庶務課長","answer":"みんながクーラーをつけるから、だんだん暑くなって、また自分に戻ってくるということです。区立の小中学校がみんなクーラーをつけたら、一体どういうふうになるのかなと、ちょっと心配もあります。この辺を当然含みながら、十分検討していきたいということがあります。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"要望に関しては、ＰＴＡの連合会、校長会からも、あったらありがたいということで、そこで、ぜひやっぱり子どもたちの声、私が聞いている範囲では、女の子はスカートの間から下敷きでぱたぱたあおぎながら勉強しているんだという声も聞いています。研究は、いろいろ多方面にわたって研究をしていただいて、現場の声にこたえていただきたいなと、私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"川西委員","kind":"質問","question":"すみません、私の質問はどうなりましたか。まだ答弁できてない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"川西委員","kind":"質問・要望","question":"お答えいただきたいのは、教員の勤務時間というのがありますよね。休憩時間は、服務規律や規則ではどうなっているのか。それから、労働基準法みたいなものがあるから、そういうのとの関連をちょっとはっきり聞いておきたい。休憩室の問題は別ですよ。","respondent":"青木指導課長、指田教育次長","answer":"４５分間の休憩時間を取るということでやっております。現実的に、私どものほうもそうですけども、食事に行ってしまえば、帰ってくるだけでもって休憩時間は終わってしまうのが実態だと思いますので、その中で、先生方は、その休憩時間はだれの拘束も受けずに。","id":"exchange-033"},{"speaker":"川西委員","kind":"意見","question":"そうしますと、内部規則とか、どういう名前の規則になっていますか。","respondent":"指田教育次長","answer":"これに基づいて、全部きちんと取るようにという形で、今年の４月に、その辺について全部やりとりして変えてきたという形になっています。もしあれでしたら、後ほど、その点については、ご参考にお持ちしたいと思ってあります。","id":"exchange-034"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、児童が帰ってしまって休憩時間を取っているときに、校長が何か頼んできたら、断ってもいいんですか。","respondent":"指田教育次長","answer":"休憩時間については、勤務命令を発することは、よほどのことがない限りできませんから、断ることは自由です。","id":"exchange-035"},{"speaker":"桜井委員","kind":"質問・要望","question":"ですから、そういう２３区、あるいは東京都の主なところの状況も調べたいし、トイレの問題も、中学校でやる場合、具体的にどの程度あるのか。品川区は出ないんですか。区のほうにも、他区の状況を教えていただきたいのと、トイレの改修の場合にはどのぐらいの費用がかかるのかと、どのぐらいの計画でやるのかという幾つかお願いしたいということで、できれば継続をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"山路委員","kind":"質問","question":"いろいろ先ほどから教えていただきまして、状況から見ると、陳情されている気持ちは非常にわかるんです。お子さん、ＰＴＡの関係の方の気持ちもわかりますけど、環境状況から考えると、全体としてちょっとまだ早いんじゃないかと、私はそう思うんですよ。そういうことになりますと、きょう、結論出していいんじゃないかというのが、私の意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"川西委員","kind":"意見","question":"１、２、３と、意見はいろいろ私もあるんですが、学校関係の改築問題を含めて、これからいろいろありますし、設備関係の問題で、ここだけ解決して、学校現場がどうなるかという問題もありますから、ちょっとこれは願意に沿いがたいような気がして、結論を出して結構です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"高星委員","kind":"意見","question":"基本的に、先ほどから言っているように、空き教室を休憩室にしろなんて、だれも考えているわけじゃなくて、原則的に休憩する場所が欲しいということなんだろうと理解するんです。１番、２番のほうも、これはだめだという中身じゃないと思うんで、総体的に言えば、私は趣旨を採択すべきだと、もし、きょう結論出すんだったら、そういうふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"桜井委員","kind":"質問・要望","question":"結論を出すに当たって、願意に沿いがたいというご意見もあるようですけど、それはその会派のご意見でしょうが、例えば２は、既に実施していて、またこれからもやっていくということってありますよね。だから私は、もしきょう結論を出すんなら、項目採択がいいんじゃないかと思っているんです。だから、これをもし一致するとしたら、そういう項目的な採択を、私はしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"松澤委員","kind":"質問・要望","question":"私たちは、組合から出されているこの問題は、３が主じゃないか、休憩室を設置するということがメインテーマではないかというような気がするんですよ。２の子どもたちが安心して喜んで使える、明るい清潔なトイレについては、トイレを改修するということは、共産党もよく質問しましたけども、今、やっているわけですよ。ですから、一括してやっていただきたいし、結論を出すならば、願意に沿いがたい、不採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"山路委員","kind":"意見","question":"私は気持ちはわかりますけど、学校施設の改修に関しましては、区のほうでしっかり計画、目標を立てられて、国との連携のもとに現場の意見を聞いて着実に進められているという判断のもとに、今言われた、ウォシュレット云々とか、この陳情書に対して賛成することはできない。着実に進められていると信じていますので、そこを言いたいわけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"川西委員","kind":"質問・要望","question":"トイレの問題も、今、着実に予算の範囲でやっている。そういう点では、高星委員の意見のように、ほんとうに場所をつくればいいだけの要望じゃないんだということは、さっき、規則や何か聞いたら、休憩したければできる条件というのはあるんだと、そういう中で、どうやって子どもと対面していくかということのほうが大事だというふうに、私は思いまして、さっきの結論を出しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"桜井委員","kind":"質問・要望","question":"まだ言ってないです。では、意見を申し上げます。１については、冷房化も、研究ということですので、それはぜひ研究していただきたいと思いますし、同時に、さっきのヒートアイランドについては、私はいただけませんね。ですから、そういう点では、これはぜひ、積極的に進めていっていただきたいと思います。１年でやれるとかという問題じゃないと、今、聞いたら１億５,０００万円でできる話でしょ。","respondent":"鷹倉庶務課長","answer":"１けた間違っていました。２５０万円×６００校で１５億円です。","id":"exchange-044"},{"speaker":"桜井委員","kind":"質問","question":"まあ、いいです。わかりました、１年でやるという話でもないと思いますので、それは十分可能だと思います。学校の施設は、いざというときには避難場所になるという点からすれば、すべて１００％やらなくても、一部分については、どんな対応もできる。休憩室の問題は、私も、今、第一義的かどうかということは、確かにあると思いますよ。ですから、趣旨の採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今、ちょっと声が出たんですけど、予算面の措置や負担は六行会の負担ですか。","respondent":"志村品川図書館長","answer":"そもそも、ここの建物の管理をやっています管理事務局というのがありますので、そこが工事主体になります。ただ、私ども、その中の入居者になってありますので、応分の負担をするということになります。","id":"exchange-046"},{"speaker":"桜井委員","kind":"意見","question":"私、ちょっとそれは異議ありだわ。というのは、もともとの図書館費というのは、いろいろ既に、冊数もそうだし、事務経費も含めてきちっとしているわけでしょ。どこかを削減ということになりますよね。だから私は、トータル的に幾ら予算がかかって、必要であれば予備費でやるか、あるいは補正で組むか。それを、通常の予算の中からやるというのは、ほかにしわ寄せしますから、私はそれは反対です。","respondent":"志村品川図書館長","answer":"大変申しわけございません、説明が粗くて申しわけないです。","id":"exchange-047"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この間、聞いていたんで、それで大体はわかったんですけど、こういうビルの点検というのは、中の借りている人間が払うものなんですか。というのは、区の庁舎をやったときに、例えば、中に富士銀行が入っていたり都税事務所、それと東京都建築事務所も入っていますね。あの辺からの負担金というのは、当然、区ももらっているという考え方になるわけですか。","respondent":"指田教育次長","answer":"ですから、今回の場合についても、そういうような典型的な緊急なものが出ましたので、管理組合でその話が出され、管理組合でこういう話があって、いこうという形になろうかと思っています。","id":"exchange-048"},{"speaker":"川西委員","kind":"質問","question":"ちょっと質問しておきたいんですが、点検はいいんですけれども、今度、工事が必要だということになりまして、今、区の規定で５,０００万円以上とか、３,０００万円から５,０００万円とかありますね。その範囲を超えた場合に、業者を選定するときは、こういう共同ビルの場合はどうするんですか。","respondent":"志村品川図書館長","answer":"一義的には、そこの管理組合が決めることなんですけども、当然のことながら、今ちょっと次長がお答えしたように、あの建物自体は品川区と六行会、いわゆる二者で共有していますので、当然のことながら、私どものほうのやり方というんですか。","id":"exchange-049"},{"speaker":"桜井委員","kind":"質問・要望","question":"３点ほどあります。品川区ではどうだろうかということで、私、生涯学習課に行って「品川の学習・スポーツ」というのをいただいたんです。今後、ちょっと委員長にお願いしたいのは、「品川の学習・スポーツ」、今回、生涯学習なんですが、全体の概況説明はいただきたいんですけども、個別的にテーマを設けて、品川区がどういうふうに生涯学習を推進していくのかというのを知りたいなというのは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"松澤委員","kind":"質問","question":"ただ、あれには子どもたちが入っている。我々は、２２km2という小さな品川区の中でも、施設がある品川区のほうが上かな。それともう１点は、どこへ行っても、プラン２１のことが話題になりましたけども、結局、向こうのほうが聞きたがるというようなことで、特に終わってから、次長に、「質問していいでしょうか」なんて方がいらっしゃるけど、あれは初めてのことだったんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"川西委員","kind":"意見","question":"最初に行ったときに、あいさつされた中で、やっぱり一つの時代の大きな流れの中で、今までの行政の運営というのは、固定観念にとらわれないんだと、言葉はちょっと違うかもしれないけど、おっしゃっていたことは、やはり非常に私、議会もそうですし、行政側も、ああいう勢いというのは感じるべきだなと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"山路委員","kind":"意見","question":"それと、函館のまなびっとは、子どもから幅広く、全体の教育力アップということを、これは非常に感じたけど、これもまたシステムの違いはあったんで、品川区でそのまま受け入れるかどうかということは別にしまして、非常に勉強になりました。ただ、品川区のほうを、むしろ地方の人が参考にしたいというのが強いのは感じてまいりましたけど、それについてはまとめていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"桜井委員","kind":"質問・要望","question":"委員長、今後の運営についていいでしょうか。いろいろ発言して申しわけないんですけど。今後の委員会の後半部分というか、私たちの調査事項のことなんですけども、これは要望なんで、正副委員長でご検討いただければと思いますけど、平成１３年度の事務事業評価が出ましたよね。教育委員会所管の部分を、ひとつお願いしたいと思います。ご検討いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"松澤委員","kind":"質問","question":"私もいいですか。きょうみたいに、請願・陳情審査の後に視察するという形は、時間的にどう転ぶかわからないという言い方はおかしいですけど、議論が白熱して延びたときに、まだここは歴史館ですからあれだったですけど、ちょっと遠いところとか、他区なんかに行く場合に大変に失礼なんで、なるべくそれは重ならないような形にできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/202784?Template=document&Id=4420#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":34205,"voices":133}},{"id":"h13-20011107-13","meetingId":"h13-cm11","date":"2001年11月7日","dateIso":"2001-11-07","committee":"清掃・リサイクル特別委員会","time":"午後１時0６分～午後２時４６分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"役割について今ご説明をいただいたわけですけれども、地域の町会の方で推進員に選ばれた方から、１月に委嘱の後、役割を持って自分は頑張るんだということで、いつ連絡が来るのかなといって待っていた方がいらっしゃいました。１１月１日に大井地区で開催されたということで、多分いろんなご意見が出たと思うので、出ていたご意見がありましたらまず聞かせていただきたいと思います。","respondent":"中山清掃リサイクル課長","answer":"その際に、改めてご説明申し上げたんですが、先ほど簡単にご説明しましたけれども、推進員の主な役割の１点目として、推進員みずからごみの排出抑制と分別の徹底を実践してくださいというのがあります。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一つ、決算特別委員会のときにも南委員から言っていただいたんですが、地域の方が地域のごみを見て回ったり、意見を言うときにぜひ腕章か名札か、役割が地域の人にわかるようにしてほしいという声が出ましたので、その辺をぜひ具体化していただきたい。平成１３年度の予算が２４８万４,０００円と載っていたんですけれども、この辺の予算はどういうふうに使われていくか教えていただきたいんですが。","respondent":"中山清掃リサイクル課長","answer":"平成１３年度予算の執行の部分ですけれども、主なものとしましては、先ほど今後施設見学会等を実施する予定ですということで、かつての清掃協力会においても実施しておりましたけれども、バス等での清掃およびリサイクル施設の見学を。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本当に区民の皆さんに身近なごみ問題なので、区民参加という意味ではとてもいい制度だと思うので、ぜひ皆さんの意見を大いに聞いていただいて、充実をしていただきたいとともに、この委員会にも内容を今後報告をお願いしたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"今の関連なんですけれども、今年の２月のときには６００人を考えているというお話でしたけれども、なぜそこに至って３８０人、半分ちょっとということですね。その辺で増やしていく努力というのか、その辺はどういうふうに考えていらっしゃるのかというのが１点。ですから、その辺はどういうふうにお考えになっているか伺いたいと思います。","respondent":"中山清掃リサイクル課長","answer":"したがって、ある種のシステムにしてやっていくというのは、なかなか３８０人の方というのもそれぞれですから難しい部分がありますけれども、まずは一人より二人、二人が三人という形で口コミでも伝えていただければ。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"そういうところで行きやすいような受け入れ体制をつくっていただくことも含めて、区のほうでいろいろな支援をしていただかないとなかなか進んでいかないし、せっかく配置して応募してというシステムを取られていくのも発展していかないという気がしますので、その辺はできるだけ、せっかく受けていただく大事な役割ですから、進みやすいようにして協力いただきたいということをお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"船波副委員長","kind":"質問","question":"保育園と学校のところでは、生ごみを集めたことによって可燃ごみがどう減ったかという数字が出ているわけですけれども、一般の住宅のほうでは１世帯当たりだと１カ月で７kg前後とか出ているわけだけれども、これが例えば品川区全体に広げたらどれぐらい可燃ごみが減るかというようなシミュレーションというか予測というか、そういったことは考えていないんでしょうか。","respondent":"中山清掃リサイクル課長","answer":"したがって、もともと全域に広げた場合には、こういった協力を一切できないと言われるような方のところのエリアも入れてしまうと、平均値というのが大きく動いてしまうということも考えられますので、あくまでも今回の数値というのは。","id":"exchange-006"},{"speaker":"船波副委員長","kind":"質問","question":"可燃ごみのデータに対して生ごみがどれぐらい減るかということについては、今の説明でわかりましたけれども、コストがどうなるのかということが説明ないわけですが、燃やす量が少なくなれば、燃やして処理するという部分でのコストは減るでしょうけれども、他方生ごみだけを処理するコストがかかるわけで、生ごみを燃やすのではなくて処理する場合、燃やすコストは減るけれども。","respondent":"中山清掃リサイクル課長","answer":"したがって、単純にこのまま何も手を加えずに広げてしまえば、可燃ごみよりも今段階では高いコストがかかってくるというのが、現段階での区の認識になっているところです。","id":"exchange-007"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"私も緊急補助対象事業になっているということを思ったので、この補助事業がなくなってきたときに区としてどう対応していくのか、この辺をお聞きしようと思ったんですけれども。","respondent":"中山清掃リサイクル課長、野本環境清掃事業部長","answer":"繰り返し申し上げているように、２カ年の事業を分析した上での判断ということになるんですけれども、率直に申し上げまして、やはり価格の問題、実際にこれを今後モデルを含めて展開した場合、当然コストの問題になるわけですから。今のご質問に若干補足をしますと、この事業を昨年やったときに、やはり委員会でほかの委員から「何でやるんだ」と、ご質問がございまして、そのときにお答えしたのは。","id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"数年すると、もう本当に大きなオゾンホールが、さらに大きくなっちゃって大変なことになると言われていますね。ですから、議定書の問題でも、早く日本が批准をしてというふうなところで、そういう動きが世界中の世論にもなってきているわけで、その点から本当にいろんな可能性を探っていくという、そういうスタンスでやっていただけているのかなと期待していたんですが、そういう点でどうなんでしょうか。","respondent":"野本環境清掃事業部長","answer":"やはり、行政がこれはこうあれはこうと、こういうふうにやっていったときに、どうしてもデスクなり概念的なもので組み立てますから、なおかつつくって不整合が出た場合に、みずからそれをきちっとオープンにして、もう１回「ごめんなさい。","id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"そのことはもう小さな自治体云々のレベルではなく、やっぱり小さな自治体から集合して、一つひとつがきちんとやっていくことが大事なことだと思うわけですから、国の補助金が外れてしまってもきちんと条件が整備され、いきとどいた状況がつくり上げられるまでの間だけでも、少なくとも自治体が率先してやっていくという姿勢は、生ごみ分野でも欠かさないで持つべきだと思うんです。","respondent":"中山清掃リサイクル課長","answer":"しかしながら、これをどう生かせるかについては、じっくり検討していきながら、学校も一つですけれども、何らかの形でモデル事業というものは生かしていきたいし、その中で、部長もご答弁申し上げましたデータを知らしめていくということで。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"ただ、堆肥になったときに、どうやってそれをリサイクルとして完結させるかというのが、一つの大きなネックになっているのは承知した上での発言をしているつもりなんですけれども、その辺も含めて検討をしていただいて、せっかくここまで一部の地域ではあっても、生ごみの分別収集と堆肥化の問題が、品川区の大きな事業としてスタートして発展して認識も広がってきているときだけに、補助金の問題。","respondent":"中山清掃リサイクル課長","answer":"端的にこの事業の継続ということになるかは別にしまして、今回のモデル事業を何らかの形で区政の中、あるいは対外的にオープンにしていくという流れの中での検討、およびそういった意味での活用について考えていきたいと考えています。","id":"exchange-011"},{"speaker":"土井委員","kind":"質問・要望","question":"それは要するに、これから先ほどのように理念的にそうすべきだ、だけれどもそれにはお金がかかる、したがってこれもお伝えいただけるんですねという確認をしていくためにも絶対に必要なことですから、これはぜひデータを集積して、コスト面のデータもしっかりと出していただきたい。そうじゃない方法のためにも、このデータを使っていただきたいというお話だったら、それは面白いと逆に思いました。","respondent":"中山清掃リサイクル課長","answer":"例えば、飼料でも全国的には、これはまた有機化してというプラントをつくっているところもありますが、現実に東京２３区、品川区の中で同じようなシステムを単純に取り入れられるかというと、それは難しいといったものもありますので、品川区の風土。","id":"exchange-012"},{"speaker":"須藤委員","kind":"質問","question":"先ほどモデルになったところは各世帯あるんだけれども、手を挙げてもらったというようなお話で、こういった状況をよく考えているご家庭の方だろうと思うんですけれども、この中に先ほど言ったごみ減量化推進員という方々はどのぐらい入っていらっしゃるんですか。","respondent":"中山清掃リサイクル課長","answer":"申し訳ございません。全委員の名簿と照らし合わせれば即答できるところですが、荏原地区内で１３１人ですから、何人かはいらっしゃるかと思いますが、詳しい人数は名簿と照らし合わせて、後ほどご提出したいと思います。","id":"exchange-013"},{"speaker":"須藤委員","kind":"質問","question":"ですから、これはモデルだから、あくまでもモデルとして見ているけれども、これは最大の状況で考えてきての結果がここだよというので、「一部混入していたものの概ね良好である」という表現をここに書いてあるけれども、その後は有機肥料の原料となるといっても、あれは分けてとなればそれはいい結果になるけれども、「概ね良好」というような表現では、私があそこの現場を見たときには。","respondent":"中山清掃リサイクル課長","answer":"それと、今回ちょっと推進員の数は明確ではございませんでしたけれども、この３地区を選ぶ際にも、実は管内の荏原清掃事務所と連携を取る中で、先ほど東京ルールＩという言葉が出ておりましたが、資源回収事業を２３区に先駆けて品川区で実施する前に、モデル地区を選定した中で。","id":"exchange-014"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから、絵の描き方というのは幾つかできてこようと思うので、今後の検討材料として僕らも勉強させていただきたいのと、先ほど言ったアンケートの結果を今待っているというので、そういうところもまたどういうお考えがあったか、後で聞かせていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"須藤委員","kind":"意見","question":"３００部という数字は、今言ったようにどういう形で出てきたのかな、配布先等を考慮してきているのか、単に見学者が来ているのが３００部なのか、予算的に３００部しかできなかったというのか。","respondent":"中山清掃リサイクル課長","answer":"予算の中で大体従来から３００部という形で設定しているわけですけれども、今申し上げた関係区への配布等、それから実際に要望がある従来の数ということを踏まえて、それから清掃事業の一環ということで、若干関心が高まるだろうということで。","id":"exchange-016"},{"speaker":"須藤委員","kind":"意見","question":"し尿処理で品川区は７５世帯があるということなんだけれども、非常に多いかなというふうな感じがしたので、これもどうしようもない場所なのか、配置的にチェンジしていく方法ができないか。","respondent":"中山清掃リサイクル課長、金井環境課長","answer":"毎年調査するたびに１０世帯、２０世帯の割合で減ってきておりますから、いずれはなくなっていこうと思いますが、地理の形状と敷地の権限の関係で、どうしても下水道との直結がすぐにはできない世帯がいるということで。ただ、今のお話にございましたように、いろんな推進員ですとか、そういった情報提供にインターネットを皆さん全部わかるかといったら、なかなか難しい面がありますので、相当これは厚いものですから。","id":"exchange-017"},{"speaker":"須藤委員","kind":"意見","question":"結局、まちの人にいろいろお願いしてきているときに、やはり勉強しようと思っている方々がいらっしゃるときに、この前見たときに結構年配の方が多かったので、インターネットに直接取り組むようなメンバーばかりならいいんですけれども、そうでない方々もいらっしゃるので、これを全部というと勉強も大変だろうから、平易に解釈できるようにしてご協力いただいてもらえれば、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、そういう機会がありましたら、ぜひそのことも伝えていただきたいというふうに思っています。見解のところにちょっとわからないから教えていただきたいんですけれども、「東京都建設発生土再利用センター等を活用し」という、ここのところはどういうことなのか、ちょっとよくわからないので、システムも含めて教えていただきたい。","respondent":"金井環境課長","answer":"したがいまして、そういった内容も含めながらこれは書かれていると思いますので、その受け皿といいますか、そういったことを含めた発生土の再利用センターというところで、いろいろ指導も含めた内容をやっていると思うんですが。","id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"私がお願いしたかったのは、「工場だより」を見せてくださいと言ったときには見せてもらえるんだけれども、日常的に地域センターだよりの中に、工場だよりで出てきた情報については紹介していただけないかという、そういうことを含んでの質問だったんですが、それについてはどうなのかということを伺いたいと思います。特に、月末だとか月初めとか連休等のときには。","respondent":"金井環境課長","answer":"先ほどの区民委員会でもご説明しておりますが、全体的な環境汚染のことと一緒になって出てきていますので、それで不安がどうしても出ちゃうということは、それはご心配のとおりかもしれませんけれども、それは東京都がご案内のとおり大気汚染に関しては、特に自動車、ＮＯｘ。","id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"丁寧に教えていただきまして、ありがとうあります。ですから、そういう車の規制を厳しくしたりとか、そういうことでこれからさらに５年後、１０年後に一層これを右肩下がりになっていくということで、改めてきれいになっていると実感するんだろうと思うんですけれども、そういうことも含めて、もっと加速できるようにしていきたいというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"土井委員","kind":"意見","question":"この表現がもともとの問題があるところがあるんだろうと思うんですけれども、いろいろ私もあちこちの清掃工場等を見させていただいて、最新鋭の工場ですと、吸い込みの空気よりも出てくるガスのほうがいろんな値が低いんだと。だから、この工場によって大気汚染が深まるということはないんだということを、逆によくなるほうになるんだということをちゃんと説明したほうがいいと思いますよ、意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"環境負荷の低減に関しての事業者意見の５番目なんですが、私の考えが違ったら質問にならなくなっちゃうんですけれども、この事業者意見というのは清掃一部事務組合のほうでつくっているわけですね。この清掃車両は今で言うと品川区が担当する部分じゃないかと思うんですけれども、この文章はどうなっているのかなという質問なんですが。","respondent":"中山清掃リサイクル課長","answer":"それが、いかにも民間のことも含めて進めていくように言えるというのは、区の事業はもとより、確かに清掃工場が主語だとすれば、清掃車両の運営は権限がないですから、不正確な表現ということが言えるかと思いますけれども、要は低公害車になっていくということを。","id":"exchange-023"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"低公害車ということで、前もちょっと質問をさせていただいて、お聞きしている範囲でガスの充てん除去の問題も大井清掃工場は出ていましたが、これの実現性みたいなものは充てん除去の早期実施、清掃作業の方に聞いていると、やはりガスの充てん場がないので不便だというお話を聞いています。その辺のところで、お答えをいただければ。","respondent":"中山清掃リサイクル課長","answer":"あるいは、都市計画施設の問題、アセスメントの問題を考えますと、現清掃工場の施設以外の部分も含めて、具体的に言いますと現在職員住宅がある部分、あるいはストックヤードの未利用地の部分。","id":"exchange-024"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"逆に、清掃一部事務組合で管理しているうちに、品川区が借地として借り取るような形を考えるのも一つの方法じゃないかと思うんですが、この辺はどうですか。やはり、形状でやりようがないというのでしたら、やむを得ない部分ですが。","respondent":"中山清掃リサイクル課長","answer":"権限というよりは、明確な方針があってということであれば、権限上の問題ということではないんですけれども、今申し上げたような更新期間中に全面的に敷地を平成１８年３月まで工事を行い、工事車両を入れ、なおかつ実際にはかなり建屋自体が広がるという中で考えますと。","id":"exchange-025"},{"speaker":"南委員","kind":"質問","question":"今の委員長がおっしゃったことは、次回の委員会の運営を議長にご出席をいただいて、清掃一部事務組合等の所管する問題について、委員会の中で理事者への質問も含めて質疑をするという、そういう運営をしていきたいということですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/520175?Template=document&Id=5650#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":31294,"voices":69}},{"id":"h13-20011107-16","meetingId":"h13-cm11","date":"2001年11月7日","dateIso":"2001-11-07","committee":"街づくり特別委員会","time":"午後１時０４分～午後４時４０分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"上山委員","kind":"質問・要望","question":"こういう地区計画の上で、ほかに何かこういうものがあるとか、あるいは、手法というんでしょうか、わかれば教えていただきたいと、最初にちょっとお願いしたいんですが。","respondent":"浜脇住環境整備課長","answer":"斜線があると、いくら容積が使えても、また、上のほうで細くなっちゃいますから、それを何とか、統一感がある景観に届いた３階建て程度のものがこのまちにはふさわしいのではないかということで、街並み誘導型地区計画を使うと判断をし、さまざまな地区計画をご提案したんですが。","id":"exchange-001"},{"speaker":"上山委員","kind":"確認","question":"ちょっと確認だけしたいんで恐縮なんですけども、今、住んでいらっしゃる方が建て替えるだとか、今、ご説明があったように、事実上、今の時点では１６０％しか使えないのを、２００％使えるということになると、それはそれで非常に、住民に関してはよかったと思うんですが、今の説明で、住民の側からすると、こういう計画が一番いいんじゃないかという話だったと思うんですけれども。","respondent":"浜脇住環境整備課長","answer":"このご提案といいますか、私どもが地区計画が何種類かあるうちのこれを選んで、地元から見た得策というふうに判断された部分というのは、やっぱり多いと思います。","id":"exchange-002"},{"speaker":"石田委員","kind":"質問","question":"そういう場合も加味していって、これからいろいろ８.１haというところに進んでいく上において、今、品川区が５０m2という指導をしているんであれば、そこをあえて地区計画をかけたために、この前例でいってしまえば、８.１haという広いところにこういう形のものが残っていくとするならば、そこはやっぱり品川区が指導している５０m2というものの根拠が一番明解だと思うけれども。","respondent":"浜脇住環境整備課長","answer":"開発指導要綱のほうでは、５０m2ということで、品川区全域にそういう考え方で指導していますが、今回、私どもとすれば、地元といいますか、地元をどういうふうに、安全で快適にするかとなったときに、やはり一定の規制と緩和というのがあるわけです。","id":"exchange-003"},{"speaker":"石田委員","kind":"質問","question":"今のお答えで、確かにおっしゃるとおりだと思うけれども、６０m2をどうしようとか、皆さんにご説明をして異論がないとか、それは当たり前のことで、現実、それがどういう形になるかということはわかっていないんですよね。例えば、今、ほかのところも平均的に６０m2だという前例を引っ張ってこられたけれども、だから進んでないんじゃないですか。","respondent":"山室住宅指導担当部長","answer":"今後、ご案内のとおり、都市計画の手続を踏んでまいりますので、そこでまたいろいろなご意見が地元のほうからも出るかもしれませんが、我々としては、地元の意向を踏まえて、現時点で、６０m2をご提案をさせていただているということをご理解いただければと思います。","id":"exchange-004"},{"speaker":"本田委員","kind":"確認","question":"地区計画の網は８.１ha全部にかかるわけですか。密集住宅に住んでいる方々の緩やかな努力といいますか、合意といいますか、そういうことを待ちながら、年月をかけて努力をしてきたという背景がありますので、３回の意見交換会をやったという報告が、今ありましたけど、その辺の住民の皆さんの合意というものは、法律上、どういうふうに生かさせるというのか、かかってくるのか、確認したいと思います。","respondent":"浜脇住環境整備課長","answer":"ところが、方針だけですから、これによって何かを規制するということではなかったり、緩和されるということではございませんが、地域といたしましては、８.１haに地区計画がかかっているとご判断いただきたいと思います。","id":"exchange-005"},{"speaker":"本田委員","kind":"質問","question":"私のほうでちょっと懸念していたのは、見切り発車にならないようにという思いがあって、お話ししているんです。規制緩和について、今、ご意見がございましたけれども、わりと緩やかな内容ですよね。くれぐれも、見切り発車になってはならないなと思うんですが、その辺のとらえ方はどうなんですか。","respondent":"浜脇住環境整備課長","answer":"私どもとすれば、これは地元から出たものですから、ぜひ、区としては成功させたいといいますか、成立させたいと思って、今後やってまいります。","id":"exchange-006"},{"speaker":"藤田委員","kind":"質問","question":"最初にお聞きしたいのは、私たちもあそこの現場を見てまいりましたね。あのときに、かなり細い通路のような道路があったんですけれども、それについては、あれは全部２項道路に指定をされているのかどうか。それをまず、ちょっとお聞きしたいと思います。","respondent":"浜脇住環境整備課長","answer":"一部区道と、一部私道ですけども、２項道路です。","id":"exchange-007"},{"speaker":"藤田委員","kind":"質問","question":"限られた土地ですから、有効に建てたいというのは、だれしもの思いですから。まだ０.５ｍ下げるなんていうと、道路はいいんですよ、まだ実感としての話じゃありませんけども、まだ出てきていませんけど、裏の家とのトラブルというのは、かなりこの地域で、これから逆に多くなるんじゃないかと心配するんですけども、その辺をどう受けとめられているのか。","respondent":"浜脇住環境整備課長","answer":"幾つという数字は、現在、出ておりません。ただ、そういうことがあるという問題点は、今、考えておりまして、これは間もなく整理してまいりたいと思っています。","id":"exchange-008"},{"speaker":"藤田委員","kind":"意見","question":"本来、説明会のときに、それをやっぱり言わなきゃだめですよ。それを言わないで、後から、そういうふうに言われたって、変な話、区がだまし討ちしたんじゃないかと思われる可能性はありますよ。本来、そこまで言って、隣地とこれだけ離しなさいとか、そういうことをちゃんと説明しないから、後からトラブルが起きるんですよね。例えば空調の室外機をもし置かれたら、どうしますか。","respondent":"浜脇住環境整備課長","answer":"委員、ご承知のとおり、工作物についてはこれでやっているんですが、今の室外機については、工作物とみなせませんので、その辺も、今の間隔と同じように、室外機はどういうふうに見るかというのは、やはり認定といいますか、内規の中で定める必要があると考えています。","id":"exchange-009"},{"speaker":"藤田委員","kind":"意見","question":"そういうことなんですよ、大事なのはやっぱり。きちっと道路に固定したものはだめとか、はっきり打ち出さないと、門とか塀だけがだめなんじゃないかと、もう設計の段階で、どんどん０.５ｍの中に出てきちゃいますよ、これは。必ず出てくると思うんです。きょうは、そのぐらいにしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"三上委員","kind":"質問・要望","question":"幾つかちょっと教えていただきたいと思うんですけど、一つは、まちづくり懇談会に入っているメンバーというのは、どれぐらいの方たちがいて、検討されてきたのか。少なくとも１.２haの１４０世帯のうちで懇談会をつくったわけじゃないでしょうから、８.１haという広い中にあっての懇談会のメンバーということで、これは自由参加的な部分があるでしょうけども、どのぐらいの人たちがここにいたのか。","respondent":"浜脇住環境整備課長","answer":"４番目に駐車場の件がございましたけども、やはり、今、お話がありましたように、車をとめて、一部区道や私道に出ているということがありますが、これについても、幾つまで出てもいいか、そういったこともやっぱり、これまでも課題になっておりまして、それを今ここで。","id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/930789?Template=document&Id=6218#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":16504,"voices":30}},{"id":"h13-20011108-14","meetingId":"h13-cm11","date":"2001年11月8日","dateIso":"2001-11-08","committee":"行財政改革特別委員会","time":"午後 １時１５分～午後４時２９分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/533450?Template=document&Id=5694#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":312,"voices":2}},{"id":"h13-20011126-6","meetingId":"h13-cm11","date":"2001年11月26日","dateIso":"2001-11-26","committee":"区民委員会","time":"午前１０時０５分～午後１２時５０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"原委員","kind":"意見","question":"毎年というか、こういう請願が出されて、意見書が出されるわけですが、もちろん出されない年もありましたけれども、内容的もほとんど同じような形で出されている内容ですし、てにをはの部分は後にしまして、基本的にこれでよろしいんじゃないかというふうに思っておりますので、それにご同意いただければと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問・要望","question":"ちょっとお聞きをしたいことがあるのですけれども、一般質問でハローワークの問題をうちの桜井議員がお聞きをしたのですけれども、ハローワークのほうは私も一緒にハローワークに参りまして、いろいろお話を聞いたのですけれども、そのときにかなり所長さん以下、積極的に区と連携をとってこの対策を進めたいのだという話をされておりましたのですけれども、区長のご答弁ですと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"課長のほうで、常設的なものとして考えているのだと、質問の中でとられたんだということなんですけれども、別に質問の中では限定した話でしているわけではないと思うんです。要は今の雇用対策としてお聞きをしているというふうに考えているんです。ですから、今、課長が言われた内容で十分かと思われます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/693840?Template=document&Id=2312#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":5674,"voices":32}},{"id":"h13-20011126-7","meetingId":"h13-cm11","date":"2001年11月26日","dateIso":"2001-11-26","committee":"厚生委員会","time":"午前１０時１０分～午後４時５６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を85件抜き出しています。","topics":[{"id":"topic-01","title":"平成１３年請願第１２号、新たな大気汚染公害被害者の救済を求める意見書に関する請願","agenda":"平成１３年請願第１２号、新たな大気汚染公害被害者の救済を求める意見書に関する請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここの中で出されている、東京都のほうで環境確保条例というのが制定されたということですが、この中身を具体的に教えていただきたいのと、そこの後に続いて、ロードプライシングというのが書かれているんですけれども、これがどういうことなのかを教えてください。","respondent":"田中健康課長","answer":"水泳教室等でも、今、気管支喘息等の治療法も大分進んできておるというふうに私どもは聞いておりまして、品川区に関しては割によくなっているケースもあるようです。環境とロードプライシングは、今確認しておりますのて、ちょっとお待ちください。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"難治化のところはあれですけれども、その後で、補償から外れた方の自己負担とか、生活補償が受けられないというところでの大変な実態というふうなところはつかまれているところがあったらお聞かせいただきたいと先ほどお願いしたいんですが、よろしくお願いします。","respondent":"田中健康課長、青山品川区保健センター所長","answer":"１８歳未満といいますか、１８歳で打ち切られてしまいますので、都条例に関するものについては、いろいろな実態があろうかと思いますが、具体的には私ども今その辺の部分についてはつかんでおりません。先ほどの児童の気管支喘息の難治化と、成人の気管支喘息の重症発作による突然死の増加という点ですが、先ほど健康課長もご説明申し上げましたように、現在、医療の面が非常に進んできておりまして。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そしてまた、区長会で出されているというふうなところもありますし、また、ここのところで書かれている、大気汚染の原因者の責任を明確にした上で、原因者責任と適正な負担のあり方や、救済すべき対象の範囲と認定の方法など、制度全般にわたる総合的な見直しを検討してまいりますという答弁をされたということと、そして。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"確認","question":"請願を読ませていただきまして、品川区の理事者に聞くのもちょっと酷な話かもしれませんけれども、ここに大きく出た「新たな大気汚染公害被害者」という判断というんですか、請願の中で言いますと、多分１９８８年以降の方をそういうふうに言っているんでしょうけれども、それが一体どういうふうな基準で、どういうふうにされていくのか。それが、だれが、どこで、どういう基準で認定するのか。","respondent":"田中健康課長","answer":"それで、近年の都市型複合大気汚染の現状という部分が、今回の二酸化窒素、あるいは浮遊粒子状物質、この辺をもう一度きちんと押さえて、大気汚染の被害者の救済をという考え方が必要になったのではなかろうかという提起かというふうに認識しています。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問","question":"もちろんそれが主因であることは間違いないんでしょうけれども、もっと別な、総合的な対策をしていくべきではないかということ。それは基準がないから。むしろそのことについてそれぞれ都議会に各会派がいるわけですから、都議会議員の紹介を通じて、さまざまな対応をしていくとか、区議会でなくて、都議会レベルの話として対応していくべきだと考えています。それは意見として述べておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"須藤委員","kind":"質問・要望","question":"先ほど課長のほうで、区長会で国あるいは都に要望を出しているというお話をされたんですけれども、その内容がどういうふうな趣旨か、ちょっと見たいなと思うので、後で結構ですけれども、資料を出していただきたいと思います。","respondent":"田中健康課長","answer":"もう一つ、品川区の大気汚染の状況ですけれども、八潮測定局といいまして、指定のところでの状況をちょっとお話ししますと、平成２年のデータがございまして、これにつきましては、0.０２……。","id":"exchange-006"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから、我々も調査していくためには、そういった資料を、数字的にもしっかりしたものをいただきたいと思うので、お願いします。委員長、資料要求をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"須藤委員","kind":"質問・要望","question":"資料的には品川区の状況と、東京都がやっている、そういった広域的なもので見させていただきたいと思いますので、それを含めてお願いします。","respondent":"新美保健高齢事業部長","answer":"ただいま須藤委員のほうからご要望のありました大気汚染の状況と、経緯も含めまして、資料をきちんと調製した上で、後日出するということでよろしいでしょうか。","id":"exchange-008"},{"speaker":"鶴副委員長","kind":"意見","question":"現在の公害健康被害補償法に基づく給付の財源はどういうふうになっているのか、ちょっとご説明していただけますか。","respondent":"田中健康課長","answer":"そこでもって協会あるいは自治体に対して、協会が実施する調査、研究等々、それから、大きなのは自治体の事業に助成をしているという実態です。予防協会のほうからは、認定患者のほうに補償給付の支給等々を行っておるものです。","id":"exchange-009"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"これまでの過程の中で、そのことについてはどういう論議をなされてきたんでしょうか。要するに業者だけにその責めを求めることになると、そういうところの問題も惹起してくるじゃありませんか。全くそこだけでいいのか。ほかの責任は何もないのですかということになる。これ以外の発生原因についての論議というのはどういうふうになされてきたんでしょうか。参考のためにお伺いしておきたいと思います。","respondent":"青山品川区保健センター所長","answer":"そういった点で、なかなか原因者を必ずしも一元化できない部分もあり、東京都がどこにどれだけの負荷がかかっているのか、それを慎重に検討した上で、施策展開をと言っている理由もそのあたりにあろうかと考えています。","id":"exchange-010"},{"speaker":"鶴副委員長","kind":"質問","question":"慎重審議がどうしても必要になってくるという要素はあると思います。そういう意味で、私たちは１回きりの審査で結論を出すというようなことでなくて、慎重な審議を重ねていくことがとても大事じゃないかなというふうに私は思うんです。だから、私たちはこの問題についてはとても微妙な問題を含んでいるので、もう少しあらゆる角度から審査すべきでないかというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"船波委員","kind":"質問","question":"１８歳未満であれば、東京都の条例によってカバーされて、補助が提供されるという制度があるわけですから、１８歳未満の新たな認定患者というのがいるわけです。ですから、そういったケースで新たな方が認定される場合、どういったルールで認定されているのか、お伺いしたいと思います。","respondent":"田中健康課長","answer":"都条例に基づきます大気汚染の健康障害に関する医療費助成の認定患者、いわゆる１８歳未満の方ですが、こちらにつきましては、私どもがお願いしております認定審査会を通じまして、病気の特定、級の特定等がありまして、医療費の助成がされるという内容になってあります。","id":"exchange-012"},{"speaker":"船波委員","kind":"質問","question":"その場合、その方の病状を見て、それによって認定審査会の方が、これは公害による症状であるというふうに判断されるんでしょうか。","respondent":"田中健康課長","answer":"おっしゃるとおり、その方がかかっている医者からの審査情報とか、レントゲン等が全部まいりまして、それを私どもがお願いしております医師会関連、あるいは品川区内の病院関連の先生方に見ていただいて、それで認定がされるという内容です。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところではディーゼル車というのが都内でどの程度走っていて、どういう状況になっているのかというのが分かったら教えていただきたい。","respondent":"田中健康課長","answer":"これが東京の空気を汚す最大の要因という表現を東京都広報でしておりまして、この辺がひとつディーゼル車に対する現在のいろいろな制限等をしようという考え方になっていることかと思います。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう中で、先ほどのディーゼル車の排気ガス規制条例というのが可決をされて、具体的にそこのところを規制していこうというところになっているわけですから、そういうところでは最大の責任があるというところは明らかなんじゃないかなというふうに、今の答弁の中でも明らかにされたのではないかなと思います。ぜひご検討いただきたいと思うんですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"高木委員","kind":"質問・要望","question":"これは今いろいろ議論があったところから伺うまでもなく、原因が車、燃料、あるいはそれを利用する人、乗る人、ここらあたりをどのように判断した判決になっておるのか。申し訳ありませんが、ここらあたりの新聞記事でも結構ですから、ちょっとお調べ願えたらありがたいと考えています。もちろん読んでもなかなかわからないんですが、そこらあたりの側面を勉強させていただきたい。","respondent":"田中健康課長","answer":"訴訟の関係ということで、新聞記事等でもということで、私どもも探してみまして、ご提供をさせていただきたいと思います。ただ、私どもが持っておりますメモでお答えして恐縮ですが……。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今日結論を出すということではなくて、審議して、明日結論を出していただきたいという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-02","title":"平成１３年請願第１３号、政府の医療制度改革に対する意見書の提出を求める請願","agenda":"平成１３年請願第１３号、政府の医療制度改革に対する意見書の提出を求める請願","exchanges":[{"speaker":"船波委員","kind":"質問","question":"参考までにお伺いしたいんですが、ここにあるように、例えば年金生活が月５万円以下ということである場合には、保険料というのは幾らになるんでしょうか。","respondent":"野田口高齢事業課長","answer":"この場合、月５万円ですと非課税になりますので、税がかかりませんので、簡単に考えれば、定額部分、定額部分も詳しくはあれなんですけれども、減免措置等があると思いますので、実質的に保険料がという話にはならないかというふうに思います。","id":"exchange-018"},{"speaker":"船波委員","kind":"質問","question":"定額部分というのは、基本的にはお幾らなんですか。","respondent":"野田口高齢事業課長","answer":"均等割という部分が年額２万7,３００円ということになります。細部はわかりませんので、それはご容赦ください。医療費の給付分につきましては、住民税の年税額掛ける１００分の１９４プラス均等割２万7,３００円掛ける加入者数と。今のは国保料の算定です。","id":"exchange-019"},{"speaker":"船波委員","kind":"質問","question":"よくわからなかったんですが、基本的に保険料については、年金生活であろうが、収入が幾らであろうが、大体において住民税の1.９倍であると。けれども、例えば年金のみで、５万円であるという場合であれば、住民税がないので、定額部分だけであると。それが１年間に２万7,３００円ということではないんでしょうか。そういった制度があるのであれば、お伺いしたいと思います。","respondent":"野田口高齢事業課長","answer":"低所得者に対する配慮ということで、老齢福祉年金受給者も対象とした制度ですけれども、それと同等程度の方については老齢福祉年金受給者と同じように１万5,０００円にということで、むしろ低所得者についてはそういった配慮が加わるということになります。","id":"exchange-020"},{"speaker":"船波委員","kind":"質問","question":"今ご説明があったのは、万が一病気になって医療を受けた場合の負担に関する説明ですよね。病気になっていなくても、保険に入っているというだけで払う保険料については、先ほどお話のありました、１年間２万7,３００円以上は減免というのはないんでしょうか。","respondent":"野田口高齢事業課長","answer":"それと、先ほど申しましたように、保険料については基本的な考え方についての部分はそうなっているということで、今示されている部分での試案の中で読み取れる範囲でお答えしておりますので、細部まで詰め切ってこの試案が出ているわけでございません。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"この提案が、報道によりますと、来年１月に具体的に提案されて、来年１０月から実施をしたいという方向だと報道されておりますけれども、来年１０月の実施時点で品川区の７０歳から７４歳までの方が何人いるのか、また、７５歳以上の方が何人になるのか、ひとつお聞きしたいと思います。そして、その４年前は1,０２０円だったわけです。そういうところで区長は、厚生労働省のこの案は問題があると。","respondent":"野田口高齢事業課長","answer":"外来の上限額ですけれども、先ほど入院の説明をいたしましたけれども、従前は外来は診療所の場合は3,０００円、大病院の場合には5,０００円ですけれども、制度が改正されますと、外来、入院とも統一して、先ほど説明したとおりになるです。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほど課長のほうから、国民健康保険財政は影響ないということで言われたんですけれども、影響ないという根拠が何なのか教えていただきたいんですが、７０歳から７４歳までの方は、ほとんどの方が高齢者の医療の中から国民健康保険のほうに移ってくると思うんですけれども、にもかかわらず、国民健康保険が影響ないという根拠はどういうことなのか、聞かせてください。","respondent":"野田口高齢事業課長","answer":"先ほど答弁したのは、そういったことを聞きましたということで、私どもは所管でございませんので、その範囲でしかわかりません。詳しくは担当課長でないと、そこまでは調べてございません。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"７０歳から７４歳の方は多分国民健康保険の財政の中から医療費が支出されるというふうなことになると思うんです。その方が、今言われた人数だけでも、平成１３年２月現在で１万4,５１２人ですか、この方はほとんどの方が国民健康保険からの給付ということになるんじゃないかと思うんですけれども、そこのところについては改めて調べてお聞かせいただきたいと思うんですが、いかがでしょうか。","respondent":"野田口高齢事業課長、新美保健高齢事業部長","answer":"聞いて、ご報告することはやぶさかではございませんけれども、それをさらに深く説明するというのは、そういった意味では根拠がどうのこうのかというふうになってしまうと。今ご質問のような、国民健康保険につきましてのいろいろなことについて、ご質問事項が明確になって、後日こちらのほうにご報告するという形でご説明するのであれば、委員会のほうでお決めいただきまして。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ぜひよろしくお願いしたいと思います。そういうところでは、ここの部分をとっても、自治体にとっても本当に大変な医療制度の改革だなというふうに思いますので、自治体のほうからという、最も私たちの預かるところの品川区の国民健康保険財政にも係わるところだというふうなところは、一緒に自治体としても国に対して言っていけるのではないかなというふうに思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"嶋委員","kind":"質問・要望","question":"それと、政府管掌保険の被保険者には低賃金労働者が多いという、今でさえも受診を控えているという、具体的にこういうふうに書かれておりますが、区民の健康促進をしていく立場として、品川区としてのご見解と、あと長期滞納者が増えているということなので、これは後日でいいですので、人数がどういう状況で増えているのか。区民の促進という形で、品川区のご所見をお聞かせいただきたいと思います。","respondent":"新美保健高齢事業部長","answer":"今日の厚生委員会でのご審議等の内容が、個々に関するものがいろいろ具体的、あるいはかなり細部にわたるものであるということでありましたら、また厚生委員長ともご相談をしながら、今後どういう形で私どもが一定の聞き取りでこちらでご報告するのか。","id":"exchange-026"},{"speaker":"伊藤委員","kind":"質問・要望","question":"先ほど課長が日本経済新聞のことで引用して答弁されておりましたけれども、今の日本の医療、福祉、保健の現状というものは極めて高い水準にあるし、先進国の中でも、アメリカは保険がないですから、そういうことからすると、この制度自体を維持していくためにはどうしたらいいかということの議論のほうが、実は国のほうでは重要視されているのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"須藤委員","kind":"質問","question":"ですから、医療制度はどこかで改革しなければいけないだろうというような観点から見ていくと、ここで個々にどうのというお話は分かりますけれども、こういったことも踏まえて、高齢者、あるいは低所得者に対しても配慮しながらの医療制度改革というふうに考えているんだろうと思うので、この趣旨については、なかなか願意に沿い難いというふうに感じます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"４番目のところに、「多くの国民の大変な実態についてご審議を」というんですから、これは相当時間をかけて、大変な実態について詳細な資料等に基づいて把握していかないと結論が出せないと思います。そういうこともあるし、詳細に報告をしていただきたい。その生活の実態というのはどうなのか。生活の実態というのは。私は、もう少し時間をかけてこの請願書は審査すべき案件ではないかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"こういう医療改革の中身が出てきましたけれども、先ほどから低所得者対策というふうなことでも言われておりますが、住民税非課税の方で3,０００円から２万4,６００円というのは、どうやって払っていくんだろうというのが、私の率直な思いなんですが、また、医療制度を存続させるためにどうするのかというふうなところが、ここでは出ていないんじゃないかということで、請願ですから、実態がこうだから。","respondent":"野田口高齢事業課長","answer":"先ほどの補足ということで説明をさせていただきたいと思います。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"受診抑制はわからないということですけれども、１９９７年の医療改悪で１２％の受診抑制がきています。それをさらに、今度は医療にかかれない状況というのをつくっていくということは明らかだと思うので、このところでは、また国民健康保険財政のところからしても大変な実態というのは明らかですから、これは皆さんで出していくというふうな方向でご検討いただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]},{"id":"topic-03","title":"平成１３年請願第１７号、こどもたちひとりひとりの発達を保障するために保育施策の改善を求める請願","agenda":"平成１３年請願第１７号、こどもたちひとりひとりの発達を保障するために保育施策の改善を求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"できれば、今の現状を、ここにはこういうふうに書かれていますけれども、実際にお聞きしたところで審査ができれば、なお審査そのものが深まると思いますので、ぜひ審査の前に意見陳述をお聞きしたいというふうに思いますので、そのことについて諮っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２番目の保育園給食についてお聞きしたいんですけれども、今年の第１回定例会だったと思うんですけれども、保育園給食の民間事業者代行園に栄養士を常駐することを求める陳情というのが出て、このことについて審議していると思うんです。変わっているとしたら、どこがどういうふうに変わっているのかについてお聞かせください。","respondent":"金子保育課長","answer":"この様式については、本年４月から新しいものに定めたわけですけれども、この診断書にきちっと書いてさえいただければ、栄養士もそこには参加しなくても大丈夫なようにはなっておりますが、そこで園長のほうで判断しまして、必要な場合には栄養士も呼んで対応すると。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほどの説明の中で、２番の三つ目の、給食の試食会についてはこれから全園で再開をしたいということで、ご答弁をいただいて、これは親御さんたちの要望に応えていただいてよかったなというふうに思っているんですけれども、ぜひお願いしたいと思います。これは全園でということですが、いつ頃から始まるという方向が出ておりましたら、この時期について教えてください。","respondent":"金子保育課長","answer":"第１点の試食会の再開の時期ですけれども、私どもはこの時期については、全園一斉にやるかどうかということも含めまして慎重に検討をしていきたいというふうに考えております。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このことについてひとつお聞きしたいのと、それから、大豆製品のところで、味噌とか醤油がだめな子どもは味付けは塩だけということになってしまうというふうに書かれているんですけれども、日本食というのは醤油や味噌が中心だと思うんですけれども、そんな中で塩だけというふうなことだと、子どもたちの味覚を育てることもなかなか難しくなってしまうと思うんですが。","respondent":"金子保育課長","answer":"そのようにできる限りということで今後とも対応をさせていただきたいというふうに考えております。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"できる限りは対応していただけるということで、例えば牛乳のかわりにシチューにアレルギー用のミルクを入れてつくっていただくとかというのが、現場でそれはできますということであれば、やっていただくということはできるということで、それから持ち込みというふうなところでも、税金を使うということでなくて、自己負担ということであれば持ち込みというふうなこともやっていただけるということで。","respondent":"金子保育課長","answer":"公費での対応ということがありますので、すべて一から十までという対応については、これは家庭でお願いするしかないというふうに考えております。ですので、私どもとしては、そういった視点に立って、できる限りの対応ということでご理解いただきたいと思います。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"できる限りということで、ぜひ現場のところで頑張ってやるというふうなところがありましたら、そこら辺のところはぜひ子どもの立場に立ってやっていただきたいというふうに要望したいと思います。","respondent":"金子保育課長","answer":"繰り返しになって恐縮ですけれども、先ほどから申し上げたとおり、できる限りの部分で対応しますけれども、できない部分はおのずからあると思います。そこの部分については自宅から弁当を持参いただく等々の方法で対応していただかざるを得ないかなというふうに考えております。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"民間への委託が、今年５園から１０園に増えていますけれども、そういうところで、民間でないところに比べて手がかけられないとか、そういう実態というのがあるんでしょうか。","respondent":"金子保育課長","answer":"私どもでは直営の部分、調理代行の部分ありますけれども、基本的には給食の内容については同じ指示をしているわけで、調理代行だからサービスが低下しても構わないよというような内容の指示は一切しておりませんので、誤解のないようにお願いしたいと思います。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"子どもも一緒に落ちなくてよかったなと思ったんですけれども、その１分前までは下で調理師が片づけをしていたということで、一歩間違えば大惨事になったということで、その窓がどうして落ちたかといったら、すべてストッパーが外れていて、ほかの窓も全部調べたら、すべての窓のストッパーが外れていたということをお聞きして、本当にこれは大惨事にならなくてよかったなというふうに思ったんですが。","respondent":"谷田部児童課長","answer":"これは使い方の問題といたしまして、例えば１階建て、２階建ての部分で、フロアごとにトイレがあった場合には、例えば男性用、女性用というふうにフロアで分けるということで、男女別のトイレにするということも可能ですし、また、どうしても１カ所しか使えないといった場合には。","id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そのほかにも壁がはがれていたりとか、ガムテープが地図のように張りめぐらされているというふうな、ガムテープで補強されているというふうな状況だったんですけれども、そういうところからしても、防球ネットも幼児クラブでプールを下に置くと、そこに錆びがポロポロ落ちて、プールの中に入り込んでくるという状況だったということで、４年くらいこういう状況で、補修の要求を出しているけれども。","respondent":"谷田部児童課長","answer":"ですから、その辺、緊急に対応するところについては、私どもは対応していきたいと思ってありますが、ただ、技術職員が見て、それで、これは１年以内に壊れるとか何とかと予測できれば、それは対応できるんでしょうけれども、なかなか難しい問題もあるというふうに考えてあります。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"中延でもそうだったんですけれども、それは改修されてきれいになってよかったというふうな館長からのお話をお伺いしたんですけれども、北品川が今年度に入っていないというところでは、驚いたんですが、そういうところでぜひ北品川のようなところがそのままにされることなく、予算も、子どもへの予算ですから、もうちょっと要求していただいて、年に１カ所ということで、２５年に一遍ということでなくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"伊藤委員","kind":"質問・要望","question":"我々は予算の執行には賛成する立場で質問をしますので、要望して、反対することは矛盾すると考えています。そのことをまず提起をします。いろいろ新しい保育施策を展開してきたわけですから、これだけ熱心に請願・陳情をなさるんでしたらば、まずそういうことをやったけれどもよかったとか、私はほめて当然だと思います。私は質問の長いのがいいとは思っておりません。それが保育園関係の三つです。","respondent":"谷田部児童課長、金子保育課長","answer":"それで、第２条で言う、「保護者とともに」という考え方ですが、まず第一に、その保護者が児童養育の責任を果たせないということ、いわゆる経済的な理由ですとか、理解不足、うまくいかない場合に、公の機関に相談し。ですが、地域から保育園のほうにお尋ねがあった場合には、当然だと思いますけれども、無下に関係ないから断るということではなくて、きちっとした対応をしていくことが望ましいかなというふうに考えて。","id":"exchange-042"},{"speaker":"伊藤委員","kind":"質問・要望","question":"間違いないかということを確認をお願いしたいのと、「さけび」は労働組合の機関紙でしょうから、そこにそういう文章が載るということは、おそらく関係者の方々が現場の声として「さけび」に載ったということだと私は思います。その事実の確認をまずお願いします。その関係が微妙になってくるし、この請願項目が本当なのかなという気さえしていますので、その確認を改めてお願いいたします。","respondent":"谷田部児童課長","answer":"私のほうで見たんですが、７月３１日付の都職労品川支部の機関紙「さけび」に、第３６回婦人部定期大会が開かれたという中で、代議員として参加した児童センター職場の者の発言の中に、児童センターは何人で運営しているというような下りがありまして。","id":"exchange-043"},{"speaker":"伊藤委員","kind":"質問・要望","question":"確認したいのは、請願項目４番に言われているように、正規職員の増員をする必要があるかということ。それから、今は「さけび」の例ですけれども、ほかの例の中で、逆に、今の体制のままではさまざまなサービス低下が起こっているから、正規職員を増やしてくださいという要望は、この団体からはあったでしょうけれども、ほかのところからはありましたでしょうか、お聞かせください。","respondent":"谷田部児童課長","answer":"１点目の、正規職員の増員の問題ですが、私どもまだまだ見直しは途中だというように思ってあります。平成１０年からいろいろ児童センターを中心とした職員の配置基準等を見直しまして、この３年間運営してまいりました。","id":"exchange-044"},{"speaker":"伊藤委員","kind":"質問・要望","question":"実際保育園を冷静に見ていきますと、夜間、病後児、年末、延長保育、ＩＳＯ取得、非常に全国的に先駆けたアイデアを取り入れて、間違いなく保育の改善がされているわけです。ですから、その裏にはコストも十分考えての品川区の対応があるわけですから、その大きな方向性をぜひ維持していっていただきたいという思いがありますので、そういう方向で進んでいっていただきたいということを意見として述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"鶴副委員長","kind":"意見","question":"今回の請願書を見て、おやっと思ったんですね。１万1,６４８名、参考3,０８４名となっていた事実ですね。ちなみに、この手の署名というのは、秋の大運動ということで、１０万名署名を目指して展開したじゃありませんか。それが始まった期日は忘れましたが、ここ数年の秋になってくる、同種の請願書の、全く同一でなくても、同類項の署名人数はどうなっていますか。分かれば。","respondent":"谷田部児童課長","answer":"ここ数年の署名の数は、私はこの請願には５年間おつき合いをさせていただきましたので、その範囲内でお答え申し上げます。細かい数字は別としまして、平成９年が５万7,５００前後だと思います。","id":"exchange-046"},{"speaker":"鶴副委員長","kind":"意見","question":"なぜこのように署名の数が漸減してきたのかなということは、保育運動自体が勢力が衰えてきたのかなとか、よくわかりませんけれども、分析は。でも、なるほどなというふうに思うような点があるんですよ。それはなぜかというと、６番のところにありましたね。今もちょっと言及されましたけれども、「さけび」の７月３１日の婦人部の定期大会で、この人たちは不満を言っていらっしゃるんじゃないんですよね。","respondent":"谷田部児童課長","answer":"私の関係する児童センター関係の職員の部会からは、毎年のように職員配置基準を見直した定数を復活しろというような要求は私どもにきてあります。","id":"exchange-047"},{"speaker":"鶴副委員長","kind":"質問","question":"職員をつけろと、この２本立てでぐんぐんやってきたんですけれども、現実の納税者の立場から見たら、それは時代遅れの要求であるということが明らかになってきているわけですよ。それをけしからんなんて言っている人はごくわずかな人じゃないですか、労働組合の中でも。労働組合の幹部の中には一人もそんなことを言っている人はいないんじゃないかというふうに思うんですが、その点はどうですか。","respondent":"金子保育課長","answer":"私どもが事業を拡大しているものについて、事業そのものについて否定している意見は聞いたことはございません。","id":"exchange-048"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"今回の１０園で拡充されているわけですけれども、おいしいと子どもたちが言っているんですから、それを、この要求を見ると、何か水準を落としているような、落としていないというふうな説明でしたから、そっちのほうを信用するんですけれども、どういう認識でこういうふうな要求が出てくるのかわからないですよ。「こんなことで子どもの育ちが守れるのでしょうか」と。これは、物申さないんですか。","respondent":"谷田部児童課長","answer":"児童センター・学童保育クラブを含めてという中でのご答弁をします。私どもそのようなことはないというふうに思ってあります。","id":"exchange-049"},{"speaker":"鶴副委員長","kind":"意見","question":"僕も障害児保育等には重大な関心を持って、今までもいろいろ言ってまいりました。もしここに言われていることが著しくしわ寄せがきているというようなことが事実としたら、これは許せないと思ったんです。でも、どうしてこういうことが書かれるのかなと。憤りすら覚えますね。署名が多いから尊重すべきだというような意見も今までありましたよ。ということをひとまず申し述べて、終わりとします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"嶋委員","kind":"質問","question":"ここに書かれているんだから、きっとこの保護者は不安がいっぱいでこういう文章を書かれていると思います。今、副委員長がおっしゃったように、これ全部を見ると、何か品川区全体という形なので、ちょっと私もこれに一つずつお聞きするのも時間がもったいないなと思うので、本当に心配で心配でしようがないならば、１つの園というか、そこの園の中の具体的なものがもっと見えてくるといいのかな。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"保育園の給食試食会というのが書いてありますけれども、私たちも試食をしたことがないので、委員長、ぜひ一遍、本当にまずいのか、子どもたちが言っているように、おいしいなあと。お金を払いますから、そういう試食会をぜひ検討をしていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"船波委員","kind":"質問・要望","question":"特に平成１０年を境に状況が、職員の体制とか、運営の状況が変化したみたいですけれども、それ以前と以後と、子どもたちをどのように過ごさせているか、何をさせているかとか、そういった状況はどういうふうになっているのかお伺いしたいと思います。","respondent":"谷田部児童課長","answer":"保育園も同じような対応をしていると思います。私ども、常にこういう請願で、正規職員の増員という話は毎年出てまいりまして、先ほども私どもの職員の関係の組合も入っているということで、致し方ないのかなというふうに思ってあります。","id":"exchange-053"},{"speaker":"船波委員","kind":"質問","question":"私としては、正規職員だからいい、非常勤だからいやだから、正規職員に代えてほしいというのではなくて、正規だろうが、非常勤だろうが、子どもたちの扱いとか、現実に子どもたちや父母が接する状況のために、何らかその状況を変えてほしいというところではないかと思うので、以前と、現在、どのように子どもたちを学童保育クラブで過ごさせているのかとか。","respondent":"谷田部児童課長、金子保育課長","answer":"障害児１人の場合にはどうするかといいますと、非常勤対応をするということでやっておりました。３年生から４年生に進級しますと、延長児という枠になりまして、障害児の概念から外れてしまいます。先ほど嶋委員がおっしゃっていたとおり、この辺は現況調査の中でも、私どもが大きな反省に立って、できる限りそういった保護者と接する場面では丁寧な対応をし、丁寧な説明を心がけていこうということが一つありますし。","id":"exchange-054"},{"speaker":"船波委員","kind":"質問","question":"学童保育クラブの障害児の扱いについては分かりましたけれども、それでは、障害でない子どもたちに対する扱いというか、サービスというか、どのように過ごさせているんでしょうか。","respondent":"谷田部児童課長","answer":"５時なり６時までお預かりして、時間がくればランドセルを背負って、またご自宅のほうに帰っていただく、そういうような内容になってあります。","id":"exchange-055"},{"speaker":"船波委員","kind":"質問","question":"それが必ずしも正規職員を増やせば、そういった不満が解消するというわけではないと思うので、職員が雇用条件が正規であろうが、非常勤であろうが、子どもたちを適切に遊ばせたり、学ばせたり、情操豊かに過ごさせるということが本当にできているのかどうかということをきちんと考えて、こういった不満が出てこないように、何らかの行動をとるべきではないかと思いますけれども、区が目指していることが。","respondent":"谷田部児童課長","answer":"こういう請願が出て、私どももご説明をしまして、委員の皆さま方に判断をいただいて、結論を出していただくという場でもありますし、また、私どものやっていることが、場合によっては独断先行にならないように、それはいろいろな面でチェックも当然あるわけです。","id":"exchange-056"},{"speaker":"船波委員","kind":"質問","question":"もう一つ、別の点でお伺いしますけれども、請願項目１番の件に関して、区長の諮問機関の児童福祉問題調査会があって、話をしていますということでしたけれども、この諮問機関の児童福祉問題調査会に関して、私は開かれるのが非常に少ないのではないかと思っているんです。ここ数年の間でどういったテーマが諮問されて、どれくらいの回数開かれたのか、お伺いしたいと思います。","respondent":"小沼福祉事業部長、谷田部児童課長","answer":"ただ、現実問題として、私ども児童課のほうの所管で申し上げれば、学童保育クラブと品川区では呼んでおりますけれども、それは放課後終わりまして、基本的には２時間なり３時間、そういうような保育に欠けるお子さんを、正規職員。２点目の児童福祉問題調査会の開催の状況ですが、平成１２年度は２回開いてあります。今年度が５月に１回ということで、平成１２年１２月５日に区長から諮問を受けまして、現在審議をしているところという状況です。","id":"exchange-057"},{"speaker":"船波委員","kind":"質問","question":"そのテーマは何で、どういうことで諮問されているんでしょうか。","respondent":"谷田部児童課長","answer":"「家庭や地域における子育て力の向上と、その方策について」という内容で、区長から諮問があったということで、現在審議中です。","id":"exchange-058"},{"speaker":"船波委員","kind":"質問","question":"平成１２年にそういったことが諮問されて、１２年には２回、今年は１回ということですが、それでは、それ以前の状況をお伺いしたいと思います。","respondent":"谷田部児童課長","answer":"諮問の内容が「今後の少子・高齢社会における児童センターおよび学童保育クラブのあり方」ということで、平成９年に３回、平成１０年に、起草委員会が３回で、調査会が６回開いて、答申をまとめて、答申をいただいたという状況です。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ正規の保育士の人数を増やしていただきたい」、こういう要望がトップに、たくさんの数で挙げられているわけです。そして、認定された子どもが何人いて、審査会に伺ったけれども、認定されなかった子どもがどれぐらいいて、そしてまた、認定はされないけれども、配慮していかなければいけないという方がどれぐらいいて、どういう体制になっているのかということについて、具体的にお聞かせください。","respondent":"小沼福祉事業部長、谷田部児童課長","answer":"一言で言いますと、現在の保育士の質では、現在保育園を取り巻く状況の中で問題となっている諸所の事例にはなかなか対応できない面が、もはや放置できないというようなことが１点ございまして、質の高いサービスと。行った結果を審査会の場で、お子さんの状況等につきまして、それぞれ説明を伺い、それぞれ委員の中で議論をし、入会を認めるか、障害児等として認定するか、障害児等としてでなくて、通常の健常児の扱いとして育成するかという。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それが今そういうのが十分にできないという職員配置の中で、そこがなかなか、もしも部長が質の問題というのであれば、そういう体制の問題からそういうふうになっているんじゃないかなというふうに思うんですけれども、いかがでしょうか。そういうところでぜひ保育の質を高めるというためにも、体制を整えるというところで、今後努力していただきたいというふうに要望します。","respondent":"小沼福祉事業部長","answer":"ご質問というか、要望の点がはっきり類型化できないようなところがあったので、もし私のほうが錯覚していたら申し訳ございませんけれども、一応申し上げておきますと、質の問題云々というところで、先ほど私は申し上げましたけれども、品川区の保育園を取り巻く状況だけでなくて。","id":"exchange-061"},{"speaker":"須藤委員","kind":"提案","question":"この請願について大分質問が出ましたので、内容的にもよく請願内容が分かりましたので、結論を出していただきたいという議事進行の提案をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"船波委員","kind":"質問・要望","question":"いろいろご質問をしたときにも発言いたしましたように、私はこの請願で学童保育クラブについても、保育園についても、求められているように、正規職員を増やすことばかりが解決方法ではない。ほかのもっとやりようがある。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"第１点目の、意見交換ができる公開シンポジウム等を開催してくださいということで、「区議会、町会、商店街、利用者、関係団体等がともに考え」ということで、ここのところについては意見を言う機会がなかったので、今、少子・高齢化というふうなところで、子どもをどう育てるかというのは、地域の中で大きな関心がありますので、その中で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"取り扱いについては、私は、今日ぜひこれを採択をしていただきたいと思います。皆さんが趣旨採択ということでご賛同いただけるなら、趣旨採択という形でも結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"伊藤委員","kind":"意見","question":"請願第１７号につきまして、私どもの会派の意見としては、須藤委員をはじめ述べさせていただきました。今日結論を出すということ、それから、併せて不採択ということでお願いしたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"船波委員","kind":"質問・要望","question":"心身障害者の方への調査についてですけれども、主な調査項目１番から１３番というところを見ますと、例えば１番の(3)では品川区への定住の意向、あるいは４番の(2)就労に関しての就労意向というところで、このアンケートを受ける方々がどういったことを望んでいるかということを調査するというか、アンケートの対象になった方が、そういった願いを表明する場があるのではないかと思うんですけれども。","respondent":"日下部障害者福祉課長","answer":"民生委員の再編成の関係でありますけれども、何が変わるのかですけれども、私ども具体的には、先ほど申し上げました、地域センターとの連携をしっかりとっていくということでございまして、そういった意味では、民生委員の日常活動自体が。","id":"exchange-067"},{"speaker":"伊藤委員","kind":"質問","question":"心身障害児・者の実態調査のことについて２点お伺いいたします。そういうふうな観点でこの設問を見ていきますと、今までの福祉が大きく変わるときなのにもかかわらず、契約に対してのサービスがこう変わるについては、どうなんですかというような設問がないのはなぜなのかなと思いましたので、その二つを教えてください。","respondent":"日下部障害者福祉課長","answer":"これにつきましては、私ども来年度その計画の策定ということで予定をしておりまして、そういった意味では今年度実施をすれば、この調査結果が地域福祉計画の内容として反映できるのではないかと、このように考えております。","id":"exchange-068"},{"speaker":"伊藤委員","kind":"質問・要望","question":"むしろそのほうが皆さんの不安も解消するのではないかということを、ここでは要望しておきますので、検討なさってください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"嶋委員","kind":"質問","question":"それのことに関して触れたそうなんですが、もうそこは無理だというふうに言われたというんですが、ちょっとそこら辺、状況が難しいかと思いますが、もしお分かりだったら、食い違いかもしれませんが、そういう話が出たものですから、お聞きをしたいと思います。分かる範囲で教えていただけたらと思います。","respondent":"日下部障害者福祉課長","answer":"しかるべき時期にその辺は公の場でしっかりとご案内をするという予定になっておりますので、その辺は十分にお伝えいただきたいと思います。","id":"exchange-070"},{"speaker":"須藤委員","kind":"意見","question":"民生委員と児童委員のほうですけれども、民生委員が地区ごとに分けられたんですけれども、この分け方、人数の考え方は、世帯数で考えられたのか、あるいは高齢者の率で考えたのか。それから、児童委員が地区別に分けてくると、先ほどＰＴＡという話があったんだけれども、学校の地区とまた違ってきているんですけれども、この辺の整理はどういうふうにされていくのか。","respondent":"日下部障害者福祉課長、谷田部児童課長","answer":"最初に、民生委員の配置の問題といいますか、これの目安になりますのは、基準が世帯数として示されておりますから、世帯数ということになってまいります。ただ、従前から民生委員は担当地域を持っております。児童委員、主任児童委員も含めて、学校区との関係ですが、私ども児童相談所、学校等の関係機関による協議会でも、その学校区との関係が話題になりまして、児童委員といたしましては、学校区の中に受け持ち区域のある児童委員は。","id":"exchange-071"},{"speaker":"須藤委員","kind":"意見","question":"小学校と連携がとれなくなるよということはないわけですね。どこかには必ず児童委員がひっかかりができてきて、ＰＴＡとの連携とか。というのは、学校によっては分かれてしまうような、こっちの地区でも学校があるけれども、活動はこうだよというようなところが非常にあるので、その辺は整理をしてあげてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-072"},{"speaker":"鶴副委員長","kind":"質問","question":"いずれその人たちを公的住宅に入居させてあげたほうがいいなと思っても、現実に住宅がないという面があります。住宅の改善箇所だけでなくて、そういうものも挿入して、調査していただけないかなという希望があるんですが、どうでしょうか。今後はどういうふうな単位で、１単位なのか、複数の単位で地区ごとに開かれる協議会というのは行われていくのか、そこらあたりを教えていただけませんか。","respondent":"日下部障害者福祉課長","answer":"その辺の活動の範囲といいますか、役割は変わりませんが、地域センターとのつながりの中で積極的な役割が発揮できるような条件を整えようということで進めてまいりたいと、このように考えております。","id":"exchange-073"},{"speaker":"鶴副委員長","kind":"質問","question":"地域福祉に係わっていただくわけですが、守秘義務は課せられていて、変わらないと思うんですが、町会の役員の皆さんと民生委員との連携プレーというか、非常に困っている人たちについては、民生委員の方々も立場上承知をされている。この人も心配だ、いざというときに、どこにどういう人が住んでいるかということについては、町会としても把握しておきたいという気持ちがあるんです。いかがでしょうか。","respondent":"日下部障害者福祉課長","answer":"今ご指摘の点は、民生委員活動を進めていく上で、なかなか難しい問題だということは事実です。","id":"exchange-074"},{"speaker":"嶋委員","kind":"質問・要望","question":"民生委員のことでお尋ねいたします。民生委員、児童委員、主任児童委員とありますが、一番長く民生委員をやっている方の年数と、最高の年齢の方の年齢をお聞きしたいこと。男女に分けて、もし分かりましたら教えていただきたいと思います。","respondent":"日下部障害者福祉課長","answer":"その方につきましては、再任の場合は、民生委員は７３歳まで可能なんです。ですから、もう４０年以上民生委員をやっていらっしゃる。そういう方は承知しております。更新の一斉改選のときの再任でいくと、最長年齢は７３歳ということで切られております。","id":"exchange-075"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"心身障害児・者実態調査のほうですが、先ほど課長のほうから、平成１５年４月からの障害者福祉制度の措置から契約に変わるというふうなところで、現状でどう変わるかということを説明させていただいたというふうに聞いたような思いなんですが、そこら辺のところの中身がどうなるのかというのを、簡単に教えていただけないかということ。","respondent":"日下部障害者福祉課長","answer":"障害者の場合は支援費制度ということで、今までは行政が措置という形で必要な費用の負担をして、それぞれの負担もいただきましたけれども、それが基本的には当事者同士の契約がベースになりますから、当事者同士の費用の負担、ただ。","id":"exchange-076"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その中身が分かったら、委員会の中にもお知らせをいただきたいというふうに要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"船波委員","kind":"質問","question":"これだけ応募が多かった中で、当初４０人だったところを５０人の方に講座を受けていただけることになったものの、その中でも３名の方が最初から欠席ということでしたけれども、その方々はどうしてせっかく受けられることになったのに受けなくなってしまったのか。もし分かっていればお伺いしたいと思います。","respondent":"谷田部児童課長","answer":"ただ、区の講座にしては非常に出席率は高いというふうには思ってあります。４７名のうち、４５名のアンケートなのかというご質問ですが、最終日にアンケート調査をしたところ、４５名の方が最終日に出席されたので、４５名の方の回答しか私どもの手元にないです。","id":"exchange-078"},{"speaker":"船波委員","kind":"意見","question":"最終日に欠席なさった方が、全日欠席した方を除いては２名だったということですけれども、その方は最後はたまたま出られなかったというだけで、例えば今後活動したい意向などについては何らかのことをしたいと思っていらっしゃるのかどうか。そして、そのアンケートに答えなかったからといって、せっかく講座を受けたからには何かしらやっていただけることになっているのかどうか。","respondent":"谷田部児童課長","answer":"何らかの形で応募されて、出席をされているわけですから、私どもも何とかつなぎ止める努力は今後ともしてまいりたいと思ってありますし、子育て関係の資料等も送付するということで、つなぎ止める努力はしていきたいというふうに思ってあります。","id":"exchange-079"},{"speaker":"嶋委員","kind":"質問・要望","question":"私の友人は申し込みをして、補欠でということで、先日行きましたら、また来年２月にあるということもご存じで、来年挑戦しますということで、大変うれしく思いました。区としても、私が知っている限りでは、広報のお知らせ１回のみではなかったと思うんですけれども、そのお知らせだけでこんなにたくさんの方が応募をしてくださったという、区側のほうの思いをお聞かせをいただきたいと思います。","respondent":"谷田部児童課長","answer":"広報紙、特に１面を使わせていただきまして、いわゆるトップ記事で募集をお願いしたわけです。私も講座開催期間中は都合のつく限り聴講をさせていただきまして、毎回受講生の皆さん方から、一口メモという形でご意見、感想等をいただいて、私もすべて目を通したわけです。","id":"exchange-080"},{"speaker":"嶋委員","kind":"質問・要望","question":"未来に希望を感じさせるということでは、私も同じ思いです。第２回講座が開催されますが、定員が決まっているんでしたら、定員もお知らせをいただきたいと考えています。","respondent":"谷田部児童課長","answer":"今回４０名のところを５０名の形でさせていただきましたので、５０名でスタートをしたいというふうに思ってあります。","id":"exchange-081"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひすばらしい内容で開催をしていただきたいと思います。ファミリーサポートセンターができるということで、逆に、お子さんを預けたいというお母さん方の、いわゆる保護者の方の思いもありますが、そういう方たちのお話を聞くと、先ほど児童課長がおっしゃったように、たくさんこういう方がいらっしゃるということで、大変喜んでいらっしゃいます。預ける側の募集はいつ頃から始められていくんでしょうか。","respondent":"谷田部児童課長","answer":"そのように今のところ予定はしています。","id":"exchange-082"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"年末保育についてですが、今回３１日をプラスしてやるということですが、これは要求がどれぐらいあるとかという、そこら辺のところをどう把握されて、どういうことから出てきたのかということを教えていただきたい。","respondent":"金子保育課長","answer":"何点かご質問をいただきましたが、まず、需要動向をどう見たかということですけれども、私ども年末保育に当たってはアンケート調査をしておりまして、実際の数というのは今手元にないんですが、かなりの方が３１日も実施してほしいというご要望を出されていたのは事実です。","id":"exchange-083"},{"speaker":"伊藤委員","kind":"質問・要望","question":"保育の調査のことで、来年度以降のことについて一つだけお話ししておきたいのは、ぜひ検討していただきたいのは、コストですね。保育料をこれだけもらっているけれども、実際税金をこれだけ投入していますよというような設問の仕方をすると、随分イメージが変わってくると思うんです。これは検討してくださいということで、要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"保育園のサービス現況調査ということで、今度全園をやっていくということですけれども、今までは東京都の地域福祉サービスということでやってきたと思うんですけれども、今回も東京都ということでやっていくんでしょうか。","respondent":"金子保育課長","answer":"２点のお尋ねですが、先ほどちょっと説明が漏れましたが、今年度は昨年度実施した質問項目について、東京都の地域福祉サービス検討会で、質問項目その他について精査、検討いたしました。","id":"exchange-085"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/498533?Template=document&Id=3004#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":91740,"voices":222}},{"id":"h13-20011126-8","meetingId":"h13-cm11","date":"2001年11月26日","dateIso":"2001-11-26","committee":"建設委員会","time":"午前１０時０６分～午前１１時４８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"上山委員","kind":"質問・要望","question":"それで、ここの本文には書かれていないんですけれども、私はちょっと別の話を伺ったところによりますと、ほかのところでも、かなりマンションが建つとなるといろんなところでトラブルが住民との間に起きたりとか、この議会でも幾つか請願書に出されたりしていますので、幾つかこの間あったかと思いますけれども、マツヤだけではないと思うんですけれども、特に多いんだみたいな話は聞いたことがあるので。","respondent":"浜脇住環境整備課長","answer":"当然私どものほうに、この開発要綱なり手引き書を見て、それから問い合わせといいますか、まず建築主のほうは来ますから、当然品川区にはこういう開発指導要綱があり、もう一方ではこういう予防条例がありますよということは当然お話をして。","id":"exchange-001"},{"speaker":"上山委員","kind":"質問","question":"ほかのところは余り、直接の問題ではきょうはありませんので、それならそれで余りここでどうのこうの言う必要もありませんけれども、せっかくそういう、ここで全部あれするつもりもないんですけれども、区のほうでそういう指導要綱もつくったりとか、予防条例をかつて制定して、業者にいろいろお話をされたり、最初にこういうふうに相談があったときにもちろんされていると思うんですけれども。","respondent":"浜脇住環境整備課長","answer":"ですから、ここに出てくるというのも困りますけれども、トラブルというか、こういう紛争が入る、かといって、今のものをじゃあ、どういうふうにかえるかということになると、非常に基準法の問題と予防条例の問題。","id":"exchange-002"},{"speaker":"上山委員","kind":"提案","question":"だけれども、住民側はもう少し変えてくれとあったとした場合、そういうここで言っているような事業主の責任で提案するようにというのは、そういう可能性というのはどうなんでしょうか。","respondent":"浜脇住環境整備課長","answer":"それは似たようなものですけれども、この指導、可能性といいますけれども、可能性を、あるとすれば、日ごろからこういうトラブルがあってなかなか、当然私ども説明会の議事録なんかを拝見させてもらいましたら。","id":"exchange-003"},{"speaker":"築舘委員","kind":"質問・要望","question":"ただし、そこで今回はそういう意味で納得ができないということがあるということは、事業主の説明会を５回やったということですが、それが説明会が一方的だったということなんですか、被害を取り除くのがうまくいっていないということなんでしょうけれども、その辺の今回の紛争になったところの具体的な請願項目は、ちょっと具体的じゃないのでよくわかりにくいんですけれども、どういうことを実際は。","respondent":"浜脇住環境整備課長","answer":"図面も見ていただきますけれども、かなりきついといいますか、５階建てですコートハウスのほうから見ても、そちらは道路がないんですけれども、隣地のほうがかなり接近しているというようなことで、やはりそこにお住まいの方から見れば、近づいているという。","id":"exchange-004"},{"speaker":"築舘委員","kind":"意見","question":"この場合、そういう意味ではいろいろプライバシーの侵害、それから採光、日照というようなことでのものは多少あるかと思うんですけれども、その点に関しては、説明においてある程度変更、変更というのは、さっき曇りガラスにしているというようなことではプライバシーの侵害に関する変更をある程度和らげているのかとかいうのがあるかと思いますが、その辺に関しての個別の変更というのは。","respondent":"浜脇住環境整備課長","answer":"第５回の説明会をやって図面を説明しているんですが、それ以降のちょっと議事録が手元にありませんですけれども、議事録自身もちゃんと業者で確認したことをこれから提出するというようなこともありまして、そういった意味では。","id":"exchange-005"},{"speaker":"沢田委員","kind":"提案","question":"ここの請願の文書では、建主のほうは法律を盾に、合法建築だからということで譲歩してくれないと、話し合いに応じてくれないということがかなり出されているのですが、先ほどバルコニーだとか、目隠しの曇りガラス化だとか、何点かの改善提案が向こうから出ているということなんですけれども、区のほうとしてはどうなんでしょうか。","respondent":"浜脇住環境整備課長","answer":"ですから、区のほうでというか、合法なのが合法、あるいは予防条例は予防条例として、こういう指導とか条例に基づいた指導をしていきたいというふうに思っているわけです。","id":"exchange-006"},{"speaker":"沢田委員","kind":"提案","question":"やっぱりきちっとしたほうがいいというふうに思います。それと、あとここに書いてある日照阻害と、それから採光阻害、プライバシーの侵害は、これは皆さんどう感じているのか、ちょっと聞いてはいないんですが、曇りガラスにしたり、目隠しをしたり、バルコニーを小さくしたりという努力はされているんですが、日照阻害と採光阻害の点で、具体的な改善提案は何かなされているんでしょうか。","respondent":"浜脇住環境整備課長","answer":"ですから、そういう意味での日照や採光について、説明をさらにやる必要があるのかなというふうには思っております。","id":"exchange-007"},{"speaker":"沢田委員","kind":"意見","question":"現地を視察したときに近隣の方から言われたんですけれども、隣棟間隔というか、敷地境界から５０センチしか離れていないで建ったら、これは全滅だと。その辺でやっぱり譲歩の余地がないのかどうなのか、業者との間で話し合いがされたかどうか、これはかなり強い要求だと思うので、もしあったらその点を明らかにしてもらえますか。","respondent":"浜脇住環境整備課長","answer":"ですから、それについては、住民のほうからこうした意見があり、それに対して建主側は答えてくれと。答えるというのは、ただ回答をしているというふうに思います。","id":"exchange-008"},{"speaker":"沢田委員","kind":"提案","question":"ずっと提案していますから。最後になりますけれども、区のほうも指導できる限界というのはありながら、やっぱり間に入ってやっているわけですけれども、やっぱり住民が、ある意味では自治というかコミュニティーの問題、地域環境全体の問題ですから、ぜひ一致点を見出せるように、難しい立場は重々わかりますけれども、努力をしていただきたいということを述べて終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"沢田委員","kind":"意見","question":"ちょっと私事で大変恐縮なんですけれども、私自身のマンションが、一つは大崎の再開発で日陰になるという問題がありまして、その隣に三菱地所のマンションと、それからもう一つユニーブルというマンションで、１階部分はもう完全に日陰になっちゃったんですね。ちょっと長くなっちゃって申しわけないんですけれども、ぜひこれを継続して、話し合いを保障するという立場で私は継続を主張します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/791630?Template=document&Id=3706#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":13857,"voices":37}},{"id":"h13-20011126-9","meetingId":"h13-cm11","date":"2001年11月26日","dateIso":"2001-11-26","committee":"文教委員会","time":"午前１０時０５分～午後１２時０８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"桜井委員","kind":"質問・要望","question":"３０人学級の３点目は、今お話があったように、一人ひとりに行き届いたということで、個別学習あるいはさまざまなチームティーチングとか、いろんな手法を入れてやっているわけですけれども、そうした手法の背景というんですか、なぜそういう手法が取り入れられているのか、あるいはそれを継続して拡大していこうとしているのか、その基本的な考え方をお知らせいただきたい。それってわかりますか。","respondent":"青木指導課長、久保田学務課長、鷹倉庶務課長","answer":"１点目の、文部科学省の考え方ということをどのように受けとめているかということだと思いますが、私どもはやはり学習においては。実際に入ったことがあるかということですけれども、私どもはこれは直接教室に入ったことはないのですが。クーラーの３点目の質問で、今後校舎改築していく研究の基本的スタンス、基本的考えはどうかというお話です。","id":"exchange-001"},{"speaker":"桜井委員","kind":"質問・要望","question":"今のクーラーからですけれども、たくましさを期待してクーラーを入れないというのはちょっと区民の皆さんや親の皆さんに言ったら、笑われちゃうんじゃないですか。ちょっと私は……。何ですかと言ったら、自民党の議員さんが質問されたようなんです。だから改めてお聞きしたいのは、小中学校のＰＴＡの連合会から出された冷房化についてのご回答というのはどういうふうにするつもりでしょうか。","respondent":"鷹倉庶務課長、青木指導課長","answer":"生きる力、生き抜いていく力、まさにたくましい力を身につけつつ基礎基本学力をつけていく。その周辺部分としてクーラー云々というものがあるのだと考えています。基本的なねらいというのはそこだというふうに考えております。それから２点目の、教育的な考慮であるというようなお話ですが、私が先ほど申し上げたのは、その内容によって随分と効果が違うのではないかというふうに考えております。","id":"exchange-002"},{"speaker":"桜井委員","kind":"質問・要望","question":"例えば東京都と品川区のそれぞれのかかわり方、例えば品川区で３０人学級以下にしていく場合というふうに例えば東京都に申請した場合に、どういうふうに、例えば手続き上の問題だけでいきますと、考え方ではなくて手続きそのもので、どういうふうに東京都の態度というのはなっていくのでしょうか。雇用問題。具体的に冷房の設備を整えてほしいと。クーラー以外に何か冷房の設備があるのですか。","respondent":"久保田学務課長、鷹倉庶務課長","answer":"区市町村教育委員会は都の基準に従って学級編制を行い、あらかじめ協議してその同意を得なければならないというふうになってございまして。その辺を踏まえまして、具体的な要望に移すのは難しいと、このような形の回答をしていきたいと思ってあります。","id":"exchange-003"},{"speaker":"山路委員","kind":"質問・要望","question":"この請願者は教職員の先生たちだということで、先生の立場として経験をされた理事者の方にちょっとお伺いしたいのですけれど、「いじめや不登校、学級崩壊や低学力の問題など教育困難な状況が続いています」という現状につきまして、こういうものを出してそれが解決するということだけじゃないとは思うんですけれども、現場でとらえることとちょっと違うんじゃないかと私は疑問を持っているんですけれど。","respondent":"青木指導課長","answer":"先だっての本会議でもこちらのほうからご答弁させていただきましたけれども、昨年でもやはり大きく問題になった学級ということで５学級というようなお話をしていますけれども。","id":"exchange-004"},{"speaker":"山路委員","kind":"質問・要望","question":"大体大枠説明いただきましたけれど、教育困難という現場での実例といいますか、もうこれ以上教育ができないというものはどういうものがあったか、あったら聞かせていただきたいんですが。","respondent":"青木指導課長","answer":"その場合には当然学校内の校長を初め、教員などが学級に入って補助的な指導をしていくわけですけれども、そういうような状況が一つ困難な状況というふうに考えられるかと思いますし、また、学校だけではなくて、関係諸機関、例えば教育相談センターとか病院とか。","id":"exchange-005"},{"speaker":"山路委員","kind":"提案","question":"ここの文章の中に言われていることで、補助教員というのは、ちょうど教育長がプラン２１を提案された直後の決算の総括では、私も区独自で補助教員を採用されたらどうかというお話をいたしまして、翌年採用されて、いろんな話をお聞きしましたら、学生で就職についていなくて、補助教員をアルバイトさせてもらったので非常に勉強になっている、また。","respondent":"青木指導課長","answer":"やはりその都度そうした今申しました要件によって変わってくることがあると思いますので、それぞれの学校ではやはりその形、手続き、それから形式、学級の規模ということよりも、やはり一人ひとりの子どもたちをどういうふうに理解し、そして確実な学力を定着させるかと。","id":"exchange-006"},{"speaker":"山路委員","kind":"意見","question":"私も品川区民の一員として、全国の、完璧じゃない、大変問題は全国それぞれあるでしょうけれど、モデル、模範となっている品川区であるということを自覚しながら、より確実に、より将来の子どもたちを国を築いていく人材に育てていかなきゃいけないということを再認識しながら、その辺をどうぞすばらしい教育をお願いして終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問","question":"３０人学級に関して、指導助手の方の今後の配置状況。今年度は今、お話しありましたが、また来年度以降も同じような配置をなさっていくのかどうか。小学校、中学校、どのようなバランスで助手の方が配置されているのか、その２点をまず教えてください。","respondent":"青木指導課長","answer":"小・中ですが、この件につきましても、今年度も小学校が２０、中学校は７というような形で進めておりますが、それぞれの学校の状況と、それから今後の指導方針、方法なども吟味しながら小・中にふさわしいそうした指導助手をつけていきたいというふうに考えております。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問","question":"具体的に言うと、３０人を超えた学級というのは５クラス全部なのか、１校もありませんとかそういう形で、どこというのはいいですけれど、数字的なものを教えていただければと思います。","respondent":"青木指導課長","answer":"先ほどもお話ししましたけれども、五つの学級の数を改めてここで申し上げます。２８人、２校目が２８人、３校目が３０人、４校目が２３人、５校目が２２人です。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"意見","question":"２番目の栄養士さんの関係ですけれど、２校に１人入っていて、その中でこの請願趣旨の下から３行目あたりに「ゆきとどいた栄養教育」という言葉が出てくるんですけれど、請願の中に。その辺の意味がよくわからなかったのですが、教育委員会としてゆきとどいた栄養教育というとどういうニュアンスなのか、２校にお一人で足りるのかどうか、そこら辺のお答えをお願いします。","respondent":"青木指導課長","answer":"給食に対する教育的な考え方というふうにこれを受けとめるべきなのかというふうに思うんですが、それぞれの給食指導というのは、栄養士が直接行う形もありますが、基本的には学級担任がその給食についての指導をしております。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問","question":"一個戻っちゃうんですが、さっき質問があったんですけれど、３０人超の学級が小学校は２６％とさっきおっしゃいましたけれど、ことしの事務事業概要の中で、４１１クラスありますよね。８０ページに出ているんですけれど。今この中に３０人超えていると、３０校ぐらいしか出てこないと思ったんで、パーセンテージじゃなくて、何クラスというので教えてもらっていいですか。","respondent":"久保田学務課長","answer":"これは５月１日段階なので、若干違うかと思いますけれども、４月１日付で４０９クラスで、これで答えさせてもらいますと、まず４０人～３６人の間のクラスが３６学級、それから３５～３１人のクラスが７０学級、それから３０～２６人のクラスが１１４学級。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問","question":"自分が丸付けたのが違ったので、それはわかりました。ただ、全体として、今、山路委員もおっしゃいましたけれど、答弁にも出ている部分もあるなというふうに思っています。非常に疑問を感じるところもあるということで、これで質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"質問で、栄養士の問題なんですけれども、標準法、４校に１校という話なんですけれど、これ何年ごろ決められた話なんでしょうか。それともう一つ、東京都の方で、公立校２校に１校という話、毎年毎年そういうのが出ている。一番初めに出たのは何年ぐらいになるんですか。","respondent":"鷹倉庶務課長","answer":"東京都のほうの方針は、毎年１月ごろに来ます。したがってこれは最新の１３年度東京都公立小中学校教職員定数配当一般方針です。","id":"exchange-013"},{"speaker":"松澤委員","kind":"質問","question":"一番初めに、標準法の４校に１校という話が、東京都、俗に言うところの国基準、都基準という形なんでしょうけれども、２校に１校という話が出たのはいつごろからなんですか。毎年毎年１校と言いながら始めないわけでしょ。","respondent":"鷹倉庶務課長","answer":"２校に１校というのは、私の記憶では昭和５０年の初めぐらいの基準となるかと思います。","id":"exchange-014"},{"speaker":"松澤委員","kind":"質問","question":"おそらくそれに対して東京都も追加ですから、するとそのときぐらいになっているとは思うんですけれど、今のようなコンピュータ化されていない中で栄養士の仕事の本来は栄養献立ですよなんていう話はよくされるんですけれども、こんなにコンピュータ化された中で栄養士の仕事というのは本当にどうなっているのだろうか。ですから、こういう形で増やしてくださいというのは私もおかしいなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"高星委員","kind":"質問","question":"今、松澤委員からちょっと変わって違った話が出たんで、請願したのは労働組合の人たちですから、労働組合は何であるかというのをもうちょっと勉強してもらわないとだめなんであって、そのようなことで……。それで、私、質問なんだけれども、先ほど品川区内でいわゆる教育困難という言葉がどうなのか、なじむかどうかわからないけれども、その前の学級崩壊ということにつながって、品川区で５校ありますよと。","respondent":"青木指導課長","answer":"これは去年のデータですので、卒業してしまったとか、その後担任が変わったということがございましたので。去年のデータです。","id":"exchange-016"},{"speaker":"高星委員","kind":"質問","question":"具体的にどんなことをやられたのですか。具体的にどんな指導をされてきたのか。","respondent":"青木指導課長","answer":"やはり校長や教頭が入ったり、他の教員が入ったりというような、学校のまさに全校体制の中でその学級を再建してきたというような経緯があります。","id":"exchange-017"},{"speaker":"高星委員","kind":"意見","question":"そういうことをやってきているときに、その大事な指導的な立場にある課長、学校の現場の全責任を負う学務課長あたりが、具体的に教育困難なクラスがあります、学級崩壊のクラスが５校ありますなんてこういうふうに言うこと事態が私はふに落ちない、納得しないんだよね。多少のことはあるかもしれないけれど、責任を持って我々はクリアしていますというようなことをなぜ言えないのかと。","respondent":"青木指導課長","answer":"ただ、先ほどの話題になってきましたように、そのまま放置しておくと大変困難になっていくという意味での５学級というような形で示しておりますので、もうこれは手に負えないような状況だというようなことではなくて。","id":"exchange-018"},{"speaker":"高星委員","kind":"質問・要望","question":"そのとおりなんです。だからそうであるべきだというのは当然のことなんだけれど、先ほど言ったように、最高責任者のレベルであたかも揺るがすことでもやっぱり現場の責任を押しつけるみたいな言い方しかないんだと思うんだ、そういう言い方されちゃうと。現場の問題です、みたいなことになって。これはそれぞれ人の考え方も違うだろうから、要望にしておきたいというふうに思います。","respondent":"鷹倉庶務課長","answer":"利便性の裏にいろんな問題が生じてきている。利便性というものを人間がうまく使っていかなければいけない。あったほうがいいのかと言われたら、あったほうがいい。だけれどそれで何か弊害が出てくる。そこを気をつけながらやっていかなきゃいけない、こういうことです。","id":"exchange-019"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"意見があります。栄養士さんのところを少しお伺いしたいと思います。先ほどのご説明の中では、配置されている学校とない学校と特に差は生じていないので、区費による配置は考えていないということだったんですけれども、改めて栄養士さんの役割について基本的なところをお伺いしたいと思うんです。役割と位置づけ、あと仕事の内容についてお話しいただきたいのですが。","respondent":"久保田学務課長","answer":"栄養士の役割ですけれども、給食事務の円滑な執行を図るということで、栄養的な部分についての、例えば献立をつくるとかそういったところにかかわっていただいてやるということが大きな役割の一つです。","id":"exchange-020"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"１週間のうちどういう動きをしているのかとか、今、献立が大きな役割と言いましたけれども、そのほかのところ、子どもとかかわる部分とか、保護者の皆様にいろいろお知らせをするところとか、文書をつくるとか、いろいろ仕事はあると思うんですが、さっき鈴木委員の中では、子どもに対するところは学級担任の仕事だというところがあったんですが、それだけにとどまっているのかどうか。","respondent":"久保田学務課長","answer":"そのほかということであえてお話を申し上げれば、例えば材料品の発注とか、あるいは調理師、調理員との打ち合わせとか、それから今お話があった給食だより等にかかわるというようなこともありますが、主たるものは献立作成ということになってあります。","id":"exchange-021"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"そういった面で、親への食事の重要性を再認識させるような援助がやっぱり今の時代すごい求められていると思うんで、特に子どものところと親への援助のところ、この辺を学校の中での給食の教育的な役割としてどうとらえてどう行っているのかというところが最も私は関心が高いんですけれども、そこのところを教えてください。","respondent":"青木指導課長","answer":"教員はこうした使命を持って子どもに向かっているんだというようなことは私どもいろいろな場面で指導しています。","id":"exchange-022"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"だからその辺で特に、今位置づけられているよりももっと今の時代が求めているもの、栄養士さんを求めているものがあるからこそ、私はこの水準をさらに高めていくのと、ゆきとどいた栄養教育を行うために配置してほしいという声が出ているんだと思うんですけれども、再度そのところをもう一回聞かせていただきたいです。","respondent":"久保田学務課長","answer":"品川区は５８校ありますけれども、それぞれ栄養士さんがいない学校では、それぞれ学校長が中心になりまして、この辺の栄養改善指導を担任を通じて実践的にやっておりますし、そういうことでの反響なりもＰＴＡの方々からもいただいているところですので、いる。","id":"exchange-023"},{"speaker":"飯沼副委員長","kind":"質問","question":"差がないというところで、例えばどういうふうに栄養士さんが動いているのかというのを聞いて、そこをお答えいただいていないんですが、２校を行ったり来たりしていれば差はないと思うんですけれども、私はそこの中でさらにやっぱり学校給食を高めていってほしいということでもっと力を入れてほしいという要求だと受けとめているんですが、栄養士さんの動きをもう一回教えてください。","respondent":"久保田学務課長","answer":"１週間の動きということですけれども、私も全部栄養士さんの状況を見ているわけじゃないのでその辺はあれなんですけれども、先ほどからお話ししているとおり、栄養士さんに主にやっていただいているお仕事というのは献立作成です。","id":"exchange-024"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"３点目の用務さんの仕事についても伺いたいんですけれども、先ほどご説明のところで数的にあまりよくわからなかったんですけれども、全体的にという話で、現在どのぐらい減っているんでしょうか。用務さんです。これは定数のところで出ているからなのでしょうか。ちょっとその辺、どのぐらい減っているのか、もう一回人数的なことと、あと用務さんの仕事内容についてもお伺いしたい。","respondent":"鷹倉庶務課長","answer":"それ以外に、現在この定数に落としたのが、平成１２年度に１１９から７６に落としたわけですけれども、その関係で過員という形で現在退職不補充でやってまいりますけれども、ついてあります。それが小学校７０、中学校３５、１０５です。","id":"exchange-025"},{"speaker":"飯沼副委員長","kind":"意見","question":"定数のところで、用務さんが１名のところが小学校で１０校ありますよね。中学校だと１校なんですけれども。ゆくゆくは過員が解消されていくと、ここは今１名ないし２名のところは現実的にどうなっていくのか、済みません、ちょっと理解が悪いので。","respondent":"鷹倉庶務課長","answer":"今我々も用務さんの仕事のあり方というのを、〔「業務主事」と呼ぶ者あり〕業務主事さんの仕事のあり方というものを、時代の流れも変わってきてありますので、詳細に詰めつつ、基本的には退職不補充という形で。","id":"exchange-026"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"この辺で、品川６で、二日野が３。そういった面でこんなに格差があっていいのかなというのが１点。ここを用務さんのところで１校２名は配置してほしいというような要求も出ているという声も聞いたので、この辺危機管理と合わせて用務さんのさっきの仕事の内容からして１名で果たしてできるのかというあたりを合わせてもう一度質問いたします。","respondent":"鷹倉庶務課長","answer":"ずっと座っているわけじゃないですから。ずっと外にいっぱなしだけでもない。そこはやっぱり組み合わせをうまくやりながらやっていきたいなというのが基本です。","id":"exchange-027"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"私は先日、平塚中学校の周年行事に伺ったらば、校長先生の名札が木でできていたり、花瓶を乗せる花台が用務さんの手作りだったり……。〔「業務主事。用務というのは昔の小使いさん。そういった面でこれ以上削減しないでください、私はこれ切実な声ではないかなと思うんで、ぜひこういう声を受けとめていただきたいなと思って、これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"川西委員","kind":"質問","question":"一つ目の３０人学級と指導助手のことで伺います。ですから指導助手の活用についてなんですが、配置が多い学級だけなのか、２５人ぐらいの少数学級でも低学年でちょっとついていけなかったり、あるいは集団の中で座っていられなかったりというのは、育ちの過程であると思うので、一定期間でも個別指導みたいなことができる位置に指導助手があるのかどうか伺います。ですからそれはどうなっているのか。","respondent":"青木指導課長、鷹倉庶務課長","answer":"ですから、今、委員がご指摘のそうしたなかなか席について学習ができないようなお子さんのことも含めてそれぞれの学校で検討し指導助手をつけているところです。共同作業でやるべきものにつきましては、今後新たに検討して取り組んでいきたいなと、このように考えてあります。基本的な考え方は、当面は退職不補充という形で考えてありますので、よろしくお願いします。","id":"exchange-029"},{"speaker":"松澤委員","kind":"質問・要望","question":"１番目です。今こういう時代ですから、やはりもっともっと見つめ直していただきたいと思います。その意味では区費ですからいいんですが、基本的には都費の事務主事、これがすべて区費の事務主事に取って代わっていただけるのなら、区費の事務主事は各校に１人いるだろうと思うんです。しかも４日前ですのでね。答えが出ちゃっているものをなんでまたするんですかと言うしかないですもんね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"山路委員","kind":"質問","question":"先ほどの質問の中では全般的なことを含めまして、私の体験も含めまして例え話として沖縄の例を出させていただきましたけれど、請願項目の具体的な内容に入りまして、１番は、いい教育に対して数は必要ないと思います。３番、４番に関しましては、自民党さんから言われましたけれど、努力をしていらっしゃるということも含めまして、私も願意に沿いがたいという意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"桜井委員","kind":"質問・要望","question":"それから３点目の事務主事、業務主事の役割というのは本質的にさらに重要だというのは飯沼副委員長が指摘したとおりですからあえて申しませんけれど、やはりこうした危機管理の状況からすれば、やっぱり業務主事さんはぜひ必要だと。だから私も先ほど紹介したように、親の立場から見ても要望も強いし、また、大体３０℃を超えるクラスで三十六、八人がいる、一日学習しているということはかなりきついですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"高星委員","kind":"意見","question":"最初の労働組合の話になるんだけれど、時間の関係もあるので簡単に。それから区とは関係ありませんよという組合もある。いろんな労働組合があるんだよ。その話は終わりまして、今度は扱いについてなんですけれど、どっちにしても、２０日前にこの委員会で同じような似たようなことをやっているんだよ。したがって私はこの請願書についてはやっぱり基本的に願意に沿い難いというふうにしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"川西委員","kind":"質問","question":"ですからこの季節、大根を入れたり、ジャガイモを入れたりするおでんがいかに必要かということを、季節感覚の料理、食を進めない栄養士というのはやっぱり見直してもらいたいというふうに思う一人ですので、２校の１名の配置だって、さっき私が親の指導はそれが仕事ではないというふうに申し上げたけれども、やはり指導をしたいならば、２校に１名が配置されているなら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"桜井委員","kind":"質問・要望","question":"質問ですけれど、この城南、平塚、浜川については、２年保育に欠員がないため１年保育の募集を行わないというこの意味なんですけれど、これで見ると、２年保育、要するに５歳児は行わないとそういう意味ですよね。４歳児は行うけれども、５歳児は行わない。定数は３５ですよね。この辺は現状はどうなんでしょうか。もう少し平塚についての今の現状を知らせていただきたいと思います。","respondent":"久保田学務課長","answer":"最初の１年保育、城南、平塚、浜川については、現在、昨年４歳児の時点で３５名というふうに定員拡大しましたので、そのまま持ち上がりで３５目いっぱいですので、それ以上受け付ける余裕がもうないです。","id":"exchange-035"},{"speaker":"桜井委員","kind":"意見","question":"今、平塚の話を聞いたんですけれど、平塚の４歳児の場合に３５名、当然定数目いっぱいを募集しますよね。じゃなくて、３０名で募集して、そして３５にするんでしたかしら。改正されましたよね。それで一定程度定数の枠を増やすということには時限か何かを切って指導があったというふうに記憶していたんですけれども、要するに３５名ということで平塚幼稚園は来年度の４歳児は可能なのかどうか。","respondent":"久保田学務課長","answer":"５歳児のほうの若干名というのは、先ほどご説明したとおりですので、これはご理解いただいたのかなというふうに思います。４歳児については、当初の募集人員というのは３０名です。","id":"exchange-036"},{"speaker":"桜井委員","kind":"質問","question":"それでこの流れを見ていますと、平成１１年は２８０、１２年は２５２、合わせては５５８、５３２、５４３、これって最近の傾向としてはたぶんふえる傾向にあるんじゃないかなと思うんですけれど、例えば今お話を申し上げた、たまたま平塚ですけれど、城南も３５、浜川も３５で４歳児をやっているんですけれど、これって３５まではほかも例えば希望した場合は可能ですか。定数３５ということで可能なんですか。","respondent":"久保田学務課長","answer":"したがって、急激にふえるということは予想されないわけであります。それから可能性ですけれども、昨年の募集人員が大幅にふえたところについては柔軟な対応をしています。ことしもそのような状況がもしもあれば、同様な配慮はする必要があるだろうというふうには考えております。","id":"exchange-037"},{"speaker":"桜井委員","kind":"質問・要望","question":"意見です。そうすると、幼稚園をもう少し、もう一個ぐらい増やしてほしいというような希望があるかなと思うんですが、そこへ行くとまた私立幼稚園の問題があるし、大変難しいんですが、やはり例えば３５とか近くなった場合には、先ほどの指導助手じゃないけれども、幼稚園にもそういう補助助手を欲しいなという要望だけにとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"意見","question":"個別の幼稚園が出ているんですけれども、二葉幼稚園が９０名から今度６０名に定数を落としていただいているんですけれど、確かに今年度の５月でもほぼ１６しか入っていないから数はわかるんですけれど、これが前の本会議にもちょっと出て、「とどらぁ」との問題に絡んでいるというふうに判断をしていいのか、お答えしていただけるかどうか。","respondent":"久保田学務課長","answer":"それは当然ながら今後の幼稚園を取り巻く新しい課題、大きな課題について考えていくべきじゃないかということから、例えば預かり保育とか、あるいは乳幼児保育などを求める声も大きくなってありますので、その辺の一つの候補地として検討していきたいというふうには考えています。","id":"exchange-039"},{"speaker":"桜井委員","kind":"質問・要望","question":"今、後段の努力したというか、学校での取り組みということで増えたところというのは、去年のいただいた１１月同時点と比べているんですけれども、そこでの比較がちょっと見れないんですけれど、それはどこかの数字で根拠があるんでしょうか。その辺については３年目ということですから、感想的な意見が述べられたんですけれども、もう少し教えていただきたいと思っています。","respondent":"久保田学務課長","answer":"今、多分お持ちの資料は、昨年１１月のたしか２７日ぐらいだと思うんですね。ことしは１１月２２日ってこれ微妙な差なんですけれど、昨年のほうは最終結果に近いものですけれど、ことしはまだまだこれでは言えないというような状況です。","id":"exchange-040"},{"speaker":"桜井委員","kind":"質問","question":"だから第一義的にはそれぞれの学校でのよさというのはあるけれども、基本的な観点として学校、教育委員会としてどういうふうにそこへの指導を援助したのかというところをもうちょっと今後次回の委員会でもいいですから、数字が出たところで、〔「次々回」という声あり〕次々回ぐらい、きちっと聞いておきたいと思いますので、お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"鈴木（真）委員","kind":"意見","question":"数字とか中身の問題じゃなくて、この表として、中学校のときには住民基本台帳による数字が乗っかっていたんですけれど、小学校の場合はなんで乗せてこないのかなとちょっと疑問が……。〔「小学校入れてないんだよ」という声あり〕いや、住民票の数字が……。ちょっとそれが疑問だったので、それをちょっと。","respondent":"久保田学務課長","answer":"ご指摘のとおりのところでございまして、１０月１日現在、２、０１３人ということでお話し申し上げました。実はこの表のつくり方で工夫の余地があると私も思っていますので、次回はその辺の形も出せるような形で。申しわけございませんが。","id":"exchange-042"},{"speaker":"川西委員","kind":"質問","question":"この審議会というのはなかなか私たちのほうには中身が見えてこないのでちょっと伺いますが、例えばこの４年間にどんな議題で委員会が何回ぐらい開かれたでしょうか。","respondent":"上川内生涯学習課長","answer":"審議会の実績ですが、１２年度は３回実施しています。文化財の指定審議として、大島家の文書。大島家というのは、東品川の漁師町の名主さんだそうです。","id":"exchange-043"},{"speaker":"桜井委員","kind":"質問・要望","question":"だから私は、専門職ですから、それは必ずしも一般的にには言い切れないけれども、でもやっぱり最近いろんな女性の研究員って活躍していますよね、世界的にも。だから外国から呼んでこいとは言いませんけれども、やっぱり女性のそういう審議会委員の構成を考えるときに、少なくとも４割に近い努力をいただきたいというふうに思いますけれども、そこら辺１点だけ、いかがでしょうか。","respondent":"上川内生涯学習課長","answer":"まさにそのとおりだと思います。専門の区分ということもございまして、それから前に議会のほうから区内在住の方がいないのかというご要望もあったので、今回、佐藤高先生が品川区在住ということで、もしいい方がいらっしゃいましたら、ご紹介いただきたいと思います。","id":"exchange-044"},{"speaker":"桜井委員","kind":"意見","question":"文化センターで、ちょっとはっきりしないところがあった。センター条例との関係なんですね。センター条例の関係なんです。ちょっと今条例文を持っていないんですけれど、相談業務についてセンター条例の３条か４条かにきちっと書いてあったんですね。私は条例違反じゃないかと指摘したんですけれど、今でもそういうふうに率直に思うんですよ。この辺について、教育次長、お願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/202784?Template=document&Id=4422#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":37244,"voices":114}}]);
